local config = {
  ui_story_5040_50400101_1_dialog_content = "(Ahh... Holidays are hard to come by...)",
  ui_story_5040_50400101_2_dialog_content = "(No, pull yourself together!)",
  ui_story_5040_50400101_3_dialog_content = "\"(Beep) 3 days until <color=#FFB400>Mooncrown Day</color>.\"",
  ui_story_5040_50400101_4_dialog_content = "\"Mooncrown Day is a traditional holiday in Astra. It's a day for couples to express their love, and a popular day for weddings.\"",
  ui_story_5040_50400101_5_dialog_content = "I know already! If I hadn't been so busy that I missed it last year, I wouldn't be—",
  ui_story_5040_50400101_6_dialog_content = "Anyway, I've gotta buy that embossed record player back, the one that Vice and Carleen had their sights set on. That'll be a nice holiday surprise!",
  ui_story_5040_50400101_7_dialog_content = "(They recently said they intended to take a mini-break, and I have no idea where they've gone. Whatever, I'll just have to go get it alone!)",
  ui_story_5040_50400101_8_dialog_content = "PlayerName, it's been a while. Anything I can help you with?",
  ui_story_5040_50400101_9_dialog_content = "Sorry, but the Courier Union is overwhelmed with the festival coming up, so I don't really have time to chat.",
  ui_story_5040_50400101_10_dialog_content = "Not to mention my colleague in the Rediesel Wrench division messed up a bunch of letters heading for Lumopolis...",
  ui_story_5040_50400101_11_dialog_content = "Whoa... Can I help with anything?",
  ui_story_5040_50400101_12_dialog_content = "I want to buy something for the holiday, so I'm taking on odd jobs to earn money.",
  ui_story_5040_50400101_13_dialog_content = "I didn't really want to bug you again, especially since you helped Tweety out last time.",
  ui_story_5040_50400101_14_dialog_content = "But since you asked, there is one thing. Do you think you could swing by the Rediesel Wrench division?",
  ui_story_5040_50400101_15_dialog_content = "An old friend from Northland is getting married on Mooncrown Day, just as a bunch of others are.",
  ui_story_5040_50400101_16_dialog_content = "It's just that his fiancée had a slight accident in the Rediesel Desert a while back, and they're worried there won't be enough time to get to Northland once she's recovered.",
  ui_story_5040_50400101_17_dialog_content = "And you want to borrow the Colossus to ensure she gets there, right? No problem, that's easily done.",
  ui_story_5040_50400101_18_dialog_content = "(Speaking of her friend's wedding, isn't Naroxel gonna go herself?)",
  ui_story_5040_50400101_19_dialog_content = "(Anyway, always best to ask the person involved for the details. This must be the Rediesel Wrench division.)",
  ui_story_5040_50400101_20_dialog_content = "<color=#e8d9bb>Knock, knock—</color>",
  ui_story_5040_50400101_21_dialog_content = "Excuse me...",
  ui_story_5040_50400101_22_dialog_content = "You must be the young Caelestite here to help! I've been expecting you!",
  ui_story_5040_50400101_23_dialog_content = "I thought you'd get here earlier, the way Naroxel always talks about how fast the Colossus is.",
  ui_story_5040_50400101_X23_dialog_content = "(Wh-What a huge snake! Is this thing a Speaker!? It's amazing!)",
  ui_story_5040_50400101_X24_dialog_content = "(And this office... Refined is not usually the Rediesel Wrench style.)",
  ui_story_5040_50400101_24_dialog_content = "(Wow, this office... Refinement is not usually the Rediesel Wrench style.)",
  ui_story_5040_50400101_25_dialog_content = "It's nice to meet you. I'm PlayerName, here on Naroxel's behalf.",
  ui_story_5040_50400101_26_dialog_content = "Who are you guys?",
  ui_story_5040_50400101_27_dialog_content = "You're younger than I imagined. Anyway, let me introduce myself.",
  ui_story_5040_50400101_28_dialog_content = "I'm <color=#FFB400>Jeriah</color>, Senior Member of the Courier Union's Rediesel Wrench Division. This is <color=#FFB400>Tara</color>, our client for this assignment.",
  ui_story_5040_50400101_29_dialog_content = "Hi, I'm Tara! I never expected to meet the legendary Caelestite. What luck!",
  ui_story_5040_50400101_30_dialog_content = "I'm flattered! Are you coming with us to Northland too, Lady Jeriah?",
  ui_story_5040_50400101_31_dialog_content = "Just Jeriah will do. Heheh, there was a mix-up with the mail, and I had no choice but to ask Naroxel for help.",
  ui_story_5040_50400101_32_dialog_content = "So I'll be representing her as a witness to the marriage.",
  ui_story_5040_50400101_33_dialog_content = "(I wonder if she's the colleague Naroxel mentioned who's responsible for the mail kerfuffle?)",
  ui_story_5040_50400101_34_dialog_content = "Witness? I heard that having someone from the Courier Union attend a wedding brings good luck to the newlyweds.",
  ui_story_5040_50400101_35_dialog_content = "Certainly! It wasn't easy to find a courier for a wedding on Mooncrown Day. Naroxel had to call in a favor just for us!",
  ui_story_5040_50400101_36_dialog_content = "Is Naroxel really so busy that she can't get a single day off?",
  ui_story_5040_50400101_37_dialog_content = "The periods just before and just after Mooncrown Day are always the busiest for the Courier Union, with all kinds of invitations and letters flying around.",
  ui_story_5040_50400101_38_dialog_content = "Perfect timing for the lovely Jeriah to \"accidentally\" mess up a bunch of packages bound for Northland.",
  ui_story_5040_50400101_39_dialog_content = "I imagine you invited our Caelestite friend here for more important matters than to make fun of me. Let's get going. Don't you miss your fiance?",
  ui_story_5040_50400101_40_dialog_content = "Good idea. As fast as the Colossus is, we'd better depart as soon as possible.",
  ui_story_5040_50400101_41_dialog_content = "Wow! Your Colossus is so different from the Giant Lizard!",
  ui_story_5040_50400101_42_dialog_content = "Haha, just wait till you get on board.",
  ui_story_5040_50400101_43_dialog_content = "A Desert bride and a Northlander groom is an interesting match, by the way. Are these sorts of cross-country unions common?",
  ui_story_5040_50400101_44_dialog_content = "Hmm, well... I'd say they're pretty rare!",
  ui_story_5040_50400101_45_dialog_content = "The world is a big place and anything is possible. But for Aurorians, it is a little strange.",
  ui_story_5040_50400101_46_dialog_content = "Wow, really?",
  ui_story_5040_50400101_47_dialog_content = "Lad... Jeriah, are you from the Rediesel Desert too?",
  ui_story_5040_50400101_48_dialog_content = "I don't like to admit it, but it's true.",
  ui_story_5040_50400101_49_dialog_content = "It's pretty weird how you're clearly desert born and bred, yet you don't seem to have many friends in the Rediesel Wrench.",
  ui_story_5040_50400101_50_dialog_content = "I had to ask loads of people just to find your office.",
  ui_story_5040_50400101_51_dialog_content = "Well now, everyone walks their own path in life.",
  ui_story_5040_50400101_52_dialog_content = "Anyway, my life story doesn't matter. You're the star of the show today.",
  ui_story_5040_50400101_53_dialog_content = "That's right! I've never met a bride-to-be before!",
  ui_story_5040_50400101_54_dialog_content = "It's not that big of a deal. We desert dwellers are pretty open-minded when it comes to love.",
  ui_story_5040_50400101_55_dialog_content = "Anyway, we don't have a lot of time, so I really wanna look around the Colossus.",
  ui_story_5040_50400101_56_dialog_content = "Take me on tour, PlayerName!",
  ui_story_5040_50400101_57_dialog_content = "Ah, okay. Wait for me!",
  ui_story_5040_50400101_58_dialog_content = "This might sound bad, but Tara doesn't really strike me as very... bride-like.",
  ui_story_5040_50400101_59_dialog_content = "Everyone has their style, little Caelestite. It's not good to gossip behind people's backs.",
  ui_story_5040_50400101_60_dialog_content = "Yeah, I suppose you're right.",
  ui_story_5040_50400101_61_dialog_content = "(Jeriah seems completely indifferent about the wedding...)",
  ui_story_5040_50400101_62_dialog_content = "Phew! We're finally here.",
  ui_story_5040_50400101_63_dialog_content = "Did Tara go off to find her fiance? I remember seeing what looked like a village nearby.",
  ui_story_5040_50400101_64_dialog_content = "Origin Town, on the Northland border. The majority of people there are traditional, and hold their wedding ceremonies in the temple.",
  ui_story_5040_50400101_65_dialog_content = "Should we head there then?",
  ui_story_5040_50400101_66_dialog_content = "I think those two are probably elsewhere right now.",
  ui_story_5040_50400101_67_dialog_content = "(Now that the client's already been dropped off, do I need to stay for the wedding itself??)",
  ui_story_5040_50400101_68_dialog_content = "Are you wondering if you can go back now?",
  ui_story_5040_50400101_69_dialog_content = "(She read me like a book.)",
  ui_story_5040_50400101_70_dialog_content = "Seeing as you're Naroxel's friend, they'll undoubtedly invite you to the wedding.",
  ui_story_5040_50400101_71_dialog_content = "You're already here, after all. While Northland weddings might not be as lively as those in Lumopolis, they certainly have their own character.",
  ui_story_5040_50400101_72_dialog_content = "Good point. By the way, you seem really familiar with Northland for someone who's from the Rediesel Wrench Division.",
  ui_story_5040_50400101_73_dialog_content = "Not just Northland! She knows everything there is to know about the world, except things related to work.",
  ui_story_5040_50400101_74_dialog_content = "Ahaha, you're back! Where's the groom?",
  ui_story_5040_50400101_75_dialog_content = "Tara?",
  ui_story_5040_50400101_76_dialog_content = "Sorry to have kept you waiting...!",
  ui_story_5040_50400101_77_dialog_content = "You really are a slowpoke—",
  ui_story_5040_50400101_78_dialog_content = "This is Jeriah of the Courier Union's Rediesel Wrench Division. I told you about her.",
  ui_story_5040_50400101_79_dialog_content = "And this is the person who got us here! Meet PlayerName, a Caelestite! That Colossus is really something.",
  ui_story_5040_50400101_80_dialog_content = "He's <color=#FFB400>Adonis</color>, my fiance... Eh, it's kinda weird saying that. I usually just use his name.",
  ui_story_5040_50400101_81_dialog_content = "Nice to meet you both, Lady Jeriah, PlayerName.",
  ui_story_5040_50400101_82_dialog_content = "Sorry for the rush today. Naroxel is an old friend of mine from school. She's always there to help in an emergency.",
  ui_story_5040_50400101_83_dialog_content = "If you'd do me the honor of attending, PlayerName, we'd love to have you at the wedding too.",
  ui_story_5040_50400101_84_dialog_content = "Oh yeah, have you been home yet?",
  ui_story_5040_50400101_85_dialog_content = "Er, not yet.",
  ui_story_5040_50400101_86_dialog_content = "You still haven't told them?",
  ui_story_5040_50400101_87_dialog_content = "How long exactly are you planning to drag this out?",
  ui_story_5040_50400101_88_dialog_content = "Only a couple of days! I'll go tomorrow, I promise!",
  ui_story_5040_50400101_89_dialog_content = "And tomorrow it'll be the day after! Tomorrow never comes! Do you even WANT to tell your parents?",
  ui_story_5040_50400101_90_dialog_content = "...",
  ui_story_5040_50400101_91_dialog_content = "(What's going on here?)",
  ui_story_5040_50400101_92_dialog_content = "Looks like we're missing the backstory here.",
  ui_story_5040_50400101_93_dialog_content = "Since the young Caelestite and I have been asked here, shouldn't you let us know what's going on?",
  ui_story_5040_50400101_94_dialog_content = "Hmph. You tell them!",
  ui_story_5040_50400101_95_dialog_content = "... You'll probably find this laughable, but to be honest... we're having a private, secret ceremony.",
  ui_story_5040_50400101_96_dialog_content = "My parents never wanted me to marry Tara.",
  ui_story_5040_50400101_97_dialog_content = "Ah. I see.",
  ui_story_5040_50400101_98_dialog_content = "Marriage between a Northlander and a desert dweller is quite uncommon.",
  ui_story_5040_50400101_99_dialog_content = "I'm serious, I'll tell them this time!",
  ui_story_5040_50400101_100_dialog_content = "And then let's get out of here! We can go to the Rediesel Desert or anywhere else.",
  ui_story_5040_50400101_101_dialog_content = "You mean you're eloping?",
  ui_story_5040_50400101_102_dialog_content = "I'd love it if I could sway my parents, but...",
  ui_story_5040_50400101_103_dialog_content = "But what? You haven't even tried.",
  ui_story_5040_50400101_104_dialog_content = "Is it really that hard for you to speak up for yourself?!",
  ui_story_5040_50400101_105_dialog_content = "I...",
  ui_story_5040_50400101_106_dialog_content = "I'm curious, Adonis, if you've ever left Northland before?",
  ui_story_5040_50400101_107_dialog_content = "N-No. Tara and I met here.",
  ui_story_5040_50400101_108_dialog_content = "Ah! The greenhouse flower wishes to live the life of a wildflower. How courageous.",
  ui_story_5040_50400101_109_dialog_content = "I'm ready! As long as two people stick together, there's nothing that can't be overcome!",
  ui_story_5040_50400101_110_dialog_content = "Really? How about overcoming your inability to tell your parents?",
  ui_story_5040_50400101_111_dialog_content = "Um, sorry to interrupt...",
  ui_story_5040_50400101_112_dialog_content = "I have a package for you, Adonis. You said it was urgent, so I brought it straight over.",
  ui_story_5040_50400101_113_dialog_content = "Why, if it isn't the little Northland bird!",
  ui_story_5040_50400101_114_dialog_content = "L-Lady Jeriah?",
  ui_story_5040_50400101_115_dialog_content = "Thanks for your help sorting out those few letters that were sent here by accident.",
  ui_story_5040_50400101_116_dialog_content = "It was a lot more than a few! Please be more careful next time.",
  ui_story_5040_50400101_117_dialog_content = "<size=33>I never want to have to handle such a nightmarish workload ever again...</size>",
  ui_story_5040_50400101_118_dialog_content = "Thank you, <color=#FFB400>Kya</color>.",
  ui_story_5040_50400101_119_dialog_content = "What's that?",
  ui_story_5040_50400101_120_dialog_content = "Oh yeah, the psychic who sent this potion said to be very careful when using it. Apparently it's pretty potent stuff.",
  ui_story_5040_50400101_121_dialog_content = "Potion? What kind of potion?",
  ui_story_5040_50400101_122_dialog_content = "Oh, er... I'll tell you later.",
  ui_story_5040_50400101_123_dialog_content = "Just tell me now! What's with all your mumbling?!",
  ui_story_5040_50400101_124_dialog_content = "Sigh...",
  ui_story_5040_50400101_125_dialog_content = "It's an <color=#FFB400>all-purpose potion</color> made by a super mystical psychic. It can be used to help change one's mental state in various ways, like boosting bravery.",
  ui_story_5040_50400101_126_dialog_content = "I thought it would give me more confidence when dealing with my parents.",
  ui_story_5040_50400101_127_dialog_content = "(I've never heard of this sort of potion before!)",
  ui_story_5040_50400101_128_dialog_content = "Hah?! What's wrong with you? Do you actually believe that rubbish? Give it here, lemme see.",
  ui_story_5040_50400101_129_dialog_content = "I can't believe there are still suckers falling for psychics these days.",
  ui_story_5040_50400101_130_dialog_content = "We've been together for three years, and you STILL have to rely on some snake oil potion to tell your parents about us?",
  ui_story_5040_50400101_131_dialog_content = "I-I got this to help us!",
  ui_story_5040_50400101_132_dialog_content = "Are you really that much of a coward? Or do you have so little faith in our future?!",
  ui_story_5040_50400101_133_dialog_content = "Adonis, do we seriously need to rely on external strength to maintain our relationship?",
  ui_story_5040_50400101_134_dialog_content = "If you must be this way, maybe it's better to just not—",
  ui_story_5040_50400101_135_dialog_content = "<color=#e8d9bb>Rustle... Rustle...</color>",
  ui_story_5040_50400101_136_dialog_content = "<size=45>Graaagh!</size>",
  ui_story_5040_50400101_137_dialog_content = "<size=45>Graa—!!</size>",
  ui_story_5040_50400101_138_dialog_content = "Eclipsites? Where did they come from?",
  ui_story_5040_50400101_139_dialog_content = "What are Eclipsites doing here?!",
  ui_story_5040_50400101_140_dialog_content = "Well, this is unexpected. How bothersome.",
  ui_story_5040_50400201_1_dialog_content = "<color=#e8d9bb>... Swish!!!</color>",
  ui_story_5040_50400201_2_dialog_content = "Graaah—!",
  ui_story_5040_50400201_3_dialog_content = "Graa—!",
  ui_story_5040_50400201_4_dialog_content = "What's going on? Where are they all coming from?!",
  ui_story_5040_50400201_5_dialog_content = "As annoying as this is, it's best to be cautious.",
  ui_story_5040_50400201_6_dialog_content = "There's something strange about that Eclipsite in the middle.",
  ui_story_5040_50400201_7_dialog_content = "Huff... Huff...",
  ui_story_5040_50400201_8_dialog_content = "Tara! Behind you!",
  ui_story_5040_50400201_9_dialog_content = "Adonis, stay back! Let us handle this!",
  ui_story_5040_50400201_10_dialog_content = "Watch out, Tara! That weird Eclipsite seems to have its sights set on you!",
  ui_story_5040_50400201_11_dialog_content = "Give...",
  ui_story_5040_50400201_12_dialog_content = "Give... me...",
  ui_story_5040_50400201_13_dialog_content = "I want... want...",
  ui_story_5040_50400201_14_dialog_content = "What did you say?!",
  ui_story_5040_50400201_15_dialog_content = "(Is it speaking Universese?)",
  ui_story_5040_50400201_16_dialog_content = "Tara! Get rid of that potion in your hand!",
  ui_story_5040_50400201_17_dialog_content = "Wha—",
  ui_story_5040_50400201_18_dialog_content = "<color=#e8d9bb>Whoosh—Slam!</color>",
  ui_story_5040_50400201_19_dialog_content = "Tara!!",
  ui_story_5040_50400201_20_dialog_content = "This is dangerous. Find cover!",
  ui_story_5040_50400201_21_dialog_content = "<color=#e8d9bb>Splash...</color>",
  ui_story_5040_50400201_22_dialog_content = "Ahhhhh!",
  ui_story_5040_50400201_23_dialog_content = "Huff...! Potion...",
  ui_story_5040_50400201_24_dialog_content = "Grah...",
  ui_story_5040_50400201_25_dialog_content = "Grah! Graaaaah!",
  ui_story_5040_50400201_27_dialog_content = "Did they just take off?",
  ui_story_5040_50400201_28_dialog_content = "There are still a few smaller ones left.",
  ui_story_5040_50400201_29_dialog_content = "Look after your fiancée, Adonis.",
  ui_story_5040_50400202_1_dialog_content = "Finally. Is everyone alright?",
  ui_story_5040_50400202_2_dialog_content = "Tara! Tara!!",
  ui_story_5040_50400202_3_dialog_content = "Oh no! She's out cold!",
  ui_story_5040_50400202_4_dialog_content = "You two, out of the way. Let me take a look.",
  ui_story_5040_50400202_5_dialog_content = "There's no serious wound. It doesn't look like that Eclipsite did her much harm.",
  ui_story_5040_50400202_6_dialog_content = "Just a few scratches.",
  ui_story_5040_50400202_7_dialog_content = "But why would she pass out, then? Could she have hit her head?",
  ui_story_5040_50400202_8_dialog_content = "First and foremost, calm down. She seems fine right now, but we need to get her somewhere safe.",
  ui_story_5040_50400202_9_dialog_content = "Um, she seems to have gotten some of that potion on her.",
  ui_story_5040_50400202_10_dialog_content = "There's nothing bad in it, is there?!",
  ui_story_5040_50400202_11_dialog_content = "I-I don't know! You're the one who wanted it, Adonis! I just delivered it on behalf of that psychic.",
  ui_story_5040_50400202_12_dialog_content = "Don't get yourself worked up. The most important thing right now is to get her somewhere to rest.",
  ui_story_5040_50400202_13_dialog_content = "Yes. I'm sorry for the trouble, everyone. Could we please bring her to my place?",
  ui_story_5040_50400202_14_dialog_content = "Well then, I'm off to finish the rest of my deliveries. Look after Tara, you guys.",
  ui_story_5040_50400202_15_dialog_content = "<color=#e8d9bb>Knock, knock, knock!</color>",
  ui_story_5040_50400202_16_dialog_content = "Adonis? Do you know what time it—",
  ui_story_5040_50400202_17_dialog_content = "What is this? What's happened?!",
  ui_story_5040_50400202_18_dialog_content = "It's a long story, Father. Let us come in first.",
  ui_story_5040_50400202_19_dialog_content = "Are these friends of yours, Adonis? And this girl... Is that Tara?",
  ui_story_5040_50400202_20_dialog_content = "Sorry for the inconvenience.",
  ui_story_5040_50400202_21_dialog_content = "She's hurt, Mother. We ran into some Eclipsites... Can we just get her settled somewhere first? Then I'll tell you the whole story.",
  ui_story_5040_50400202_22_dialog_content = "Eclipsites?! We should have a first-aid kit somewhere. Are there any wounds that need tending to? Are you injured?!",
  ui_story_5040_50400202_23_dialog_content = "There's no cause for alarm. She has a few scrapes and is probably in shock. Everyone else is fine.",
  ui_story_5040_50400202_24_dialog_content = "I'll go take care of her. You guys chat.",
  ui_story_5040_50400202_25_dialog_content = "So, that's what happened...",
  ui_story_5040_50400202_26_dialog_content = "Preposterous!",
  ui_story_5040_50400202_27_dialog_content = "How could you not tell your mother and me about this?",
  ui_story_5040_50400202_28_dialog_content = "If she hadn't been injured, you were just going to elope and then leave Northland?",
  ui_story_5040_50400202_29_dialog_content = "I...",
  ui_story_5040_50400202_30_dialog_content = "I always thought you were a bit dense, but I didn't think you were an outright idiot!",
  ui_story_5040_50400202_31_dialog_content = "Did everything Novio teach you just go in one ear and out the other?!",
  ui_story_5040_50400202_32_dialog_content = "You really think you can get by on your own if you leave Northland? Then fine, go! And never come back!",
  ui_story_5040_50400202_33_dialog_content = "We'll pretend we never had a son!",
  ui_story_5040_50400202_34_dialog_content = "Dad, Ma, please... I-I didn't mean it like that!",
  ui_story_5040_50400202_35_dialog_content = "Save your pathetic excuses, I don't want to hear any of it!",
  ui_story_5040_50400202_36_dialog_content = "Your father's just angry, son.",
  ui_story_5040_50400202_37_dialog_content = "But really, Adonis, we're at our wit's end with you.",
  ui_story_5040_50400202_38_dialog_content = "...",
  ui_story_5040_50400202_39_dialog_content = "Uh...",
  ui_story_5040_50400202_40_dialog_content = "(... Can't say I've witnessed anything like that ever before.)",
  ui_story_5040_50400202_41_option_content = "Comfort Adonis",
  ui_story_5040_50400202_42_dialog_content = "Don't take it to heart. They're just a little upset.",
  ui_story_5040_50400202_43_dialog_content = "I mean, it's normal that they'd get a little emotional, suddenly hearing all this.",
  ui_story_5040_50400202_44_dialog_content = "But they're still your parents. Just talk to them later, and I'm sure everything will work out.",
  ui_story_5040_50400202_45_dialog_content = "Sigh... my parents won't forgive me, and Tara's hurt too.",
  ui_story_5040_50400202_46_dialog_content = "I'm really such a failure.",
  ui_story_5040_50400202_47_dialog_content = "(This isn't good. He seems to be caught in a cycle of negative thinking about himself...)",
  ui_story_5040_50400202_48_option_content = "Ask Jeriah for help",
  ui_story_5040_50400202_49_dialog_content = "What should we do, Jeriah?",
  ui_story_5040_50400202_50_dialog_content = "Huh? What?",
  ui_story_5040_50400202_51_dialog_content = "(Was she spacing out? At a time like this?!)",
  ui_story_5040_50400202_52_dialog_content = "What do you say in these circumstances?",
  ui_story_5040_50400202_53_dialog_content = "This is his problem. It doesn't matter what anyone else says.",
  ui_story_5040_50400202_54_dialog_content = "Anyway, even if you offered a few kind platitudes, it doesn't actually solve anything.",
  ui_story_5040_50400202_55_dialog_content = "(She's not wrong, but surely I can't just say nothing!)",
  ui_story_5040_50400202_56_dialog_content = "(This is so awkward... The atmosphere is so rigid and uncomfortable.)",
  ui_story_5040_50400202_57_dialog_content = "I'm so sorry, guys. I can't imagine what you must think.",
  ui_story_5040_50400202_58_dialog_content = "It's totally fine. Just let us know if there's anything we can do to help.",
  ui_story_5040_50400202_59_dialog_content = "Eh... I've brought all this on myself.",
  ui_story_5040_50400202_60_dialog_content = "You've come such a long way too, and I've been a terrible host.",
  ui_story_5040_50400202_61_dialog_content = "Don't worry about that right now.",
  ui_story_5040_50400202_62_dialog_content = "Why don't you take him out to clear his head, PlayerName? I'll tend to Tara.",
  ui_story_5040_50400202_63_dialog_content = "Okay. Let's go get some fresh air.",
  ui_story_5040_50400202_64_dialog_content = "Sure...",
  ui_story_5040_50400202_65_dialog_content = "...",
  ui_story_5040_50400202_66_dialog_content = "About time you got up, I think.",
  ui_story_5040_50400202_67_dialog_content = "?!",
  ui_story_5040_50400202_68_dialog_content = "How did you know I was awake?",
  ui_story_5040_50400202_69_dialog_content = "That Eclipsite didn't even really attack you.",
  ui_story_5040_50400202_70_dialog_content = "I highly doubted you could've been unconscious for so long.",
  ui_story_5040_50400202_71_dialog_content = "...",
  ui_story_5040_50400202_72_dialog_content = "I'm only here to help Naroxel, so I'm not gonna waste too much time getting involved.",
  ui_story_5040_50400202_73_dialog_content = "This isn't my business anyway.",
  ui_story_5040_50400202_74_dialog_content = "But since I'm doing her a favor, I'll just venture a question. What do you plan to do?",
  ui_story_5040_50400202_75_dialog_content = "I...",
  ui_story_5040_50400202_76_dialog_content = "Honestly? I have no idea. Life in the desert was never such a hassle. I'm so annoyed.",
  ui_story_5040_50400202_77_dialog_content = "I can't deny that Adonis brings me a lot of happiness. But his lack of backbone makes me wonder if I can really marry him.",
  ui_story_5040_50400202_78_dialog_content = "Someone's character is neither formed nor can be changed overnight. You've been together for so long, have you really only discovered this problem now?",
  ui_story_5040_50400202_79_dialog_content = "Of course not.",
  ui_story_5040_50400202_80_dialog_content = "Three years ago, I was attacked by Eclipsites while searching for ruins in Northland. I managed to get away, but fainted by the side of the road.",
  ui_story_5040_50400202_80X1_dialog_content = "He's the one who found me and brought me home.",
  ui_story_5040_50400202_81_dialog_content = "There was heavy snowfall that day too. I don't want to think what could have happened if he hadn't found me.",
  ui_story_5040_50400202_82_dialog_content = "*Sigh* After that, we talked about anything and everything, about things the other hadn't ever seen.",
  ui_story_5040_50400202_83_dialog_content = "We stayed in touch after I returned to the desert, sending letters back and forth.",
  ui_story_5040_50400202_84_dialog_content = "He was so thoughtful and considerate. I'd grown up without parents, and no one had ever shown me that kind of care before.",
  ui_story_5040_50400202_85_dialog_content = "I was really touched.",
  ui_story_5040_50400202_86_dialog_content = "Ah, so that's how it happened.",
  ui_story_5040_50400202_87_dialog_content = "But later on, every time the topic of leaving Northland was brought up, he always seemed hesitant. I feel like he's really changed.",
  ui_story_5040_50400202_88_dialog_content = "He's not like how he used to be. Is it really that difficult for someone to make up their mind?",
  ui_story_5040_50400202_89_dialog_content = "I've never met a man so timid, so indecisive! Does he really even like me?",
  ui_story_5040_50400202_90_dialog_content = "I've been planning our wedding for so long now, and even prepared a very special present. But now... Meh.",
  ui_story_5040_50400202_91_dialog_content = "This probably isn't appropriate, but had you ever been in love before him?",
  ui_story_5040_50400202_92_dialog_content = "Before Adonis? No, he's my first love.",
  ui_story_5040_50400202_93_dialog_content = "Well, no wonder then. You seem to have some unrealistic expectations of him.",
  ui_story_5040_50400202_94_dialog_content = "Love can be a beautiful thing, but you have to respect who someone is too. Each individual is a complicated, nuanced creature; no one is simply black or white.",
  ui_story_5040_50400202_95_dialog_content = "W-What do you mean? I'm not sure I follow.",
  ui_story_5040_50400202_96_dialog_content = "Heheh... Someday, you may understand.",
  ui_story_5040_50400202_97_dialog_content = "...",
  ui_story_5040_50400202_98_dialog_content = "Wait! I've got it! I have an idea!",
  ui_story_5040_50400202_99_dialog_content = "?",
  ui_story_5040_50400202_102_dialog_content = "This is it!",
  ui_story_5040_50400202_103_dialog_content = "I'll just pretend to have amnesia! Start all over again, see how he acts toward me!",
  ui_story_5040_50400202_104_dialog_content = "...",
  ui_story_5040_50400202_105_dialog_content = "Are you serious?",
  ui_story_5040_50400202_106_dialog_content = "Please, I beg you! Help me!",
  ui_story_5040_50400202_107_dialog_content = "If you two aren't going to get married, I should probably get going.",
  ui_story_5040_50400202_108_dialog_content = "Oh, come on! Don't go! What would you say to Naroxel?",
  ui_story_5040_50400202_109_dialog_content = "Are you trying to threaten me?",
  ui_story_5040_50400202_110_dialog_content = "Ah! No, no, of course not! How could I? You've been so kind to me... Please, I'm begging you!",
  ui_story_5040_50400202_111_dialog_content = "Please, do it not just for Naroxel, but for a fellow Rediesel Wrench gal!",
  ui_story_5040_50400202_112_dialog_content = "You sure know how to manipulate people.",
  ui_story_5040_50400202_113_dialog_content = "What a pain.",
  ui_story_5040_50400202_114_dialog_content = "Pleeeaaassee! You're the best!",
  ui_story_5040_50400202_115_dialog_content = "You two need to sort out your own issues. I'm just a bystander.",
  ui_story_5040_50400202_116_dialog_content = "It's on you how your theatrics play out.",
  ui_story_5040_50400202_117_dialog_content = "<color=#e8d9bb>The next day...</color>",
  ui_story_5040_50400202_118_dialog_content = "Good morning, Jeriah, Adonis.",
  ui_story_5040_50400202_119_dialog_content = "Good morning, young Caelestite.",
  ui_story_5040_50400202_120_dialog_content = "Morning. I'm gonna go check if Tara's awake...",
  ui_story_5040_50400202_121_dialog_content = "*Yawns*",
  ui_story_5040_50400202_122_dialog_content = "Tara! You're awake! Are you okay?",
  ui_story_5040_50400202_123_dialog_content = "...?",
  ui_story_5040_50400202_124_dialog_content = "What's wrong? Why're you looking at me like that?",
  ui_story_5040_50400202_125_dialog_content = "Who are you?",
  ui_story_5040_50400202_126_dialog_content = "What are you talking about? Tara?",
  ui_story_5040_50400202_127_dialog_content = "I don't know you. Don't touch me!",
  ui_story_5040_50400202_128_dialog_content = "Where am I? Who are you?",
  ui_story_5040_50400202_129_dialog_content = "I remember coming to Northland yesterday with Jeriah on the Colossus, but... How strange, I can't remember why.",
  ui_story_5040_50400202_130_dialog_content = "This isn't funny, Tara...",
  ui_story_5040_50400202_131_dialog_content = "Not funny at all!",
  ui_story_5040_50400202_132_dialog_content = "Are you alright, Adonis?",
  ui_story_5040_50400202_133_dialog_content = "(Funny, Tara sounds strangely calm, all things considering. Did she say that on purpose?)",
  ui_story_5040_50400202_134_dialog_content = "(I don't really understand affairs of the heart. Things might get worse if I pry, so best not to meddle right now.)",
  ui_story_5040_50400202_135_dialog_content = "This is my fault! All my fault!",
  ui_story_5040_50400202_136_dialog_content = "That wretched potion! I wish I'd never even thought of it!",
  ui_story_5040_50400202_137_dialog_content = "You think the potion's responsible for her amnesia?",
  ui_story_5040_50400202_138_dialog_content = "The psychic said that it was capable of producing all kinds of effects! I can't think of any other reason for this!",
  ui_story_5040_50400202_139_dialog_content = "It's gotta be that. The potion spilled on her, right when she was annoyed with me and wishing she could just forget all about me! So that's what the potion did!",
  ui_story_5040_50400202_140_dialog_content = "It's all my fault!",
  ui_story_5040_50400202_141_dialog_content = "If it really is that, then why not go ask the psychic?",
  ui_story_5040_50400202_142_dialog_content = "There's no point just sitting here crying over spilled milk.",
  ui_story_5040_50400202_143_dialog_content = "Psychic?",
  ui_story_5040_50400202_144_dialog_content = "Yes, you're right! And I just remembered that sometimes they set up a stall in the market!",
  ui_story_5040_50400202_145_dialog_content = "I'll go! I'll go right now!",
  ui_story_5040_50400202_146_dialog_content = "*Panting*... O-Over there!",
  ui_story_5040_50400202_147_dialog_content = "(Wow, he's running so fast...)",
  ui_story_5040_50400202_148_dialog_content = "Hmm? Who might you be?",
  ui_story_5040_50400202_149_dialog_content = "I'm the guy who bought that all-purpose potion! I've got an urgent question for you!",
  ui_story_5040_50400202_150_dialog_content = "Huh...? Oh, yes! That fellow!",
  ui_story_5040_50400202_151_dialog_content = "How was it? I pour my heart and soul into each and every bottle, so I trust the results were as expected?",
  ui_story_5040_50400202_152_dialog_content = "It's a long story, but my fiancée used the potion accidentally, and now she can't remember anything! Please, you have to give me the antidote!",
  ui_story_5040_50400202_153_dialog_content = "Huh?! But that's not possible...",
  ui_story_5040_50400202_154_dialog_content = "Didn't you say it could do anything? Whatever the heart desired?!",
  ui_story_5040_50400202_155_dialog_content = "I-I did say that, yes.",
  ui_story_5040_50400202_156_dialog_content = "But if it's an antidote you seek... I fear that might take some effort.",
  ui_story_5040_50400202_157_dialog_content = "Huh? How come?!",
  ui_story_5040_50400202_158_dialog_content = "Because it's made from something very few people have ever even laid eyes on. Rediesel Desert's rarest treasure, the shimmering scales of the legendary pink sandworm!",
  ui_story_5040_50400202_159_dialog_content = "I'm from the desert myself. How come I've never heard of this before?",
  ui_story_5040_50400202_160_dialog_content = "!",
  ui_story_5040_50400202_161_dialog_content = "Well, tell me... If all you commoners knew about it, would it still be rare?",
  ui_story_5040_50400202_162_dialog_content = "Most people will never even see the mysterious pink sandworm even once in their lives.",
  ui_story_5040_50400202_163_dialog_content = "(I think this psychic is full of it. And who would even want to see such a thing anyway?)",
  ui_story_5040_50400202_164_dialog_content = "Its scales shimmer with all the colors of the rainbow, while its pink body is as magnificent and dazzling as the most beautiful shell!",
  ui_story_5040_50400202_165_dialog_content = "If you insist on this antidote, it cannot be done without some of its scales. Perhaps you should think of how to get some!",
  ui_story_5040_50400202_166_dialog_content = "Y-You're intentionally making things difficult, aren't you?!",
  ui_story_5040_50400202_167_dialog_content = "Hey, I'm not the one who wants the antidote. I've told you in good faith, now leave me be. I don't want you affecting my business.",
  ui_story_5040_50400202_168_dialog_content = "...",
  ui_story_5040_50400202_169_dialog_content = "That's it. It's over.",
  ui_story_5040_50400202_170_dialog_content = "I'm willing and able to do whatever it takes, but fighting a sandworm...? Impossible.",
  ui_story_5040_50400202_171_dialog_content = "Even the worms in my garden terrify me. There's no way I can go looking for a desert sandworm!",
  ui_story_5040_50400202_172_dialog_content = "You know... I don't often meet men with as little backbone as you.",
  ui_story_5040_50400202_173_dialog_content = "(Please don't make this worse!)",
  ui_story_5040_50400202_174_dialog_content = "Look on the bright side. At least she's alive and healthy, and from what I understand has just lost her memory of your relationship.",
  ui_story_5040_50400202_175_dialog_content = "Instead of going on some wild goose chase, maybe it's better to think about how to rekindle that romantic fire.",
  ui_story_5040_50400202_176_dialog_content = "And anyway, she hasn't forgotten everything. As long as she's alright, then there's still a chance.",
  ui_story_5040_50400202_177_dialog_content = "There must have been a reason that you two were together for so long. I don't think it should be too difficult to start over, as it were.",
  ui_story_5040_50400202_178_dialog_content = "Yes... I suppose you're right.",
  ui_story_5040_50400202_179_dialog_content = "The thing is, I don't have the faintest idea where to start. She sees me as a total stranger.",
  ui_story_5040_50400202_180_dialog_content = "By the way, I'm sure you both remember that I was sent here for the wedding on Naroxel's behalf.",
  ui_story_5040_50400202_181_dialog_content = "Loads of people get married on Mooncrown Day, and most of them want a courier to attend their wedding.",
  ui_story_5040_50400202_182_dialog_content = "I've heard of that tradition. Apparently, having a courier at your wedding can bring happiness and hope.",
  ui_story_5040_50400202_183_dialog_content = "Spot on. That's why the Union has been holding special Mooncrown Day events in recent years, aimed at newlyweds and couples.",
  ui_story_5040_50400202_184_dialog_content = "It also helps to relieve some of the pressure on the couriers. It's one of the busiest times of the year, after all.",
  ui_story_5040_50400202_185_dialog_content = "Really? I never knew that.",
  ui_story_5040_50400202_186_dialog_content = "Right, that's obvious, because they're aimed at couples. I highly doubt they'd be on the radar of perpetual singles.",
  ui_story_5040_50400202_187_dialog_content = "Hey!",
  ui_story_5040_50400202_188_dialog_content = "What're you getting at?",
  ui_story_5040_50400202_189_dialog_content = "In quite a few places, this event has already replaced the custom of couriers attending the wedding as a lucky blessing for happy couples.",
  ui_story_5040_50400202_190_dialog_content = "Each branch has its own event, and those who experience it with success receive the Courier Union's Feather Seal.",
  ui_story_5040_50400202_191_dialog_content = "You should consider attending one of these events with Tara. You'd get to check out the outside world while you're at it.",
  ui_story_5040_50400202_192_dialog_content = "You mean... leave Northland?",
  ui_story_5040_50400202_193_dialog_content = "Amnesiacs can often have past memories stirred via external events. That's actually an old folk remedy.",
  ui_story_5040_50400202_194_dialog_content = "All I'm saying is that the Courier Union event might be a great opportunity. What you do with it, if anything, is up to you.",
  ui_story_5040_50400202_195_dialog_content = "You won't achieve much by shutting yourself away and worrying at home. If you don't go out and see the world, how will you know if there's a solution?",
  ui_story_5040_50400202_196_dialog_content = "It's none of my business, but who's to say you might not discover some way to get her memories back by going out and traveling around?",
  ui_story_5040_50400202_197_dialog_content = "I agree!",
  ui_story_5040_50400202_198_dialog_content = "I also spent a long time by myself in solitude before. Everything I knew about the world was taught to me.",
  ui_story_5040_50400202_199_dialog_content = "It was only when I got out that I realized the wider world held so much I knew nothing about.",
  ui_story_5040_50400202_200_dialog_content = "If you go out and explore, you might jog Tara's memories and learn more about her condition!",
  ui_story_5040_50400202_201_dialog_content = "Guys...!",
  ui_story_5040_50400202_202_dialog_content = "Actually, I... um, I don't really know what to say.",
  ui_story_5040_50400202_203_dialog_content = "I'm grateful to you for helping me think of ideas. Right now, Tara's condition is the only thing I can think about.",
  ui_story_5040_50400202_204_dialog_content = "You're right! I believe in our love. Whatever we've lost can be found again!",
  ui_story_5040_50400202_205_dialog_content = "...",
  ui_story_5040_50400202_206_dialog_content = "...",
  ui_story_5040_50400202_207_dialog_content = "That's what I'm thinking!",
  ui_story_5040_50400202_208_dialog_content = "I know you might not agree, but...",
  ui_story_5040_50400202_209_dialog_content = "Off you go then.",
  ui_story_5040_50400202_210_dialog_content = "Huh?",
  ui_story_5040_50400202_211_dialog_content = "If you two come back from your travels and still wish to have a life together, well... we could give it some serious consideration.",
  ui_story_5040_50400202_212_dialog_content = "R-Really?!",
  ui_story_5040_50400202_213_dialog_content = "I can't believe it! Mother, Father, thank you so much!",
  ui_story_5040_50400202_214_dialog_content = "Just remember you've never been out of Northland before. It's a dangerous world out there, so you have to be extra careful.",
  ui_story_5040_50400202_215_dialog_content = "<size=33>What's with their sudden change of heart, Jeriah?</size>",
  ui_story_5040_50400202_216_dialog_content = "I wonder...",
  ui_story_5040_50400202_217_dialog_content = "Might I have a word with you, sir?",
  ui_story_5040_50400202_218_dialog_content = "Hmm? Who're you?",
  ui_story_5040_50400202_219_dialog_content = "I'm Jeriah, a senior member of the Courier Union.",
  ui_story_5040_50400202_220_dialog_content = "Oh. Can I help you with something? If it's to do with that ungrateful bratty son of—",
  ui_story_5040_50400202_221_dialog_content = "I totally understand how you feel.",
  ui_story_5040_50400202_222_dialog_content = "All parents want is for their children to be happy. Your worries perhaps stem from the fear that he's too naive and childish.",
  ui_story_5040_50400202_223_dialog_content = "Someone who's never left his home, suddenly wanting to live the romantic, wandering life.",
  ui_story_5040_50400202_224_dialog_content = "I don't think I'd be able to accept it, either.",
  ui_story_5040_50400202_225_dialog_content = "It is as you say. Nothing in life is that easy!",
  ui_story_5040_50400202_226_dialog_content = "Adonis studied under the tutelage of Mr. Novio as a child. He's attentive and intelligent, just a little too naive.",
  ui_story_5040_50400202_227_dialog_content = "He hasn't experienced much, so he has a tendency to see the world through rose-colored glasses.",
  ui_story_5040_50400202_228_dialog_content = "Then, what about letting him have an opportunity to experience things?",
  ui_story_5040_50400202_229_dialog_content = "The longer the fledgling stays in the nest, the less ability it has to survive on its own.",
  ui_story_5040_50400202_230_dialog_content = "Those who aren't as strong as others will never actively seize happiness, only passively receive it.",
  ui_story_5040_50400202_231_dialog_content = "It doesn't really matter where they go, or with whom.",
  ui_story_5040_50400202_232_dialog_content = "You seem like a sensible father. What do you think?",
  ui_story_5040_50400202_233_dialog_content = "I don't know what you said, but as long as everything works out.",
  ui_story_5040_50400301_1_dialog_content = "Letter for you! Here you go!",
  ui_story_5040_50400301_2_dialog_content = "Thank you, Kya. How come you're working so late?",
  ui_story_5040_50400301_3_dialog_content = "The festival's just around the corner. I hope I can just deliver more, as I'm sure people are anxiously waiting.",
  ui_story_5040_50400301_4_dialog_content = "Rookies are always the hardest-working. All the best to you!",
  ui_story_5040_50400301_5_dialog_content = "Phew, it's so late.",
  ui_story_5040_50400301_6_dialog_content = "All delivered, at last. I guess I'll call it a day today.",
  ui_story_5040_50400301_7_dialog_content = "(This afternoon I heard Adonis say that Tara got amnesia... Could it be related to yesterday's Eclipsite attack?)",
  ui_story_5040_50400301_8_dialog_content = "(It's worrying. Maybe I should go back to where it happened and look around.)",
  ui_story_5040_50400301_9_dialog_content = "(I think it was right around here.)",
  ui_story_5040_50400301_10_dialog_content = "Eh?",
  ui_story_5040_50400301_11_dialog_content = "Why is it purple here? Is it because of that potion?",
  ui_story_5040_50400301_12_dialog_content = "And there seem to be purple tracks heading into the woods.",
  ui_story_5040_50400301_13_dialog_content = "Well, I'd better check it out.",
  ui_story_5040_50400301_14_dialog_content = "<color=#e8d9bb>Caw, caw—</color>",
  ui_story_5040_50400301_15_dialog_content = "(It's so dark! Maybe I should head back instead. This is kinda scary.)",
  ui_story_5040_50400301_16_dialog_content = "Hang on... The tracks just finish here?",
  ui_story_5040_50400301_17_dialog_content = "Ah...",
  ui_story_5040_50400301_18_dialog_content = "<size=50>Aaaaaah!</size>",
  ui_story_5040_50400301_19_dialog_content = "Who's there?!",
  ui_story_5040_50400301_20_dialog_content = "H-Help...",
  ui_story_5040_50400301_21_dialog_content = "Help... me...",
  ui_story_5040_50400301_22_dialog_content = "W-Who's talking?!",
  ui_story_5040_50400301_23_dialog_content = "Me... Me!",
  ui_story_5040_50400301_24_dialog_content = "An E-Eclipsite?!",
  ui_story_5040_50400301_25_dialog_content = "N-No... Don't...",
  ui_story_5040_50400301_26_dialog_content = "I... No... Harm...",
  ui_story_5040_50400301_27_dialog_content = "What? Is that Universese? But you're the Eclipsite that attacked Tara yesterday!",
  ui_story_5040_50400301_28_dialog_content = "I... No... Hurt... You...",
  ui_story_5040_50400301_29_dialog_content = "Stay back! What are you doing?",
  ui_story_5040_50400301_30_dialog_content = "Please... You...",
  ui_story_5040_50400301_31_dialog_content = "Help... me...",
  ui_story_5040_50400301_32_dialog_content = "What did you say?",
  ui_story_5040_50400301_33_dialog_content = "My... memory... is gone...",
  ui_story_5040_50400301_34_dialog_content = "I... forgot... who... am I...",
  ui_story_5040_50400301_35_dialog_content = "Scared...",
  ui_story_5040_50400301_36_dialog_content = "Very... scared...",
  ui_story_5040_50400301_37_dialog_content = "You don't know who you are? Then why did you attack us yesterday?",
  ui_story_5040_50400301_38_dialog_content = "I... Not... Attack...",
  ui_story_5040_50400301_39_dialog_content = "Want... potion...",
  ui_story_5040_50400301_40_dialog_content = "Potion?",
  ui_story_5040_50400301_41_dialog_content = "I... hide... market...",
  ui_story_5040_50400301_42_dialog_content = "Hear... potion... powerful...",
  ui_story_5040_50400301_43_dialog_content = "Want... use... restore... memory...",
  ui_story_5040_50400301_44_dialog_content = "But... they... took...",
  ui_story_5040_50400301_45_dialog_content = "So that's what happened.",
  ui_story_5040_50400301_46_dialog_content = "But how could an Eclipsite have memories? Could you have once been an Aurorian?",
  ui_story_5040_50400301_47_dialog_content = "Think... so... but... forgot...",
  ui_story_5040_50400301_48_dialog_content = "I'm... scared...",
  ui_story_5040_50400301_49_dialog_content = "(Everyone despises Eclipsites, but it doesn't seem to be lying...)",
  ui_story_5040_50400301_50_dialog_content = "(If anyone finds out I'm helping an Eclipsite, I'll definitely lose my job as a courier. I could even be arrested.)",
  ui_story_5040_50400301_51_dialog_content = "Cold...",
  ui_story_5040_50400301_52_dialog_content = "It is!",
  ui_story_5040_50400301_53_dialog_content = "Alright. Come on then.",
  ui_story_5040_50400301_54_dialog_content = "Thank...!",
  ui_story_5040_50400301_55_dialog_content = "Just so we're clear, any funny business and I'm alerting the Speaker!",
  ui_story_5040_50400301_56_dialog_content = "Yes!",
  ui_story_5040_50400301_57_dialog_content = "Right, so what now...?",
  ui_story_5040_50400301_58_dialog_content = "Hide here a little while longer.",
  ui_story_5040_50400301_59_dialog_content = "Yep, this should work!",
  ui_story_5040_50400301_60_dialog_content = "Can... I...?",
  ui_story_5040_50400301_61_dialog_content = "Are you sure you want to wear this? It's my old bridesmaid dress.",
  ui_story_5040_50400301_62_dialog_content = "You kinda look like an Aurorian in it, even though the dress stands out a bit.",
  ui_story_5040_50400301_63_dialog_content = "Thank... You... Dress... Good...",
  ui_story_5040_50400301_64_dialog_content = "Never mind. You can wear it if you like it. My name's Kya, by the way. What should I call you in public? Do you remember your name?",
  ui_story_5040_50400301_65_dialog_content = "Don't... know...",
  ui_story_5040_50400301_66_dialog_content = "I guess I'll call you Sable for now, then. How's that?",
  ui_story_5040_50400301_67_dialog_content = "O... Okay...",
  ui_story_5040_50400301_68_dialog_content = "You really don't remember anything at all?",
  ui_story_5040_50400301_69_dialog_content = "No...",
  ui_story_5040_50400301_70_dialog_content = "Have you always been in Northland?",
  ui_story_5040_50400301_71_dialog_content = "No... I think... come from... far away...",
  ui_story_5040_50400301_72_dialog_content = "Hmm, okay. Let me think.",
  ui_story_5040_50400301_73_dialog_content = "<color=#e8d9bb>The next day—</color>",
  ui_story_5040_50400301_74_dialog_content = "All ready?",
  ui_story_5040_50400301_75_dialog_content = "You guys are going on a long journey. Make sure you've got everything you need.",
  ui_story_5040_50400301_76_dialog_content = "Yep! We've got enough canned herring, venison, and shark meat to last at least a month.",
  ui_story_5040_50400301_77_dialog_content = "As for dried goods, we have freeze-dried seal, shrimp, and fish enough for two months.",
  ui_story_5040_50400301_78_dialog_content = "Then, in case of emergencies, there's a portable stove, a ten-pound hammer, knives, a shovel, kettle, boots, raincoats...",
  ui_story_5040_50400301_79_dialog_content = "Hold on a second. You are going to Lumopolis, right? And not to survive in the wilderness of the Secret Territory?",
  ui_story_5040_50400301_80_dialog_content = "Surely that's a little over-the-top? What sort of place do you think Lumopolis is?",
  ui_story_5040_50400301_81_dialog_content = "We're visiting Lumopolis, Gannon City, and the Rediesel Desert on this trip. I want to be as prepared as possible.",
  ui_story_5040_50400301_82_dialog_content = "That's the right idea, but think about what you'll actually use. It's not like you could starve in any of the places you're going.",
  ui_story_5040_50400301_83_dialog_content = "...",
  ui_story_5040_50400301_84_dialog_content = "What? Traveling? With a stranger?!",
  ui_story_5040_50400301_85_dialog_content = "Calm down, Tara. It's a trip, but we're really hoping it'll help you recover your memory.",
  ui_story_5040_50400301_86_dialog_content = "Surely you want to remember?",
  ui_story_5040_50400301_87_dialog_content = "Of course I do, but this is insane.",
  ui_story_5040_50400301_88_dialog_content = "And anyway, I've only forgotten things related to you.",
  ui_story_5040_50400301_89_dialog_content = "You say that, but our memories together are important to both you and me.",
  ui_story_5040_50400301_90_dialog_content = "Mmm...",
  ui_story_5040_50400301_91_dialog_content = "I respect your opinion, of course I do, but I really want to at least try to get your memory back by traveling.",
  ui_story_5040_50400301_92_dialog_content = "What do you think? I won't force you to go if you really don't want to.",
  ui_story_5040_50400301_93_dialog_content = "(Oh boy, can't believe we're going to do this. Why am I such a softie?)",
  ui_story_5040_50400301_94_dialog_content = "Relax, Tara. I'll look after you! There's nothing to worry about!",
  ui_story_5040_50400301_95_dialog_content = "Your job on this trip is to have fun!",
  ui_story_5040_50400301_96_dialog_content = "I don't even know who you are. Don't think you can just be nice to me and I'll be moved or something.",
  ui_story_5040_50400301_97_dialog_content = "I want to go home.",
  ui_story_5040_50400301_98_dialog_content = "I'll take you home. Our last stop is the desert.",
  ui_story_5040_50400301_99_dialog_content = "We'll just have some fun along the way! And in the meantime, we'll think of ways to jog your memory.",
  ui_story_5040_50400301_100_dialog_content = "Fine. Whatever.",
  ui_story_5040_50400301_101_dialog_content = "Well then, if you're all set, then it's time to go. I'll take you to Lumopolis, as I need to be reporting back to Naroxel anyway.",
  ui_story_5040_50400301_102_dialog_content = "PlayerName! Wait!",
  ui_story_5040_50400301_103_dialog_content = "Huh?",
  ui_story_5040_50400301_104_dialog_content = "*Pant* Phew, I'm glad I caught up!",
  ui_story_5040_50400301_105_dialog_content = "If it isn't the little Northland bird! So cute, even when you're out of breath.",
  ui_story_5040_50400301_106_dialog_content = "Please don't tease me, Lady Jeriah! So, um... I heard you're all going to Lumopolis. Could you take us too?",
  ui_story_5040_50400301_107_dialog_content = "\"Us\"?",
  ui_story_5040_50400301_108_dialog_content = "Could she possibly be referring to this odd individual that looks suspiciously like an Eclipsite?",
  ui_story_5040_50400301_109_dialog_content = "Y-You can't just tell someone they look like an Eclipsite!",
  ui_story_5040_50400301_110_dialog_content = "This is my, uh, distant relative! She's called Sable.",
  ui_story_5040_50400301_111_dialog_content = "H-Hello... Everyone...",
  ui_story_5040_50400301_112_dialog_content = "(I'm absolutely sure this Sable is giving off serious Darkflow...)",
  ui_story_5040_50400301_113_dialog_content = "(But no other alarm bells are ringing. Best to wait and see.)",
  ui_story_5040_50400301_114_dialog_content = "A little blackbird, huh? Interesting outfit you have on.",
  ui_story_5040_50400301_115_dialog_content = "S-Sable likes formalwear! She doesn't get out much, so she wanted to dress up a little.",
  ui_story_5040_50400301_116_dialog_content = "(For some inexplicable reason, she seems to really like that dress. Like, a lot. Could it be some weird fetish?)",
  ui_story_5040_50400301_117_dialog_content = "And you guys want to go to Lumopolis too?",
  ui_story_5040_50400301_118_dialog_content = "I want to show her around during the festival. Can you take us with you, please? I also happen to have some letters I need to deliver to Lumopolis.",
  ui_story_5040_50400301_119_dialog_content = "Of course! If you're all set, we can go right now.",
  ui_story_5040_50400301_120_dialog_content = "<color=#e8d9bb>Soroz</color>",
  ui_story_5040_50400301_121_dialog_content = "Aren't you going to get some rest, Jeriah?",
  ui_story_5040_50400301_122_dialog_content = "Hehe... Reading is rest for me.",
  ui_story_5040_50400301_123_dialog_content = "And I'm not tired.",
  ui_story_5040_50400301_124_dialog_content = "Go get some sleep if you're tired, little Caelestite.",
  ui_story_5040_50400301_125_dialog_content = "Wow, that's impressive. I can't even understand what you're reading.",
  ui_story_5040_50400301_126_dialog_content = "We each have our interests. I enjoy reading ancient texts.",
  ui_story_5040_50400301_127_dialog_content = "It's much more relaxing than dealing with Aurorians.",
  ui_story_5040_50400301_128_dialog_content = "Huh?",
  ui_story_5040_50400301_129_dialog_content = "By the way, when we get to Lumopolis, are you gonna go find Naroxel?",
  ui_story_5040_50400301_130_dialog_content = "We still have things to do; I'll go talk to her first once we get there.",
  ui_story_5040_50400301_131_dialog_content = "Aaaah!!",
  ui_story_5040_50400301_132_dialog_content = "?!",
  ui_story_5040_50400301_133_dialog_content = "Eclipsites! Lady Jeriah, PlayerName, watch out!",
  ui_story_5040_50400301_134_dialog_content = "Help... me...!",
  ui_story_5040_50400301_135_dialog_content = "How did Eclipsites get on board? Did they follow someone in?",
  ui_story_5040_50400301_136_dialog_content = "We can talk about that later. Let's deal with those unsightly things first.",
  ui_story_5040_50400302_1_dialog_content = "<color=#e8d9bb>After dealing with the Eclipsites, everyone manages to rest. They arrived safe and well in Lumopolis...</color>",
  ui_story_5040_50400302_2_dialog_content = "Phew, that was a strict customs inspection, but fortunately, they didn't make things too difficult.",
  ui_story_5040_50400302_3_dialog_content = "(If the Caelestite hadn't vouched for us, Sable's cover would have been blown. Thank goodness we were able to tag along to get into the city.)",
  ui_story_5040_50400302_4_dialog_content = "PlayerName! Lady Jeriah! I'm gonna show my relative around the city, and deliver some letters while I'm at it! See you later!",
  ui_story_5040_50400302_5_dialog_content = "She just took off!",
  ui_story_5040_50400302_6_dialog_content = "...",
  ui_story_5040_50400302_7_dialog_content = "Wow... So this is Lumopolis! It certainly has quite a different vibe.",
  ui_story_5040_50400302_8_dialog_content = "What do you think, Tara?",
  ui_story_5040_50400302_9_dialog_content = "...It's not my first time here.",
  ui_story_5040_50400302_10_dialog_content = "R-Right...",
  ui_story_5040_50400302_11_dialog_content = "Let's not waste any time. We should go look for Naroxel.",
  ui_story_5040_50400302_12_dialog_content = "Naroxel! It's been forever!",
  ui_story_5040_50400302_13_dialog_content = "Wait, who... Adonis?!",
  ui_story_5040_50400302_14_dialog_content = "It has been a long time! What brings you to Lumopolis? Are your parents and Mr. Novio doing well?",
  ui_story_5040_50400302_15_dialog_content = "Everyone's doing great.",
  ui_story_5040_50400302_16_dialog_content = "And this is the one I'm always mentioning in my letters, Tara.",
  ui_story_5040_50400302_17_dialog_content = "...",
  ui_story_5040_50400302_18_dialog_content = "Actually, Naroxel, we've come back to Lumopolis because we have a slight situation...",
  ui_story_5040_50400302_19_dialog_content = "<color=#e8d9bb>After recounting the story to Naroxel...</color>",
  ui_story_5040_50400302_20_dialog_content = "How is that possible?",
  ui_story_5040_50400302_21_dialog_content = "I've never heard of a potion that can erase people's memories.",
  ui_story_5040_50400302_22_dialog_content = "Yeah, I'm finding it hard to wrap my head around too.",
  ui_story_5040_50400302_23_dialog_content = "Is there anything I can do to help? Anything at all? We're old friends, so don't be afraid to ask.",
  ui_story_5040_50400302_24_dialog_content = "Actually, Jeriah suggested that we take part in the Mooncrown Day events that the Courier Union puts on in different cities to get Feather Seals!",
  ui_story_5040_50400302_25_dialog_content = "It's a great opportunity to visit new places, and maybe find some leads to a cure for Tara's amnesia.",
  ui_story_5040_50400302_26_dialog_content = "Feather Seals?",
  ui_story_5040_50400302_27_dialog_content = "It's true, the Courier Union does offer a special challenge to couples each Mooncrown Day.",
  ui_story_5040_50400302_28_dialog_content = "But...",
  ui_story_5040_50400302_29_dialog_content = "But what? Is there a problem?",
  ui_story_5040_50400302_30_dialog_content = "We're old friends. I remember seeing you and Mr. Novio around very often when I was studying with the queen in the Winter Palace.",
  ui_story_5040_50400302_31_dialog_content = "And that's why I hope that your choice to face life's challenges with Tara was a thoughtful one, above all else.",
  ui_story_5040_50400302_32_dialog_content = "Mooncrown Day, Courier Union events, whatever else... They are all superficial.",
  ui_story_5040_50400302_33_dialog_content = "Yes, I understand.",
  ui_story_5040_50400302_34_dialog_content = "I will support you, should you wish to seize this opportunity.",
  ui_story_5040_50400302_35_dialog_content = "Thank you, Naroxel!",
  ui_story_5040_50400302_36_dialog_content = "As for the Mooncrown Day event...",
  ui_story_5040_50400302_37_dialog_content = "This is a book of special commemorative stamps, issued by the Courier Union to celebrate this year's Mooncrown Day. Sell them all, and you pass the test.",
  ui_story_5040_50400302_38_dialog_content = "That'll be easy! Right, Tara?",
  ui_story_5040_50400302_39_dialog_content = "Um, probably.",
  ui_story_5040_50400302_40_dialog_content = "But I've never done such fiddly work before.",
  ui_story_5040_50400302_41_dialog_content = "If we work together, we won't have any problems. Come on! Let's get started.",
  ui_story_5040_50400302_42_dialog_content = "Good luck!",
  ui_story_5040_50400302_43_dialog_content = "Thank you, PlayerName. And you too, Jeriah.",
  ui_story_5040_50400302_44_dialog_content = "But it appears as though they intend to go to other Courier Union divisions. Could I trouble you to escort them a few more times, PlayerName?",
  ui_story_5040_50400302_45_dialog_content = "Sure! Anything I can do to help.",
  ui_story_5040_50400302_46_dialog_content = "Go get some rest first, though.",
  ui_story_5040_50400302_47_dialog_content = "I'll accompany them during the challenges.",
  ui_story_5040_50400302_48_dialog_content = "If I could have a word, Jeriah?",
  ui_story_5040_50400302_49_dialog_content = "...",
  ui_story_5040_50400302_50_dialog_content = "Is there anything you want to tell me?",
  ui_story_5040_50400302_51_dialog_content = "Hehe... Are you getting at anything in particular?",
  ui_story_5040_50400302_52_dialog_content = "Now, don't play dumb with me. Do you know what was in all those packages sent to Lumopolis from Rediesel?",
  ui_story_5040_50400302_53_dialog_content = "Hm, I wonder? I didn't really check.",
  ui_story_5040_50400302_54_dialog_content = "How could you just forward them without checking...? Eho and I already have a lot on our plates.",
  ui_story_5040_50400302_55_dialog_content = "Even before the festival, things were piling up, but now the Lumopolis Courier Union is really at its wit's end.",
  ui_story_5040_50400302_56_dialog_content = "I didn't tell any higher-ups about this, otherwise I'm pretty sure you'd have to face a lecture when you got back.",
  ui_story_5040_50400302_57_dialog_content = "So I owe you one. But that's why I've been running all around Northland for you.",
  ui_story_5040_50400302_58_dialog_content = "Sigh, I never expected something like this would happen to Adonis.",
  ui_story_5040_50400302_59_dialog_content = "Do me a favor and continue helping them.",
  ui_story_5040_50400302_60_dialog_content = "What a bother... and I have no idea why they're so determined to chain themselves to each other when they're clearly not a good match.",
  ui_story_5040_50400302_61_dialog_content = "Don't you often say that every individual is complicated?",
  ui_story_5040_50400302_62_dialog_content = "You'll understand one day, Jeriah. No one goes through life alone forever.",
  ui_story_5040_50400302_63_dialog_content = "Here are the stamps we need to portion out, Tara.",
  ui_story_5040_50400302_64_dialog_content = "You used to send me the Mooncrown Day stamp every year, remember? I saved each and every one of them.",
  ui_story_5040_50400302_65_dialog_content = "Really? I don't remember.",
  ui_story_5040_50400302_66_dialog_content = "That's alright. From now on, I'll be the one giving them to you! Isn't this year's design pretty cool?",
  ui_story_5040_50400302_67_dialog_content = "Ah...! The packaging!",
  ui_story_5040_50400302_68_dialog_content = "Watch out!",
  ui_story_5040_50400302_69_dialog_content = "Thank goodness it didn't fall on the ground.",
  ui_story_5040_50400302_70_dialog_content = "I told you I was no good at this kind of delicate work. Selling weaponry and stuff, now that's more up my alley.",
  ui_story_5040_50400302_71_dialog_content = "It's totally normal for people to have different talents. No one individual is the same.",
  ui_story_5040_50400302_72_dialog_content = "Don't worry about bagging the merchandise. I'll take care of that, you handle customers.",
  ui_story_5040_50400302_73_dialog_content = "I should be able to do that, at least.",
  ui_story_5040_50400302_74_dialog_content = "<color=#e8d9bb>A while later...</color>",
  ui_story_5040_50400302_75_dialog_content = "Could I also have some of this year's commemorative stamps, please?",
  ui_story_5040_50400302_76_dialog_content = "How come mine still aren't ready?",
  ui_story_5040_50400302_77_dialog_content = "Please, don't worry. Mooncrown Day stamps are special, so we have to ensure they're perfectly presented and wrapped up tight. Don't you agree?",
  ui_story_5040_50400302_78_dialog_content = "Here you are!",
  ui_story_5040_50400302_79_dialog_content = "Are you doing okay there, Tara?",
  ui_story_5040_50400302_80_dialog_content = "I think you should be more worried about the stamps you're handling. I'm just talking, after all.",
  ui_story_5040_50400302_81_dialog_content = "Looks like business is doing good over here.",
  ui_story_5040_50400302_82_dialog_content = "Yep! It's been pretty smooth so far.",
  ui_story_5040_50400302_83_dialog_content = "Let me see... there's not much left! Congratulations are in order.",
  ui_story_5040_50400302_84_dialog_content = "Yes! The last one's sold, we're done!",
  ui_story_5040_50400302_85_dialog_content = "Phew, that was hard work.",
  ui_story_5040_50400302_86_dialog_content = "Well done to you both.",
  ui_story_5040_50400302_87_dialog_content = "You could at least pretend to sound a little more sincere.",
  ui_story_5040_50400302_88_dialog_content = "*Yawn* Excuse me, are you selling those Courier Union stamps here?",
  ui_story_5040_50400302_89_dialog_content = "Yeah, but unfortunately we just sold out.",
  ui_story_5040_50400302_90_dialog_content = "They're super cute this year, but I didn't come here to buy stamps.",
  ui_story_5040_50400302_91_dialog_content = "I was wondering if you had any of last year's Mooncrown Day stamps lying around somewhere. If you do... I'll pay a premium for them.",
  ui_story_5040_50400302_92_dialog_content = "Uh...",
  ui_story_5040_50400302_93_dialog_content = "We're just temporary help. Jeriah, do you know?",
  ui_story_5040_50400302_94_dialog_content = "Those Courier Union stamps are all limited editions and we don't keep backups.",
  ui_story_5040_50400302_95_dialog_content = "I'm afraid you won't be able to procure any from official channels.",
  ui_story_5040_50400302_96_dialog_content = "Oh, I see. What am I going to do...?",
  ui_story_5040_50400302_97_dialog_content = "What seems to be the issue?",
  ui_story_5040_50400302_98_dialog_content = "Eh... Honestly, a friend asked me to get them.",
  ui_story_5040_50400302_99_dialog_content = "He sends Mooncrown Day stamps to his partner in Illumina every year.",
  ui_story_5040_50400302_100_dialog_content = "However, his family is a little conservative and adamantly opposes their relationship.",
  ui_story_5040_50400302_101_dialog_content = "That's why he asked me to buy him the stamps and stationery in secret.",
  ui_story_5040_50400302_102_dialog_content = "Ha! How very Lumopolis.",
  ui_story_5040_50400302_103_dialog_content = "Huh? Is it customary in Lumopolis to give stamps?",
  ui_story_5040_50400302_104_dialog_content = "Couples in Lumopolis send them to each other on Mooncrown Day, but I think the nobles have more extravagant practices.",
  ui_story_5040_50400302_105_dialog_content = "Indeed. I'd much rather snuggle up in bed to sleep than participate in this charade.",
  ui_story_5040_50400302_106_dialog_content = "But the problem is that his partner lost the commemorative stamps from last year...",
  ui_story_5040_50400302_107_dialog_content = "She felt so guilty and sad about it. My friend couldn't bear to see her so upset, so he asked me to find another copy of those stamps for him.",
  ui_story_5040_50400302_108_dialog_content = "They're just stamps. Can't he just get her something else?",
  ui_story_5040_50400302_109_dialog_content = "It's not the same at all! You can't just replace something that's filled with shared memories with something else.",
  ui_story_5040_50400302_110_dialog_content = "A Lumo noble, and an Illuminan girl... Interesting.",
  ui_story_5040_50400302_111_dialog_content = "They must encounter all kinds of obstacles in their relationship.",
  ui_story_5040_50400302_112_dialog_content = "Well, there's still light at the end of the tunnel for them. But I guess you could say they have a rocky road ahead of them.",
  ui_story_5040_50400302_113_dialog_content = "He's been slowly working on convincing his parents and other relatives, trying to bring them around.",
  ui_story_5040_50400302_114_dialog_content = "It'll probably still take some time, though.",
  ui_story_5040_50400302_115_dialog_content = "Lumopolis really lives up to its reputation as a place where families obsess over marrying within your class.",
  ui_story_5040_50400302_116_dialog_content = "Yeah? If you ask me, not even two people from noble families are automatically guaranteed happiness together.",
  ui_story_5040_50400302_117_dialog_content = "The Hall of Justice where I work receives divorce petitions from nobles all the time.",
  ui_story_5040_50400302_118_dialog_content = "Every single case has its own bizarre twists, and they're never clear-cut, thanks to the dispute over interests between nobles.",
  ui_story_5040_50400302_119_dialog_content = "Everyone tries to avoid taking on those cases.",
  ui_story_5040_50400302_120_dialog_content = "So even nobles can have trouble in paradise...",
  ui_story_5040_50400302_121_dialog_content = "Oh, for sure! So my advice is always to follow your heart.",
  ui_story_5040_50400302_122_dialog_content = "After all, even settling for someone of similar status doesn't guarantee happiness.",
  ui_story_5040_50400302_123_dialog_content = "How rare it is to hear such words from the mouth of Lumopolis noble!",
  ui_story_5040_50400302_124_dialog_content = "I can only say that everyone makes their own choices. Feelings can't be controlled. Love is love.",
  ui_story_5040_50400302_125_dialog_content = "Falling for someone isn't something anyone can control. It doesn't matter who they are or where they're from.",
  ui_story_5040_50400302_126_dialog_content = "I know this all too well.",
  ui_story_5040_50400302_127_dialog_content = "Well said indeed! I totally agree!",
  ui_story_5040_50400302_128_dialog_content = "Oh? Might you have someone on your mind?",
  ui_story_5040_50400302_129_dialog_content = "No... It's just that I happened to meet such a funny, fuzzy little guy a while ago.",
  ui_story_5040_50400302_130_dialog_content = "It could also speak Universese! I couldn't believe it.",
  ui_story_5040_50400302_131_dialog_content = "In fact, I sent it a letter yesterday. Dunno when I might receive a response, though.",
  ui_story_5040_50400302_132_dialog_content = "Is there really nothing we can do to help her friend out, Jeriah?",
  ui_story_5040_50400302_133_dialog_content = "...",
  ui_story_5040_50400302_134_dialog_content = "Well, I don't really know, but...",
  ui_story_5040_50400302_135_dialog_content = "If he's willing to pay, it might be a good idea to ask Allura over in Umbraton. She has quite the collection.",
  ui_story_5040_50400302_136_dialog_content = "I'm sure such a small thing wouldn't be a problem.",
  ui_story_5040_50400302_137_dialog_content = "I see! Thanks so much for your help!",
  ui_story_5040_50400302_138_dialog_content = "I might as well head to Umbraton now, while I'm not yet sleepy.",
  ui_story_5040_50400302_139_dialog_content = "You're like a walking encyclopedia, Jeriah.",
  ui_story_5040_50400302_140_dialog_content = "I hope she finds what she's looking for.",
  ui_story_5040_50400302_141_dialog_content = "Either way, we completed the task! Let's go get that seal!",
  ui_story_5040_50400302_142_dialog_content = "Sure...",
  ui_story_5040_50400302_143_dialog_content = "What's wrong, Tara? Are feeling okay?",
  ui_story_5040_50400302_144_dialog_content = "It's nothing, I'm fine.",
  ui_story_5040_50400302_145_dialog_content = "...",
  ui_story_5040_50400302_146_dialog_content = "<color=#e8d9bb>Meanwhile...</color>",
  ui_story_5040_50400302_147_dialog_content = "Nothing at all...?",
  ui_story_5040_50400302_148_dialog_content = "Do you still not remember anything?",
  ui_story_5040_50400302_149_dialog_content = "No... Nothing... Sorry...",
  ui_story_5040_50400302_150_dialog_content = "You don't need to apologize, you've done nothing wrong.",
  ui_story_5040_50400302_151_dialog_content = "What else could give us a lead...?",
  ui_story_5040_50400302_152_dialog_content = "Ah... That...",
  ui_story_5040_50400302_153_dialog_content = "What?",
  ui_story_5040_50400302_154_dialog_content = "Holding... in... hand...",
  ui_story_5040_50400302_155_dialog_content = "Who? Holding what?",
  ui_story_5040_50400302_156_dialog_content = "Him...",
  ui_story_5040_50400302_157_dialog_content = "Stamps...",
  ui_story_5040_50400302_158_dialog_content = "Stamps?? That guy who just walked by? Yeah, he had those Mooncrown Day stamps.",
  ui_story_5040_50400302_159_dialog_content = "Do they remind you of something?",
  ui_story_5040_50400302_160_dialog_content = "Seems... yes...",
  ui_story_5040_50400302_161_dialog_content = "Huh? Where'd you get these from? These all seem to be old Mooncrown Day stamps!",
  ui_story_5040_50400302_162_dialog_content = "Think... I have... many...",
  ui_story_5040_50400302_163_dialog_content = "Many what? Stamps like this?",
  ui_story_5040_50400302_164_dialog_content = "Yes...",
  ui_story_5040_50400302_165_dialog_content = "Usually when people have a lot of stamps, it means they send a lot of mail, right?",
  ui_story_5040_50400302_166_dialog_content = "That gives me an idea! Why don't I take you to have a look through the Union's unclaimed mail? Maybe we'll find something.",
  ui_story_5040_50400302_167_dialog_content = "Thanks... Kya...",
  ui_story_5040_50400302_168_dialog_content = "<color=#e8d9bb>A while later...</color>",
  ui_story_5040_50400302_169_dialog_content = "Nothing?",
  ui_story_5040_50400302_170_dialog_content = "No...",
  ui_story_5040_50400302_171_dialog_content = "Hmm. Well, maybe you were in a different Union region than Lumopolis.",
  ui_story_5040_50400302_172_dialog_content = "At least we have a lead now, though. It's better than just aimlessly wandering around like before.",
  ui_story_5040_50400302_173_dialog_content = "Let's tag along with PlayerName and the others and check the Illumina and Rediesel Wrench divisions.",
  ui_story_5040_50400302_174_dialog_content = "Don't you worry. We'll find it!",
  ui_story_5040_50400302_175_dialog_content = "K... Kya...",
  ui_story_5040_50400302_176_dialog_content = "Thank you...",
  ui_story_5040_50400302_177_dialog_content = "Why you... help... me...?",
  ui_story_5040_50400302_178_dialog_content = "I don't really know myself. Maybe I just can't walk by when someone needs help.",
  ui_story_5040_50400302_179_dialog_content = "(I must be crazy, helping an Eclipsite! What on earth am I thinking?!)",
  ui_story_5040_50400302_180_dialog_content = "(What would Emerald do?)",
  ui_story_5040_50400401_1_dialog_content = "<color=#e8d9bb>After Adonis and the others report back to Naroxel...</color>",
  ui_story_5040_50400401_2_dialog_content = "So this is the Courier Union's Feather Seal? I've never seen one before.",
  ui_story_5040_50400401_3_dialog_content = "It looks so well-crafted!",
  ui_story_5040_50400401_4_dialog_content = "Come look, Tara!",
  ui_story_5040_50400401_5_dialog_content = "... Don't suddenly act like we're so intimate or something.",
  ui_story_5040_50400401_6_dialog_content = "Feather Seals are mostly commemorative objects. They have very little monetary value on their own.",
  ui_story_5040_50400401_7_dialog_content = "Even before the Union existed, couriers were welcomed as bringers of good news wherever they went.",
  ui_story_5040_50400401_8_dialog_content = "Did nobles also hire couriers for weddings?",
  ui_story_5040_50400401_9_dialog_content = "Yes, but especially the nobles of Lumopolis. In fact, many would spend extravagantly to hire couriers to serve as witnesses in their weddings.",
  ui_story_5040_50400401_10_dialog_content = "This is also why the Courier Union sought to phase out this tradition with something else.",
  ui_story_5040_50400401_11_dialog_content = "Especially in Lumopolis. Mooncrown Day originated here, and so people here take its traditions seriously.",
  ui_story_5040_50400401_12_dialog_content = "What a bunch of weirdos. We don't celebrate pointless holidays like these in the desert.",
  ui_story_5040_50400401_13_dialog_content = "What's wrong with observing holidays? Plus this one is so romantic.",
  ui_story_5040_50400401_14_dialog_content = "In Lumopolis, where all of society is so heavily stratified, these types of formalities are just a means for controlling the lower classes.",
  ui_story_5040_50400401_15_dialog_content = "This, in turn, is the reason their importance is so greatly emphasized.",
  ui_story_5040_50400401_16_dialog_content = "That's a lot to take in...",
  ui_story_5040_50400401_17_dialog_content = "She's always going on about things I can't understand.",
  ui_story_5040_50400401_18_dialog_content = "So what should we do know?",
  ui_story_5040_50400401_19_dialog_content = "Jeriah, let's go for a walk. I need to take my mind off things.",
  ui_story_5040_50400401_20_dialog_content = "Then I'll go with—",
  ui_story_5040_50400401_21_dialog_content = "PlayerName, how about you partner with him for the time being? I need some peace and quiet right now.",
  ui_story_5040_50400401_22_dialog_content = "Sure, that works.",
  ui_story_5040_50400401_23_dialog_content = "...",
  ui_story_5040_50400401_24_dialog_content = "Sigh...",
  ui_story_5040_50400401_25_dialog_content = "Are you tired of your little act?",
  ui_story_5040_50400401_26_dialog_content = "I just... I don't know if I'm doing the right thing. Adonis really seems to believe that I lost my memories.",
  ui_story_5040_50400401_27_dialog_content = "I'm so conflicted. Back when we were selling stamps together, I felt as though he was still the same kind, gentle person I'd always known.",
  ui_story_5040_50400401_28_dialog_content = "But that doesn't resolve all the issues between us. I know that as soon as something big happens, he'll go back to being a coward.",
  ui_story_5040_50400401_29_dialog_content = "Maybe we really are too different to be together.",
  ui_story_5040_50400401_30_dialog_content = "Except since I like him so much, it's hard for me to accept that fact.",
  ui_story_5040_50400401_31_dialog_content = "We can choose to become whoever we want, but we can't force others to be who we want them to be.",
  ui_story_5040_50400401_32_dialog_content = "When you choose to be with someone, you have to take everything that comes after.",
  ui_story_5040_50400401_33_dialog_content = "The more you love someone, the more painful it is to let them go.",
  ui_story_5040_50400401_34_dialog_content = "... Are you speaking from experience?",
  ui_story_5040_50400401_35_dialog_content = "Of course not. Why would I knowingly put myself through that kind of pain?",
  ui_story_5040_50400401_36_dialog_content = "Still, being with him brought me a lot of joy. Most of our time spent together was happy.",
  ui_story_5040_50400401_37_dialog_content = "You could simply be projecting due to feeling insecure about your relationship. In the end, relationships are about exchanging values.",
  ui_story_5040_50400401_38_dialog_content = "And right now, what he's offering isn't meeting your expectations. Isn't that right?",
  ui_story_5040_50400401_39_dialog_content = "I...",
  ui_story_5040_50400401_40_dialog_content = "I don't know... I don't want to view our relationship like that, like it's nothing but a transaction.",
  ui_story_5040_50400401_41_dialog_content = "Whatever you say.",
  ui_story_5040_50400401_42_dialog_content = "We need experience to know what we really want deep down. Since things are already where they are now, I wouldn't worry too much.",
  ui_story_5040_50400401_43_dialog_content = "This is your business, after all. What other people say doesn't matter.",
  ui_story_5040_50400401_44_dialog_content = "Take as much time as you need to figure it out, and listen to your heart when you finally make a choice.",
  ui_story_5040_50400401_45_dialog_content = "...",
  ui_story_5040_50400401_46_dialog_content = "Welcome to Umbraton! Feels a lot different from Lumopolis, huh?",
  ui_story_5040_50400401_47_dialog_content = "Yeah...",
  ui_story_5040_50400401_48_dialog_content = "See that island floating right above us? That's Lumopolis.",
  ui_story_5040_50400401_49_dialog_content = "For many people in Umbraton, this holiday is the perfect opportunity to rake in the profits.",
  ui_story_5040_50400401_50_dialog_content = "There are lots of bizarre folks here, but there's also lots of fascinating, interesting things.",
  ui_story_5040_50400401_51_dialog_content = "Anything you're interested in checking out?",
  ui_story_5040_50400401_52_dialog_content = "...",
  ui_story_5040_50400401_53_dialog_content = "(It's over... He seems to have lost all his energy.)",
  ui_story_5040_50400401_54_dialog_content = "Sigh... I just don't know what to do anymore.",
  ui_story_5040_50400401_55_dialog_content = "Nothing I do is right... If only she would give me a hint! Then maybe I would know what to do...",
  ui_story_5040_50400401_56_dialog_content = "Er...",
  ui_story_5040_50400401_57_dialog_content = "We used to talk about everything, especially when it came to the things we didn't understand about our world. But now... how have things ended up like this?",
  ui_story_5040_50400401_58_dialog_content = "PlayerName, you're a Caelestite, you must have girls lining up outside your front door. Do you understand what I'm going through?",
  ui_story_5040_50400401_59_dialog_content = "U-Uh, that's a bit of an exaggeration.",
  ui_story_5040_50400401_60_dialog_content = "But I think that as long as two people's feelings for each other are strong enough, they can overcome any hardship.",
  ui_story_5040_50400401_61_dialog_content = "My two good friends and I, we've been through a lot together. We've even rescued each other from death's doorstep a few times!",
  ui_story_5040_50400401_62_dialog_content = "But all of those experiences strengthened our trust in one another. We're willing to do anything for each other, even if it means putting ourselves in harm's way.",
  ui_story_5040_50400401_63_dialog_content = "I'm positive that you and Tara are the same.",
  ui_story_5040_50400401_64_dialog_content = "O-Of course I'd do anything for her! I'd even risk my life, if I had to!",
  ui_story_5040_50400401_65_dialog_content = "It's just that I'm so indecisive sometimes... I can't just make split-second decisions like other people. That might be the reason she thinks I'm lacking as a man...",
  ui_story_5040_50400401_66_dialog_content = "Don't say that, Adonis! Who says that a man has to be one way or another? We're all different, and that's okay.",
  ui_story_5040_50400401_67_dialog_content = "No one's perfect, but if you two are still together... That means there's something about you that she finds attractive enough to stick around for!",
  ui_story_5040_50400401_68_dialog_content = "*Sobbing* I... I just hope she actually feels that way!!",
  ui_story_5040_50400401_69_dialog_content = "There, there, don't cry...",
  ui_story_5040_50400401_70_dialog_content = "Oooooh!",
  ui_story_5040_50400401_71_dialog_content = "Are we interrupting a beautiful, dashing moment?",
  ui_story_5040_50400401_72_dialog_content = "Gin, I feel so inspired!",
  ui_story_5040_50400401_73_dialog_content = "Shackled by society's expectations, two lovers who cannot be seen together—",
  ui_story_5040_50400401_74_dialog_content = "They're clearly hugging each other in broad daylight.",
  ui_story_5040_50400401_75_dialog_content = "Even though it's Mooncrown Day, the two lovers have no choice but to meet in a secluded corner of Umbraton, far from prying eyes—",
  ui_story_5040_50400401_76_dialog_content = "There are people everywhere...",
  ui_story_5040_50400401_77_dialog_content = "Is this not the most beautiful thing you've ever seen, Gin? I wanna do everything in my power to help them! And maybe earn a little something for myself, while I'm at it!",
  ui_story_5040_50400401_78_dialog_content = "That sounds like a marvelous idea.",
  ui_story_5040_50400401_79_dialog_content = "Er, I think you're misunderstand—",
  ui_story_5040_50400401_80_dialog_content = "I admire your courage, my man. May I ask your name?",
  ui_story_5040_50400401_81_dialog_content = "M-Me? My name's Adonis...",
  ui_story_5040_50400401_82_dialog_content = "You have an air of greatness about you, Adonis. One that puts you far above everyone else, especially that guy next to you.",
  ui_story_5040_50400401_83_dialog_content = "Why are you taking shots at me all of a sudden?!",
  ui_story_5040_50400401_84_dialog_content = "You must be the type that would do anything for love. I can tell just by looking at you.",
  ui_story_5040_50400401_85_dialog_content = "My lollipop feels the same way too.",
  ui_story_5040_50400401_86_dialog_content = "But let's dispense with the unnecessary small talk. For this year's Mooncrown Day, we have a very rare painting for sale, one that I believe suits you perfectly.",
  ui_story_5040_50400401_87_dialog_content = "It depicts the tragic tale of a forbidden love between two star-crossed lovers...",
  ui_story_5040_50400401_88_dialog_content = "This rare, beautiful painting can be yours for a very reasonable price, but only for today!",
  ui_story_5040_50400401_89_dialog_content = "Uh... What? I...",
  ui_story_5040_50400401_90_dialog_content = "Ah-ah-ah! Not another word! It's clear as day that you're simply dying to buy this painting!",
  ui_story_5040_50400401_91_dialog_content = "I concur.",
  ui_story_5040_50400401_92_dialog_content = "I...",
  ui_story_5040_50400401_93_dialog_content = "Knock it off, you two!",
  ui_story_5040_50400401_94_dialog_content = "Don't ruin his first time here in Umbraton!",
  ui_story_5040_50400401_95_dialog_content = "Please, we're just trying to make a living here. We were only conducting a reasonable transaction with this fine gentleman, nothing more.",
  ui_story_5040_50400401_96_dialog_content = "There was nothing reasonable about it!!",
  ui_story_5040_50400401_97_dialog_content = "I would love to prove you wrong... but I think I just heard something.",
  ui_story_5040_50400401_98_dialog_content = "<size=45>Aaaah!!</size>",
  ui_story_5040_50400401_99_dialog_content = "What's wrong?!",
  ui_story_5040_50400401_100_dialog_content = "E-E-Eclipsites!",
  ui_story_5040_50400401_101_dialog_content = "What are Eclipsites doing here?!",
  ui_story_5040_50400401_102_dialog_content = "<size=45>Graah!</size>",
  ui_story_5040_50400401_103_dialog_content = "Getting in the way of my business, how irksome.",
  ui_story_5040_50400401_104_dialog_content = "E-Eclipsites!",
  ui_story_5040_50400401_105_dialog_content = "Take cover, Adonis! We'll find a way to handle this!",
  ui_story_5040_50400402_1_dialog_content = "... Man, those two didn't waste a second, did they?",
  ui_story_5040_50400402_2_dialog_content = "Are you alright, Adonis?",
  ui_story_5040_50400402_3_dialog_content = "Y-Yeah, I'm fine.",
  ui_story_5040_50400402_4_dialog_content = "Sorry for being so useless... Just the sight of those Eclipsites made my legs give out from under me.",
  ui_story_5040_50400402_5_dialog_content = "Don't worry about it. Most people aren't used to fighting against those monsters.",
  ui_story_5040_50400402_6_dialog_content = "At least Hachi and Gin have run off. They're impossible.",
  ui_story_5040_50400402_7_dialog_content = "Those guys tend to go for the easiest targets, so just remember to turn them down bluntly the next time you run into them.",
  ui_story_5040_50400402_8_dialog_content = "Sigh... Why am I always like this?",
  ui_story_5040_50400402_9_dialog_content = "Pardon me, but weren't you selling Mooncrown Day stamps earlier?",
  ui_story_5040_50400402_10_dialog_content = "Huh?",
  ui_story_5040_50400402_11_dialog_content = "Are you talking about Adonis? He was with Tara and Jeriah from the Courier Union earlier.",
  ui_story_5040_50400402_12_dialog_content = "Ah, so that's your name.",
  ui_story_5040_50400402_13_dialog_content = "And you are...?",
  ui_story_5040_50400402_14_dialog_content = "Greetings! My name is Tina, and I'm a judge from the Lumo Hall of Justice. Please excuse me for forgetting to introduce myself before.",
  ui_story_5040_50400402_15_dialog_content = "Nice to meet you, Tina. I'm PlayerName.",
  ui_story_5040_50400402_16_dialog_content = "I just asked those friends of yours about last year's Mooncrown Day stamps this morning.",
  ui_story_5040_50400402_17_dialog_content = "Thanks to that courier, I found what I was looking for here in Umbraton.",
  ui_story_5040_50400402_18_dialog_content = "Really? It's all thanks to Jeriah... I'm glad she was able to help, considering I couldn't do a thing.",
  ui_story_5040_50400402_19_dialog_content = "In any case, I'm sure your friend and his lover are happy that you could find the stamp from last year.",
  ui_story_5040_50400402_20_dialog_content = "You're absolutely right. He was practically jumping for joy when I gave it to him.",
  ui_story_5040_50400402_21_dialog_content = "He thanked me over and over again before finally running home as fast as he could to write his love letter.",
  ui_story_5040_50400402_22_dialog_content = "The merchant I got it from carried a lot of interesting items. I was just on my way to see more of her wares when I ran into you two.",
  ui_story_5040_50400402_23_dialog_content = "... Are you feeling alright, sir? You look a bit pale... Did something happen?",
  ui_story_5040_50400402_24_dialog_content = "Actually... I...",
  ui_story_5040_50400402_25_dialog_content = "Ah... I see now! No wonder I felt as though there was something strange between you two!",
  ui_story_5040_50400402_26_dialog_content = "So you're going to Illumina, yes? In that case, I could ask my friend's lover if she knows of a cure?",
  ui_story_5040_50400402_27_dialog_content = "H-Huh?",
  ui_story_5040_50400402_28_dialog_content = "I'll be upfront with you. She works for the Black Umbrella Laboratories in Gannon City.",
  ui_story_5040_50400402_29_dialog_content = "If a remedy exists, her knowledge might prove useful to you! Just mention my name to her, and she'll help you however she can.",
  ui_story_5040_50400402_30_dialog_content = "I can't guarantee she'll have the answers you seek, but referring you to her is the least I can do for you.",
  ui_story_5040_50400402_31_dialog_content = "That's more than enough! Thank you so much, Miss Tina!",
  ui_story_5040_50400402_32_dialog_content = "We'll be sure to visit her once we're over there!",
  ui_story_5040_50400402_33_dialog_content = "See, Adonis? There's still hope for you guys!",
  ui_story_5040_50400402_34_dialog_content = "I wish you safe travels and the best of luck on your journey.",
  ui_story_5040_50400402_35_dialog_content = "Yaaaaawn... I'm starting to feel a bit tired. I think it's time to go home and get some rest...",
  ui_story_5040_50400402_36_dialog_content = "It looks like your determination is finally starting to pay off, Adonis. We'll visit that lady as soon as we get to Gannon City.",
  ui_story_5040_50400402_37_dialog_content = "Yes! Thanks again, PlayerName.",
  ui_story_5040_50400402_38_dialog_content = "<color=#e8d9bb>That night...</color>",
  ui_story_5040_50400402_39_dialog_content = "Sigh... This place didn't do the trick either, huh?",
  ui_story_5040_50400402_40_dialog_content = "I'm... trying... my best...",
  ui_story_5040_50400402_41_dialog_content = "Sorry, I didn't mean to stress you out. No pressure, take all the time you need.",
  ui_story_5040_50400402_42_dialog_content = "We should be heading back, anyway. I think we've covered enough ground in Umbraton for today.",
  ui_story_5040_50400402_43_dialog_content = "It's safer in Lumopolis at night.",
  ui_story_5040_50400402_44_dialog_content = "Umbra...ton... Lumo...polis...",
  ui_story_5040_50400402_45_dialog_content = "Lumopolis...",
  ui_story_5040_50400402_46_dialog_content = "What's the matter? Why are you so hung up on Lumopolis?",
  ui_story_5040_50400402_47_dialog_content = "Did you remember something?",
  ui_story_5040_50400402_48_dialog_content = "Lumopolis... A long trip...",
  ui_story_5040_50400402_49_dialog_content = "I came here... to meet someone...",
  ui_story_5040_50400402_50_dialog_content = "But who...? Who did I promise to meet... in Lumopolis...?",
  ui_story_5040_50400402_51_dialog_content = "He... He never came...",
  ui_story_5040_50400402_52_dialog_content = "What? You mean you once came to Lumopolis from somewhere else?",
  ui_story_5040_50400402_53_dialog_content = "Yes... I... feel it...",
  ui_story_5040_50400402_54_dialog_content = "That means you're not from around here. Do you remember where you came from?",
  ui_story_5040_50400402_55_dialog_content = "I think... far, far away...",
  ui_story_5040_50400402_56_dialog_content = "A faraway place, huh? I see...",
  ui_story_5040_50400402_57_dialog_content = "Alright, don't overdo it. Since you're not from Lumopolis, we'll have to go elsewhere and keep looking.",
  ui_story_5040_50400402_58_dialog_content = "I think PlayerName and the others are going to Gannon City tomorrow. Let's tag along with them.",
  ui_story_5040_50400402_59_dialog_content = "Maybe the Courier Union over there will give us some answers.",
  ui_story_5040_50400402_60_dialog_content = "Okay...",
  ui_story_5040_50400402_61_dialog_content = "<color=#e8d9bb>The next day...</color>",
  ui_story_5040_50400402_62_dialog_content = "Alright, is everybody ready? Don't forget anything you might need!",
  ui_story_5040_50400402_63_dialog_content = "Heheh... I haven't been to Illumina in ages. I wonder how those little birds are doing?",
  ui_story_5040_50400402_64_dialog_content = "Please don't make more trouble for them, Jeriah.",
  ui_story_5040_50400402_65_dialog_content = "The Illumina Federation is supposed to be a highly-militarized nation, right? Tara told me all about it before... I've always wanted to see it for myself!",
  ui_story_5040_50400402_66_dialog_content = "I'm pretty interested in seeing their latest truck models.",
  ui_story_5040_50400402_67_dialog_content = "Then let's get going!",
  ui_story_5040_50400502_1_dialog_content = "Wow... So this is Gannon City!",
  ui_story_5040_50400502_2_dialog_content = "I've only been here once myself.",
  ui_story_5040_50400502_3_dialog_content = "It never seems to change much, does it?",
  ui_story_5040_50400502_4_dialog_content = "Do you come to Illumina often, PlayerName?",
  ui_story_5040_50400502_5_dialog_content = "Not really, no. It's just that one of my closest friends is from here, so we came here a few times.",
  ui_story_5040_50400502_6_dialog_content = "She's on vacation right now, though. I don't think we'll have a chance to see her today.",
  ui_story_5040_50400502_7_dialog_content = "Does Gannon City not celebrate Mooncrown Day or something? There isn't a single decoration to be seen around here...",
  ui_story_5040_50400502_8_dialog_content = "Of course they do, and it's just as important to them as well.",
  ui_story_5040_50400502_9_dialog_content = "Different places have their own ways of observing holidays. The Illumina Federation doesn't place as much importance on pageantry, is all.",
  ui_story_5040_50400502_10_dialog_content = "People here tend to be more pragmatic and reserved when it comes to public displays. For this particular holiday, most ladies offer handmade cinnamon rolls to the person they like.",
  ui_story_5040_50400502_11_dialog_content = "Men, on the other hand, paint a small heart on the inside of their sleeves and write the name of the person they love on it.",
  ui_story_5040_50400502_12_dialog_content = "That sounds kind of cute, actually.",
  ui_story_5040_50400502_13_dialog_content = "And romantic! I want to do it too!",
  ui_story_5040_50400502_14_dialog_content = "Hey...",
  ui_story_5040_50400502_15_dialog_content = "You sure know a lot about the world, Jeriah.",
  ui_story_5040_50400502_16_dialog_content = "I heard Jeriah has traveled to lots of places before, but she rarely ever seems to bring it up.",
  ui_story_5040_50400502_17_dialog_content = "Oh, that's all ancient history. Now then, if I'm not mistaken, that person over there...",
  ui_story_5040_50400502_18_dialog_content = "?!?",
  ui_story_5040_50400502_19_dialog_content = "That must be Illumina's little birdie.",
  ui_story_5040_50400502_20_dialog_content = "Dove? Shouldn't you be delivering letters right now?",
  ui_story_5040_50400502_21_dialog_content = "Mm, yeah, that's what I'm doing. I wouldn't lark around just because it's a holiday.",
  ui_story_5040_50400502_22_dialog_content = "I'm only working at my own pace, that's all.",
  ui_story_5040_50400502_23_dialog_content = "You sound completely unbelievable...",
  ui_story_5040_50400502_24_dialog_content = "So you're the famous Dove, huh? I've heard about you... though I can't say any of it was positive.",
  ui_story_5040_50400502_25_dialog_content = "How could you say that? I work really hard! It's not my fault there are billions of letters to deliver during these holidays.",
  ui_story_5040_50400502_26_dialog_content = "It's impossible to deliver them all, it really ruffles my feathers, coo!",
  ui_story_5040_50400502_27_dialog_content = "So you decided to just slack off altogether, then?",
  ui_story_5040_50400502_28_dialog_content = "Never mind that for now. Do you know anything about the Mooncrown Day Feather Seal?",
  ui_story_5040_50400502_29_dialog_content = "The Feather Seal? I have it on me.",
  ui_story_5040_50400502_30_dialog_content = "Huh?!",
  ui_story_5040_50400502_31_dialog_content = "All of my higher-ups are so busy making deliveries right now, they left me in charge of watching over it.",
  ui_story_5040_50400502_32_dialog_content = "It sounds more like they had no choice but to work overtime because a certain someone isn't pulling their own weight...",
  ui_story_5040_50400502_33_dialog_content = "Coo! What's that supposed to mean?!",
  ui_story_5040_50400502_34_dialog_content = "A-Anyway, we just wanted to get a Feather Seal stamp from the Courier Union of Illumina. We're a couple, you see...",
  ui_story_5040_50400502_35_dialog_content = "Ah... I see.",
  ui_story_5040_50400502_36_dialog_content = "That's easy, just take care of the rest of my deliveries for me.",
  ui_story_5040_50400502_37_dialog_content = "... Is that even allowed?!",
  ui_story_5040_50400502_38_dialog_content = "Well, I'm the only one here, and I also happen to have the Feather Seal... So basically, I can do whatever I want.",
  ui_story_5040_50400502_39_dialog_content = "I'm really sorry, but it'd be great if you'd be willing to help me.",
  ui_story_5040_50400502_40_dialog_content = "We'll do it! Just leave it to us!",
  ui_story_5040_50400502_41_dialog_content = "<color=#e8d9bb>Fifteen minutes later—</color>",
  ui_story_5040_50400502_42_dialog_content = "...",
  ui_story_5040_50400502_43_dialog_content = "...",
  ui_story_5040_50400502_44_dialog_content = "...",
  ui_story_5040_50400502_45_dialog_content = "That's quite a lot of things to deliver.",
  ui_story_5040_50400502_46_dialog_content = "\"Just a few more parcels,\" my foot! How'd she even manage to jam all of these in here?!",
  ui_story_5040_50400502_47_dialog_content = "The two of us couldn't possibly deliver all of these, even if we worked without rest for three days straight...",
  ui_story_5040_50400502_48_dialog_content = "I'm sorry... I didn't think there would be so many.",
  ui_story_5040_50400502_49_dialog_content = "Guess we don't have a choice, guys. Let's get started...",
  ui_story_5040_50400502_50_dialog_content = "I'll help out too, and take the opportunity to bring Sable around town.",
  ui_story_5040_50400502_51_dialog_content = "I'm sorry... It looks like we dragged you into our own problems again.",
  ui_story_5040_50400502_52_dialog_content = "We'll handle the lion's share of the deliveries. I'm pretty good at physical work.",
  ui_story_5040_50400502_53_dialog_content = "I'll just be over here chilling with my book, cheering you guys gone.",
  ui_story_5040_50400502_54_dialog_content = "Jeriah... Sigh, I guess it's probably for the better. We don't need things to get any worse than they already are...",
  ui_story_5040_50400502_55_dialog_content = "Alright! Let's get started, everyone!",
  ui_story_5040_50400502_56_dialog_content = "Ahhhh!",
  ui_story_5040_50400502_57_dialog_content = "Oi, hurry it up, Adonis!",
  ui_story_5040_50400502_58_dialog_content = "I... I'm sorry! These stairs are just so steep...",
  ui_story_5040_50400502_59_dialog_content = "Be a little more careful, then!",
  ui_story_5040_50400502_60_dialog_content = "Here, let's stop and sort out our deliveries. You take the closer ones, and I'll handle the farther ones.",
  ui_story_5040_50400502_61_dialog_content = "No way, there's way too much for you to handle alone.",
  ui_story_5040_50400502_62_dialog_content = "Don't worry, I'm used to running around like this. It'll make the deliveries go by much quicker, trust me.",
  ui_story_5040_50400502_63_dialog_content = "Oh... Okay.",
  ui_story_5040_50400502_64_dialog_content = "D-Delivery for you, Vivian!",
  ui_story_5040_50400502_65_dialog_content = "Oh my, if it isn't PlayerName! Aren't you usually with V—",
  ui_story_5040_50400502_66_dialog_content = "Yeah, yeah. Here's your package, see you later!",
  ui_story_5040_50400502_67_dialog_content = "But why are you delivering mail in the first place?",
  ui_story_5040_50400502_68_dialog_content = "... Dove, your performance review is going to be a disaster.",
  ui_story_5040_50400502_69_dialog_content = "Hello! Please sign for this letter, and have a nice day!",
  ui_story_5040_50400502_70_dialog_content = "Nice. That takes care of the deliveries for this floor.",
  ui_story_5040_50400502_71_dialog_content = "Kya... is amazing...",
  ui_story_5040_50400502_72_dialog_content = "Not really! I'm a courier, after all!",
  ui_story_5040_50400502_73_dialog_content = "Just remember to tell me if you see anything that jogs your memory, okay?",
  ui_story_5040_50400502_74_dialog_content = "<color=#e8d9bb>A few hours later—</color>",
  ui_story_5040_50400502_75_dialog_content = "I... I'm at my limit...",
  ui_story_5040_50400502_76_dialog_content = "*Panting* PlayerName... Are you finished with your deliveries?",
  ui_story_5040_50400502_77_dialog_content = "Yeah... Finally...",
  ui_story_5040_50400502_78_dialog_content = "I know we had to cover a lot of ground, but you guys really have lackluster stamina.",
  ui_story_5040_50400502_79_dialog_content = "Great work, everyone! It looks like our work here is done.",
  ui_story_5040_50400502_80_dialog_content = "Kya's not back yet?",
  ui_story_5040_50400502_81_dialog_content = "Oh, don't worry about her. She finished her deliveries a while ago. Northland's birdies are the most efficient.",
  ui_story_5040_50400502_82_dialog_content = "She must be showing her little friend the sights in Gannon City right about now.",
  ui_story_5040_50400502_83_dialog_content = "Haha! I knew you had it in you, PlayerName!",
  ui_story_5040_50400502_84_dialog_content = "D-Dove? Have you been hanging out around here this whole time?!",
  ui_story_5040_50400502_85_dialog_content = "\"Hanging out\"? I'm working really hard right now.",
  ui_story_5040_50400502_86_dialog_content = "Can we have a stamp now that we finished the job?",
  ui_story_5040_50400502_87_dialog_content = "Sure, come on over. Behold the Feather Seal!",
  ui_story_5040_50400502_88_dialog_content = "Ta-da!",
  ui_story_5040_50400502_89_dialog_content = "Hah... Now we have Illumina's stamp too!",
  ui_story_5040_50400502_90_dialog_content = "I still don't see the point of all of this...",
  ui_story_5040_50400502_91_dialog_content = "D-Don't say that! Our little adventures have been bringing us closer together, don't you think?",
  ui_story_5040_50400502_92_dialog_content = "S-Says who?!",
  ui_story_5040_50400502_93_dialog_content = "Now that we have Illumina's Feather Seal, where are we off to next?",
  ui_story_5040_50400502_94_dialog_content = "We don't come to Gannon City every day. Let's go try some of the local food, and maybe watch a movie!",
  ui_story_5040_50400502_95_dialog_content = "That ought to put us all in the holiday spirit!",
  ui_story_5040_50400502_96_dialog_content = "We can eat Illumina's food whenever we want, though.",
  ui_story_5040_50400502_97_dialog_content = "While delivering letters, I overheard that a shipment of kinetic energy rifles just arrived from an Undercity. I want to go see them unload those weapons.",
  ui_story_5040_50400502_98_dialog_content = "You want to go look at guns on Mooncrown Day? That's not very romantic...",
  ui_story_5040_50400502_99_dialog_content = "If you don't want to go, I can always go by myself.",
  ui_story_5040_50400502_100_dialog_content = "I...",
  ui_story_5040_50400502_101_dialog_content = "Settle down, you two. There is still a very important matter to attend to.",
  ui_story_5040_50400502_102_dialog_content = "Or have you both forgotten the reason we came here in the first place?",
  ui_story_5040_50400502_103_dialog_content = "Oh yeah! We still have to go ask that lady in the Black Umbrella Laboratories about Tara's amnesia!",
  ui_story_5040_50400502_104_dialog_content = "O-Oh, right...",
  ui_story_5040_50400502_105_dialog_content = "...",
  ui_story_5040_50400502_106_dialog_content = "Let's get that done before it gets dark. Come on.",
  ui_story_5040_50400601_1_dialog_content = "(It really has been too long.)",
  ui_story_5040_50400601_2_dialog_content = "... And that's why we're here today. Sorry for all of the trouble.",
  ui_story_5040_50400601_3_dialog_content = "It's no trouble at all! After all, I owe so much to Miss Tina, as well as all of you!",
  ui_story_5040_50400601_4_dialog_content = "Lumopolis and Illumina have always had their differences, which has made things very difficult for the two of us.",
  ui_story_5040_50400601_5_dialog_content = "But we've been blessed to have the company of people like Miss Tina who support us!",
  ui_story_5040_50400601_6_dialog_content = "Despite being a member of the noble class, she has always been supportive of our love.",
  ui_story_5040_50400601_7_dialog_content = "From what I understand, her body requires plenty of sleep in order to even function properly. Despite her condition, she still went out of her way to find that stamp for us.",
  ui_story_5040_50400601_8_dialog_content = "Yup, there's no denying that she's an incredible person.",
  ui_story_5040_50400601_9_dialog_content = "She's always so kind and polite.",
  ui_story_5040_50400601_10_dialog_content = "But I know that she has enough problems to deal with. I heard that her job in the Hall of Justice is... interesting, to say the least.",
  ui_story_5040_50400601_11_dialog_content = "I have no clue when we'll have the chance to see each other again. I wish I knew more about her.",
  ui_story_5040_50400601_12_dialog_content = "But according to her, it sounds like you and your beloved have it hard enough as it is.",
  ui_story_5040_50400601_13_dialog_content = "Yeah. Why haven't you two just eloped?",
  ui_story_5040_50400601_14_dialog_content = "Because we both have things we need to do. We may be lovers, but our own responsibilities will always come first.",
  ui_story_5040_50400601_15_dialog_content = "He and I both have a strong sense of duty, which is probably why we were attracted to each other in the first place.",
  ui_story_5040_50400601_16_dialog_content = "If two people are completely sincere with themselves and with one another, things like distance become trivial. After all, our hearts are always together.",
  ui_story_5040_50400601_17_dialog_content = "Your hearts... are always together?",
  ui_story_5040_50400601_18_dialog_content = "I feel the same way too. No problem is too difficult to overcome, as long as you love each other!",
  ui_story_5040_50400601_19_dialog_content = "Hahaha! Now then, we should really get back to business. Your name is Tara, right? I think I understand your dilemma, more or less.",
  ui_story_5040_50400601_20_dialog_content = "Unfortunately, I'm only an intern at the moment, but let me ask my colleagues and see what they think. One moment, please.",
  ui_story_5040_50400601_21_dialog_content = "Thanks again!",
  ui_story_5040_50400601_22_dialog_content = "<size=33>Jeriah... You don't think they'll figure out that I'm just pretending, do you?</size>",
  ui_story_5040_50400601_23_dialog_content = "Wouldn't it be better to come clean at this point?",
  ui_story_5040_50400601_24_dialog_content = "<size=33>No way! I could never show my face around the others if I did!</size>",
  ui_story_5040_50400601_25_dialog_content = "You didn't think of that when you came up with this crazy idea?",
  ui_story_5040_50400601_26_dialog_content = "<size=33>Anyways, if the secret gets out, I'll really need you to help me put out the fire.</size>",
  ui_story_5040_50400601_27_dialog_content = "...",
  ui_story_5040_50400601_28_dialog_content = "(I knew she was just pretending this whole time... I guess I'll just pretend I don't know anything.)",
  ui_story_5040_50400601_29_dialog_content = "What are you two talking about?",
  ui_story_5040_50400601_30_dialog_content = "Nothing! We were just saying how incredible this laboratory looks!",
  ui_story_5040_50400601_31_dialog_content = "Well, yeah... Migard is in charge of this place, and she's on a totally different level.",
  ui_story_5040_50400601_32_dialog_content = "Tara? Why are you trembling?",
  ui_story_5040_50400601_33_dialog_content = "Oh, she's just a little cold!",
  ui_story_5040_50400601_34_dialog_content = "Really? It doesn't feel very cold at all in here...",
  ui_story_5040_50400601_35_dialog_content = "Sorry to keep you waiting! If everyone would just follow me, I'd like to introduce you to one of the senior researchers here.",
  ui_story_5040_50400601_36_dialog_content = "Lead the way!",
  ui_story_5040_50400601_37_dialog_content = "Jola? This is Tara, the young lady I mentioned earlier. It appears she's currently suffering from a case of amnesia.",
  ui_story_5040_50400601_38_dialog_content = "We'd appreciate any help you can give us!",
  ui_story_5040_50400601_39_dialog_content = "I'm more than happy to lend a hand! It's the least I can do, after all you've done for my colleague here.",
  ui_story_5040_50400601_40_dialog_content = "Now then, Miss Tara... Would you mind if I examined you up close?",
  ui_story_5040_50400601_41_dialog_content = "G-Go ahead...",
  ui_story_5040_50400601_42_dialog_content = "What a pity Migard isn't here today. I'm not an expert in these matters, but I'll still try my best.",
  ui_story_5040_50400601_43_dialog_content = "(Thank goodness!)",
  ui_story_5040_50400601_44_dialog_content = "Hmm... At first glance, nothing appears to be out of the ordinary. We'll have to run a number of tests to ascertain your body's condition.",
  ui_story_5040_50400601_45_dialog_content = "Wh-What kind of tests...?",
  ui_story_5040_50400601_46_dialog_content = "(His smile looks ominous...)",
  ui_story_5040_50400601_47_dialog_content = "Don't worry! A little pinch here, a small tug there, and it'll be over before you know it!",
  ui_story_5040_50400601_48_dialog_content = "Graaah!",
  ui_story_5040_50400601_49_dialog_content = "Oh no...",
  ui_story_5040_50400602_1_dialog_content = "Hey! You didn't say anything about using Eclipsites to run your tests!",
  ui_story_5040_50400602_2_dialog_content = "A little warning would have been nice, you know!!",
  ui_story_5040_50400602_3_dialog_content = "My apologies, everyone. I honestly didn't expect you would be so opposed to my methods!",
  ui_story_5040_50400602_4_dialog_content = "After all, you guys are quite the peculiar group. A Northlander, a desert-dweller, a demi-human courier... and, of course, the very last Caelestite in the world.",
  ui_story_5040_50400602_5_dialog_content = "That's not relevant at all. We're just here to help Tara get better!",
  ui_story_5040_50400602_6_dialog_content = "So what exactly is wrong with me?",
  ui_story_5040_50400602_7_dialog_content = "Well, from what I've seen, you appear to be in perfect physical health.",
  ui_story_5040_50400602_8_dialog_content = "... Is that it? Then, what else can we do?",
  ui_story_5040_50400602_9_dialog_content = "What else can you tell me about her illness? Do you know what might have caused it?",
  ui_story_5040_50400602_10_dialog_content = "Let me see... It all started with that magic potion. The psychic who sold it to me said that it was made using a very special ingredient.",
  ui_story_5040_50400602_11_dialog_content = "Something about a giant, pink sandworm in the Rediesel Desert... I guess it's supposed to be an extremely rare creature?",
  ui_story_5040_50400602_12_dialog_content = "Did you say... a pink sandworm?",
  ui_story_5040_50400602_13_dialog_content = "Y-Yeah?",
  ui_story_5040_50400602_14_dialog_content = "Jola, what do you know about it?",
  ui_story_5040_50400602_15_dialog_content = "...",
  ui_story_5040_50400602_16_dialog_content = "I can't believe the legendary pink sandworm has shown itself again...",
  ui_story_5040_50400602_17_dialog_content = "<size=33>What?! That's impossible!</size>",
  ui_story_5040_50400602_18_dialog_content = "<size=33>Tara?</size>",
  ui_story_5040_50400602_19_dialog_content = "<size=33>I got my hands on the pink sandworm scale a long time ago! How did some psychic get a hold of one too?!</size>",
  ui_story_5040_50400602_20_dialog_content = "<size=33>If this pink sandworm really exists, is it really so surprising to know that someone else has one of its scales?</size>",
  ui_story_5040_50400602_21_dialog_content = "<size=33>It is, because as far as I know, only one pink sandworm scale has ever been available on the entire market! So how could there suddenly be another one?</size>",
  ui_story_5040_50400602_22_dialog_content = "My expertise lies in the field of botany. While I was searching for a particular spore one day, Migard mentioned the pink sandworm to me.",
  ui_story_5040_50400602_23_dialog_content = "This spore has gone mostly unresearched over the years, and is only mentioned in books. The reason for this is because it only grows on the scales of the exceedingly rare pink sandworm.",
  ui_story_5040_50400602_24_dialog_content = "Migard mentioned that there were eyewitness reports of this creature, but very few have been able to prove their claims.",
  ui_story_5040_50400602_25_dialog_content = "It's more aggressive than the regular sandworm, making it difficult for anyone to approach it. Its scales are an extremely rare and precious ingredient. In fact, I think there's only a single scale available on the entire market.",
  ui_story_5040_50400602_26_dialog_content = "If you were to bring me one of these scales, I could perhaps attempt at crafting a cure.",
  ui_story_5040_50400602_27_dialog_content = "Beyond that, I'm afraid I have no other solutions to offer you.",
  ui_story_5040_50400602_28_dialog_content = "...",
  ui_story_5040_50400602_29_dialog_content = "...",
  ui_story_5040_50400602_30_dialog_content = "Then it seems our goal has been made very clear to us.",
  ui_story_5040_50400602_31_dialog_content = "Jeriah?",
  ui_story_5040_50400602_32_dialog_content = "Considering our next destination is the Rediesel Wrench, and I'm the head of the Courier Union there... then I'll just make getting one of those pink sandworm scales the Feather Seal trial.",
  ui_story_5040_50400602_33_dialog_content = "Hey, are you serious?",
  ui_story_5040_50400602_34_dialog_content = "It sounds like only a few people have ever laid eyes on this thing... I've never even heard of it despite living in the desert my entire life. Have you?",
  ui_story_5040_50400602_35_dialog_content = "I've never heard of it either.",
  ui_story_5040_50400602_36_dialog_content = "Then why the heck are you making this our trial?!",
  ui_story_5040_50400602_37_dialog_content = "I'll do it! If there's even the smallest chance to restore Tara's memories, I'm willing to try.",
  ui_story_5040_50400602_38_dialog_content = "Huh?",
  ui_story_5040_50400602_39_dialog_content = "Adonis! Have you lost your mind?!",
  ui_story_5040_50400602_40_dialog_content = "To be honest, I don't feel confident at all... because I know I'm weak and timid—I can't even kill the bugs in my own house, let alone some giant sandworm...",
  ui_story_5040_50400602_41_dialog_content = "But Tara ended up like this because of me, so I have to do something about it.",
  ui_story_5040_50400602_42_dialog_content = "I know that my timid nature is what frustrated her so much in the first place... That's why I want to change.",
  ui_story_5040_50400602_43_dialog_content = "I can't back down no matter what.",
  ui_story_5040_50400602_44_dialog_content = "That was a really moving speech!",
  ui_story_5040_50400602_45_dialog_content = "Adonis! I... Actually, I—",
  ui_story_5040_50400602_46_dialog_content = "Quite the touching speech, Adonis. So you think you can defeat this sandworm all by yourself now?",
  ui_story_5040_50400602_47_dialog_content = "Of course not! I'll need all the help I can get, so please teach me how to fight!",
  ui_story_5040_50400602_48_dialog_content = "Start me off with Eclipsites if you have to! I'll do anything to get stronger!",
  ui_story_5040_50400602_49_dialog_content = "Do you even know how to fight?",
  ui_story_5040_50400602_50_dialog_content = "I seem to recall your father saying that you once studied Luminatics under Novio... Is that right?",
  ui_story_5040_50400602_51_dialog_content = "Yes! As a boy, I used to go to the library all the time, and Mr. Novio would teach me a lot.",
  ui_story_5040_50400602_52_dialog_content = "My Luminatics may not be very strong, but I have a fairly solid understanding of how to use them.",
  ui_story_5040_50400602_53_dialog_content = "Heheheh... Good!",
  ui_story_5040_50400602_54_dialog_content = "Jeriah, your expression is scaring me.",
  ui_story_5040_50400602_55_dialog_content = "Relax, we're all on the same team! It's not like I'm going to torture him or something.",
  ui_story_5040_50400602_56_dialog_content = "This will be easy. Like you said yourself, we can start with Eclipsites...",
  ui_story_5040_50400602_57_dialog_content = "W-Wait... You're seriously going to make me fight one of those things?",
  ui_story_5040_50400602_58_dialog_content = "Oh heavens, no! That would be much too cruel! No... I have an even better idea.",
  ui_story_5040_50400602_59_dialog_content = "She's a much more suitable opponent for you.",
  ui_story_5040_50400701_1_dialog_content = "What did you call me here, Lady Jeriah?",
  ui_story_5040_50400701_2_dialog_content = "Jeriah, you don't mean...",
  ui_story_5040_50400701_3_dialog_content = "Graah...?",
  ui_story_5040_50400701_4_dialog_content = "Hehe, yep! Kya's little friend is a perfect match for him, don't you think? Everything about her practically screams \"Eclipsite.\"",
  ui_story_5040_50400701_5_dialog_content = "I think she would be a wonderful sparring partner for Adonis!",
  ui_story_5040_50400701_6_dialog_content = "I mean, I know Sable doesn't look a whole lot like other Aurorians... but don't you think calling her an Eclipsite is going too far?",
  ui_story_5040_50400701_7_dialog_content = "(Still, she definitely is connected to the Eclipsites somehow.)",
  ui_story_5040_50400701_8_dialog_content = "(She's with Kya though, and hasn't caused any trouble so far. We'll just have to wait and see, I guess.)",
  ui_story_5040_50400701_9_dialog_content = "Sparring... partner...?",
  ui_story_5040_50400701_10_dialog_content = "She doesn't know how to fight! What if she gets hurt?",
  ui_story_5040_50400701_11_dialog_content = "Relax, they won't really be fighting. This is just to help Adonis find his courage, that's all.",
  ui_story_5040_50400701_12_dialog_content = "Adonis, what do you think?",
  ui_story_5040_50400701_13_dialog_content = "I-It does seem a little rude... but if Sable's willing to help, I'd be super grateful.",
  ui_story_5040_50400701_14_dialog_content = "If I were to go head-to-head with an Eclipsite right now, I'd practically be serving myself to it on a silver platter.",
  ui_story_5040_50400701_15_dialog_content = "I'm not good with Luminatics either, since I rarely use them. Usually, I just rely on Tara to protect me.",
  ui_story_5040_50400701_16_dialog_content = "You don't have to do this, Adonis. Everyone has different strengths and weaknesses.",
  ui_story_5040_50400701_17_dialog_content = "And I don't even think of needing to protect you as a burden.",
  ui_story_5040_50400701_18_dialog_content = "Tara?",
  ui_story_5040_50400701_19_dialog_content = "No... no matter what, I have to do this! I have to push myself out of my comfort zone.",
  ui_story_5040_50400701_20_dialog_content = "Kya, Sable, please help me!",
  ui_story_5040_50400701_21_dialog_content = "Hm... Sable, are you alright with this?",
  ui_story_5040_50400701_22_dialog_content = "If it means... I can help...",
  ui_story_5040_50400701_23_dialog_content = "Then... I'll do it!",
  ui_story_5040_50400701_24_dialog_content = "Don't push yourself, okay? It's just a pretend fight, nothing more.",
  ui_story_5040_50400701_25_dialog_content = "I won't...",
  ui_story_5040_50400701_26_dialog_content = "I'm... happy to help...",
  ui_story_5040_50400701_27_dialog_content = "You're the best, Sable!",
  ui_story_5040_50400701_28_dialog_content = "Graah! Graaah!!",
  ui_story_5040_50400701_29_dialog_content = "Is it just me, or did I hear an actual Eclipsite...?",
  ui_story_5040_50400701_30_dialog_content = "Huh?!",
  ui_story_5040_50400701_31_dialog_content = "<size=45>Graaahh—!</size>",
  ui_story_5040_50400701_32_dialog_content = "Watch out! There are Eclipsites here!",
  ui_story_5040_50400701_33_dialog_content = "B-But how?! Where'd they come from?!",
  ui_story_5040_50400701_34_dialog_content = "Where, indeed? You and your little black bird always seem to draw a crowd wherever you go...",
  ui_story_5040_50400701_35_dialog_content = "Could it really just be a coincidence?",
  ui_story_5040_50400701_36_dialog_content = "Hmm.",
  ui_story_5040_50400701_37_dialog_content = "(Did Sable really draw these monsters here...?)",
  ui_story_5040_50400701_38_dialog_content = "Eclip...sites...?",
  ui_story_5040_50400701_39_dialog_content = "Focus. Let's get rid of these pests first and foremost.",
  ui_story_5040_50400701_40_dialog_content = "Get behind me, Adonis!",
  ui_story_5040_50400701_41_dialog_content = "I-I know.",
  ui_story_5040_50400702_1_dialog_content = "Looks like we got them all. Is everyone all right?",
  ui_story_5040_50400702_2_dialog_content = "Of course. It was just a couple of Eclipsites, after all.",
  ui_story_5040_50400702_3_dialog_content = "I-I'm okay too.",
  ui_story_5040_50400702_4_dialog_content = "That's great for you girls, but it seems like a different story for those two over there.",
  ui_story_5040_50400702_5_dialog_content = "Ah!",
  ui_story_5040_50400702_6_dialog_content = "S... So scary...",
  ui_story_5040_50400702_7_dialog_content = "(I wonder how productive it is to have those two train each other...)",
  ui_story_5040_50400702_8_dialog_content = "Should we keep going with our training, or do you two need a break?",
  ui_story_5040_50400702_9_dialog_content = "I-I can keep going!",
  ui_story_5040_50400702_10_dialog_content = "M... Me too...!",
  ui_story_5040_50400702_11_dialog_content = "Don't push yourself, Sable.",
  ui_story_5040_50400702_12_dialog_content = "Since you're both feeling brave, let's continue.",
  ui_story_5040_50400702_13_dialog_content = "<color=#e8d9bb>15 minutes later—</color>",
  ui_story_5040_50400702_14_dialog_content = "...",
  ui_story_5040_50400702_15_dialog_content = "...",
  ui_story_5040_50400702_16_dialog_content = "Uh... are you guys gonna get started anytime soon? You've been standing around for a while now...",
  ui_story_5040_50400702_17_dialog_content = "I-I'm gonna attack now!",
  ui_story_5040_50400702_18_dialog_content = "...!!",
  ui_story_5040_50400702_19_dialog_content = "You don't look like you're about to go into battle at all.",
  ui_story_5040_50400702_20_dialog_content = "I'm really gonna do it! You better be ready!",
  ui_story_5040_50400702_21_dialog_content = "O-Okay...!",
  ui_story_5040_50400702_22_dialog_content = "<color=#e8d9bb>An hour later...</color>",
  ui_story_5040_50400702_23_dialog_content = "This time, I swear I'm going to attack!",
  ui_story_5040_50400702_24_dialog_content = "Just watch!",
  ui_story_5040_50400702_25_dialog_content = "(I'm so sleepy, I feel like I could go take a nap right now.)",
  ui_story_5040_50400702_26_dialog_content = "Like I said, Adonis, you really don't have to do this.",
  ui_story_5040_50400702_27_dialog_content = "Go Sable!!!",
  ui_story_5040_50400702_28_dialog_content = "...",
  ui_story_5040_50400702_29_dialog_content = "Do you honestly think that an Eclipsite is going to stand around for an hour and wait for you to attack?",
  ui_story_5040_50400702_30_dialog_content = "Remember, you're doing this for Tara's sake.",
  ui_story_5040_50400702_31_dialog_content = "If she fell in battle and an Eclipsite had her in its sights, would you hesitate like this?",
  ui_story_5040_50400702_32_dialog_content = "You don't need me to tell you what the outcome of that would be.",
  ui_story_5040_50400702_33_dialog_content = "I... I...",
  ui_story_5040_50400702_34_dialog_content = "Or are you telling me you don't care if she gets hurt, since you're unwilling to get past your cowardice-driven hesitance?",
  ui_story_5040_50400702_35_dialog_content = "Th-That's not true at all!",
  ui_story_5040_50400702_36_dialog_content = "Even a moment's hesitation could mean the difference between life and death. Who would want to be with someone so unreliable?",
  ui_story_5040_50400702_37_dialog_content = "<size=33>Hey! You're being way too hard on him!</size>",
  ui_story_5040_50400702_38_dialog_content = "<size=33>I feel really bad for him... Sable, why don't you give him a hand?</size>",
  ui_story_5040_50400702_39_dialog_content = "<size=45>Grah! Graaaaah!</size>",
  ui_story_5040_50400702_40_dialog_content = "<size=55>Aaaahhhh!!!</size>",
  ui_story_5040_50400702_41_dialog_content = "<color=#e8d9bb>Bonk...!</color>",
  ui_story_5040_50400702_42_dialog_content = "Haaah... Haaah...",
  ui_story_5040_50400702_43_dialog_content = "Ow...",
  ui_story_5040_50400702_44_dialog_content = "S-Sable! Are you okay?!",
  ui_story_5040_50400702_45_dialog_content = "I'm... I'm okay...",
  ui_story_5040_50400702_46_dialog_content = "He actually attacked her?",
  ui_story_5040_50400702_47_dialog_content = "You're making progress, Adonis! At least you didn't cower in the back this time!",
  ui_story_5040_50400702_48_dialog_content = "It was certainly the least harmful attack I've ever seen in my life, but the Caelestite is right.",
  ui_story_5040_50400702_49_dialog_content = "Still, you won't be landing a hit on a real Eclipsite anytime soon.",
  ui_story_5040_50400702_50_dialog_content = "What's most important is that he's making progress! Overcoming yourself is always the hardest step!",
  ui_story_5040_50400702_51_dialog_content = "Tara... Thank you!",
  ui_story_5040_50400702_52_dialog_content = "*Sniff* Thank you so much, everyone! Especially you, Sable!",
  ui_story_5040_50400702_53_dialog_content = "It's okay...",
  ui_story_5040_50400702_54_dialog_content = "Good. Now that we got that out of the way, the real training can begin.",
  ui_story_5040_50400702_55_dialog_content = "I think that's enough for today, Jeriah. It's getting pretty late, and I'm sure everyone's tired.",
  ui_story_5040_50400702_56_dialog_content = "We can take it one step at a time. Let's go back to the city for now.",
  ui_story_5040_50400702_57_dialog_content = "If you say so, little Caelestite.",
  ui_story_5040_50400702_58_dialog_content = "Urgh...",
  ui_story_5040_50400702_59_dialog_content = "Huh? What is it, Sable? Are you hurt?",
  ui_story_5040_50400702_60_dialog_content = "N... No...",
  ui_story_5040_50400702_61_dialog_content = "I... remember...",
  ui_story_5040_50400702_62_dialog_content = "Huh?!",
  ui_story_5040_50400702_63_dialog_content = "Desert... desert...",
  ui_story_5040_50400702_64_dialog_content = "As in the Rediesel Desert?",
  ui_story_5040_50400702_65_dialog_content = "Don't know... But...",
  ui_story_5040_50400702_66_dialog_content = "I just remember... the desert...",
  ui_story_5040_50400702_67_dialog_content = "I guess Adonis bonking your head jogged your memory?",
  ui_story_5040_50400702_68_dialog_content = "Well, the Rediesel Desert is conveniently our next stop.",
  ui_story_5040_50400702_69_dialog_content = "...",
  ui_story_5040_50400702_70_dialog_content = "You all look pretty beat, so let's call it a day and get some rest.",
  ui_story_5040_50400702_71_dialog_content = "All because of me. I don't know how to thank you all.",
  ui_story_5040_50400702_72_dialog_content = "This was our problem to begin with, but you've been supporting us all this time... Thank you.",
  ui_story_5040_50400702_73_dialog_content = "Why don't we go buy some Illuminan specialty snacks for everyone to show our appreciation, Tara? There's not much else we can do.",
  ui_story_5040_50400702_74_dialog_content = "Haha, you guys really don't have to do that!",
  ui_story_5040_50400702_75_dialog_content = "(I'm not sure Illumina's specialties are suitable as snacks...)",
  ui_story_5040_50400702_76_dialog_content = "That's a great idea. Let's get going before it gets too late.",
  ui_story_5040_50400702_77_dialog_content = "I... want to go...",
  ui_story_5040_50400702_78_dialog_content = "Kya, I'd like to talk to you in private. Do you have a moment?",
  ui_story_5040_50400702_79_dialog_content = "Huh? Why all of a sudden... yes, Lady Jeriah.",
  ui_story_5040_50400702_80_dialog_content = "But what about Sable...?",
  ui_story_5040_50400702_81_dialog_content = "Don't worry about her. She can go back with PlayerName.",
  ui_story_5040_50400702_82_dialog_content = "Unless there's something about her that we should know about...?",
  ui_story_5040_50400702_83_dialog_content = "N...Not at all!",
  ui_story_5040_50400702_84_dialog_content = "Would you mind taking her back, PlayerName?",
  ui_story_5040_50400702_85_dialog_content = "Of course not! Come on, Sable.",
  ui_story_5040_50400702_86_dialog_content = "Um...",
  ui_story_5040_50400702_87_dialog_content = "What's wrong?",
  ui_story_5040_50400702_88_dialog_content = "I... need to go somewhere...",
  ui_story_5040_50400702_89_dialog_content = "\"Go somewhere\"?",
  ui_story_5040_50400702_90_dialog_content = "Is there still some place you want to go?",
  ui_story_5040_50400702_91_dialog_content = "Earlier... I picked up... a letter...",
  ui_story_5040_50400702_92_dialog_content = "I want to... return it...",
  ui_story_5040_50400702_93_dialog_content = "When did you find a letter? Shouldn't we just drop it off at the Courier Union?",
  ui_story_5040_50400702_94_dialog_content = "It was... after... our training...",
  ui_story_5040_50400702_95_dialog_content = "Oh, so somewhere outside the city? A courier must've dropped it by accident.",
  ui_story_5040_50400702_96_dialog_content = "We can just take it to the Courier Union, okay?",
  ui_story_5040_50400702_97_dialog_content = "It has... an address.",
  ui_story_5040_50400702_98_dialog_content = "They must be... waiting... a long time...",
  ui_story_5040_50400702_99_dialog_content = "True. It is Mooncrown Day, after all. You wanna get it to the recipient faster, huh?",
  ui_story_5040_50400702_100_dialog_content = "If only Dove were even half as responsible as you...",
  ui_story_5040_50400702_101_dialog_content = "Here, let me take a look at the address. I'll help you deliver it.",
  ui_story_5040_50400702_102_dialog_content = "(This envelope looks pretty old... Something tells me it wasn't mailed recently.)",
  ui_story_5040_50400702_103_dialog_content = "<color=#e8d9bb>Knock, knock, knock!</color>",
  ui_story_5040_50400702_104_dialog_content = "Should be... here.",
  ui_story_5040_50400702_105_dialog_content = "Yeah, the address is right.",
  ui_story_5040_50400702_106_dialog_content = "Hello? May I help you?",
  ui_story_5040_50400702_107_dialog_content = "Sorry to bother you, but we found this letter on the ground earlier. It's addressed to this house.",
  ui_story_5040_50400702_108_dialog_content = "Is that so? Might I have a look?",
  ui_story_5040_50400702_109_dialog_content = "...Th-This can't be...!",
  ui_story_5040_50400702_110_dialog_content = "This is the correct address, right?",
  ui_story_5040_50400702_111_dialog_content = "Where exactly did you two find this letter?!",
  ui_story_5040_50400702_112_dialog_content = "My friend here found it just outside the city. She insisted on delivering it to you.",
  ui_story_5040_50400702_113_dialog_content = "Was I... helpful...?",
  ui_story_5040_50400702_114_dialog_content = "I-I don't know what to say...",
  ui_story_5040_50400702_115_dialog_content = "This is a letter for my grandmother.",
  ui_story_5040_50400702_116_dialog_content = "Your grandmother?",
  ui_story_5040_50400702_117_dialog_content = "She waited for this letter for a long time, up until the moment she passed.",
  ui_story_5040_50400702_118_dialog_content = "It's from her first love. From what she told me, he lived in Lumopolis. But because of the distance between there and Illumina, they never ended up together.",
  ui_story_5040_50400702_119_dialog_content = "My grandfather passed away a long time ago, so my grandma reconnected with her first love.",
  ui_story_5040_50400702_120_dialog_content = "They became close friends, and would always send letters to each other. They promised that they would keep sending them until the very end.",
  ui_story_5040_50400702_121_dialog_content = "But one day, his letters stopped coming, and not long after that, my grandmother fell ill and passed.",
  ui_story_5040_50400702_122_dialog_content = "I never thought that he...",
  ui_story_5040_50400702_123_dialog_content = "Sigh, fate truly makes fools of the mortal.",
  ui_story_5040_50400702_124_dialog_content = "To think there was such a story behind this letter...",
  ui_story_5040_50400702_125_dialog_content = "Sable, you really did something amazing!",
  ui_story_5040_50400702_126_dialog_content = "I'm really thankful! I won't be opening this letter. It was meant for my grandmother, so I will leave it by her grave so that it can accompany her.",
  ui_story_5040_50400702_127_dialog_content = "...",
  ui_story_5040_50400702_128_dialog_content = "This must be a Mooncrown Day miracle... I just hope his words still manage to reach her.",
  ui_story_5040_50400702_129_dialog_content = "Is this... love?",
  ui_story_5040_50400702_130_dialog_content = "That's a good question. Sometimes even I don't understand myself. How is love so powerful?",
  ui_story_5040_50400702_131_dialog_content = "Sometimes it hurts people, sometimes it saves people.",
  ui_story_5040_50400702_132_dialog_content = "In any case, how could I ever repay you two for this kindness?",
  ui_story_5040_50400702_133_dialog_content = "You don't have to thank me at all. Thank Sable here instead.",
  ui_story_5040_50400702_134_dialog_content = "That's okay...",
  ui_story_5040_50400702_135_dialog_content = "Looks like we're all done here. Ready to go back now?",
  ui_story_5040_50400702_136_dialog_content = "Yeah...",
  ui_story_5040_50400702_137_dialog_content = "<color=#e8d9bb>Meanwhile, on the other side of town...</color>",
  ui_story_5040_50400702_138_dialog_content = "What did you need to discuss with me, Lady Jeriah?",
  ui_story_5040_50400702_139_dialog_content = "...",
  ui_story_5040_50400702_140_dialog_content = "Northland birdie, entertain my curiosity for a moment. Wherever did you get yourself this relative of yours?",
  ui_story_5040_50400702_141_dialog_content = "!!",
  ui_story_5040_50400702_142_dialog_content = "Y-You mean... S-Sable?",
  ui_story_5040_50400702_143_dialog_content = "Who else would I be talking about?",
  ui_story_5040_50400702_144_dialog_content = "Um...",
  ui_story_5040_50400702_145_dialog_content = "(The atmosphere feels so stifling!)",
  ui_story_5040_50400702_146_dialog_content = "I've never been one to beat around the bush, so I'll ask you directly.",
  ui_story_5040_50400702_147_dialog_content = "She's not an Aurorian, is she?",
  ui_story_5040_50400702_148_dialog_content = "...!",
  ui_story_5040_50400702_149_dialog_content = "Let me be even more direct: She appears to be an Eclipsite who is capable of speaking Universese.",
  ui_story_5040_50400702_150_dialog_content = "Lady Jeriah...",
  ui_story_5040_50400702_151_dialog_content = "Heehee! Even though you haven't been a courier for very long, I must say I'm quite surprised by your bravery, little one.",
  ui_story_5040_50400702_152_dialog_content = "I seem to have underestimated you.",
  ui_story_5040_50400702_153_dialog_content = "I-I know it's completely out of line for me to ask, but... could you please keep this a secret?",
  ui_story_5040_50400702_154_dialog_content = "And why should I do that? What reason do I have for helping you maintain your little facade?",
  ui_story_5040_50400702_155_dialog_content = "None, there is no reason for you to help me. I don't have the right to ask for this favor either.",
  ui_story_5040_50400702_156_dialog_content = "I'm pleading you, is all.",
  ui_story_5040_50400702_157_dialog_content = "...",
  ui_story_5040_50400702_158_dialog_content = "She lost her memories and asked me to help her.",
  ui_story_5040_50400702_159_dialog_content = "Helping her serves me no purpose. If anything, it puts us all in danger. Aurorians and Eclipsites have always been at odds; we all know that.",
  ui_story_5040_50400702_160_dialog_content = "But the whole reason I became a courier was so that I could help people deliver their thoughts and feelings to each other. That's it. And I want to do the same for her.",
  ui_story_5040_50400702_161_dialog_content = "I said I'd help her without even thinking about it. It was reckless of me to do so, but I did it anyways.",
  ui_story_5040_50400702_162_dialog_content = "That's why I'm prepared to accept full responsibility for whatever happens as a result of my actions. No matter what... I swear I'll pay the price.",
  ui_story_5040_50400702_163_dialog_content = "If I said I wanted to hurt Sable, would you stand in front of her?",
  ui_story_5040_50400702_164_dialog_content = "I would.",
  ui_story_5040_50400702_165_dialog_content = "Well Kya, you're always earnest and finish what you start. Likewise, I will handle this matter appropriately.",
  ui_story_5040_50400702_166_dialog_content = "...",
  ui_story_5040_50400702_167_dialog_content = "You're far more interesting than I imagined. A little naive, but I don't dislike earnestness.",
  ui_story_5040_50400702_168_dialog_content = "I will do as you ask for now. Best of luck, Kya.",
  ui_story_5040_50400702_169_dialog_content = "So does that mean... you're helping me?",
  ui_story_5040_50400702_170_dialog_content = "Thank you! Thank you so much, Lady Jeriah.",
  ui_story_5040_50400702_171_dialog_content = "And don't worry! No matter what happens, I'll take full responsibility until the very end.",
  ui_story_5040_50400801_1_dialog_content = "Sable, thanks to you, we got to do something really meaningful in Gannon City. Come on, let's go back and get some rest now.",
  ui_story_5040_50400801_2_dialog_content = "Okay...",
  ui_story_5040_50400801_3_dialog_content = "Are you okay? Your complexion looks a bit off.",
  ui_story_5040_50400801_4_dialog_content = "My... face?",
  ui_story_5040_50400801_5_dialog_content = "Yeah. I don't mean to be rude, but you just look kind of drained, is all.",
  ui_story_5040_50400801_6_dialog_content = "Have you been getting enough vitamins lately? Or maybe you're feeling a little under the weather?",
  ui_story_5040_50400801_7_dialog_content = "I... I don't... think so...",
  ui_story_5040_50400801_8_dialog_content = "Graaah!",
  ui_story_5040_50400801_9_dialog_content = "Graaooh!!",
  ui_story_5040_50400801_10_dialog_content = "What? More Eclipsites?!",
  ui_story_5040_50400801_11_dialog_content = "This is the first time I've ever seen them in Gannon City!",
  ui_story_5040_50400801_12_dialog_content = "Aaaaaahhh! Somebody save me!!",
  ui_story_5040_50400801_13_dialog_content = "H... Hold onto... me!",
  ui_story_5040_50400801_14_dialog_content = "D-Don't be... afraid...",
  ui_story_5040_50400801_15_dialog_content = "Sable! Take the boy and get back!",
  ui_story_5040_50400802_1_dialog_content = "Whew... Are you two okay?",
  ui_story_5040_50400802_2_dialog_content = "Y-Yes...",
  ui_story_5040_50400802_3_dialog_content = "Waaaah! Y-You're so scary-looking!",
  ui_story_5040_50400802_4_dialog_content = "I...",
  ui_story_5040_50400802_5_dialog_content = "Don't worry about him, Sable. The poor kid is probably still in shock.",
  ui_story_5040_50400802_6_dialog_content = "Still, what are Eclipsites doing in the middle of Gannon City?",
  ui_story_5040_50400802_7_dialog_content = "Phew! You two did me a huge favor!",
  ui_story_5040_50400802_8_dialog_content = "J-Jola?",
  ui_story_5040_50400802_9_dialog_content = "This is one of the Eclipsites that Migard uses for testing. For some reason, it went berserk and found its way out of the laboratory.",
  ui_story_5040_50400802_10_dialog_content = "Thank goodness no one was hurt... thanks to you two, of course.",
  ui_story_5040_50400802_11_dialog_content = "An Eclipsite used for tests? You mean like the ones from earlier today?",
  ui_story_5040_50400802_12_dialog_content = "Precisely. Migard captured all kinds of Eclipsites. I don't know the precise nature of her experiments...",
  ui_story_5040_50400802_13_dialog_content = "but it seems like she goes through the captured Eclipsites pretty quickly.",
  ui_story_5040_50400802_14_dialog_content = "!!!",
  ui_story_5040_50400802_15_dialog_content = "You guys need to be more careful with your test subjects! What if this one managed to hurt somebody?",
  ui_story_5040_50400802_16_dialog_content = "Well, this sort of thing has never happened before. Maybe there's something on you guys that drew it out.",
  ui_story_5040_50400802_17_dialog_content = "Speaking of, Sable, we could have Migard take a look at you. She has all kinds of medicine in her lab.",
  ui_story_5040_50400802_18_dialog_content = "If you're not feeling well, I'm sure she'll be able to help!",
  ui_story_5040_50400802_19_dialog_content = "No... No, thanks!",
  ui_story_5040_50400802_20_dialog_content = "I... just remembered... something important!",
  ui_story_5040_50400802_21_dialog_content = "I need... to go... find Kya!",
  ui_story_5040_50400802_22_dialog_content = "Huh?!",
  ui_story_5040_50400802_23_dialog_content = "Heheheh... Quite the interesting friend you have there.",
  ui_story_5040_50400802_24_dialog_content = "(It's getting late... Sable and the others are probably waiting for me. I should get going.)",
  ui_story_5040_50400802_25_dialog_content = "K... Kya!!!",
  ui_story_5040_50400802_26_dialog_content = "Sable? What are you doing here? Shouldn't you be with PlayerName right now?",
  ui_story_5040_50400802_27_dialog_content = "I want... to be with you... Kya.",
  ui_story_5040_50400802_28_dialog_content = "I see... then let's head back together.",
  ui_story_5040_50400802_29_dialog_content = "<color=#e8d9bb>Growl...</color>",
  ui_story_5040_50400802_30_dialog_content = "What... was that...?",
  ui_story_5040_50400802_31_dialog_content = "Oh, that? Sorry, that was just my stomach.",
  ui_story_5040_50400802_32_dialog_content = "I haven't eaten anything all day. I'm starving!",
  ui_story_5040_50400802_33_dialog_content = "M... Me, too...",
  ui_story_5040_50400802_34_dialog_content = "You too? Come on, we can find a nice place to eat before we turn in for the night.",
  ui_story_5040_50400802_35_dialog_content = "No! I... I look... People are... scared...",
  ui_story_5040_50400802_36_dialog_content = "Sable...?",
  ui_story_5040_50400802_37_dialog_content = "Don't say that. You may not look like most Aurorians, but you're kind all the same.",
  ui_story_5040_50400802_38_dialog_content = "We can just buy some bread to-go though. Does that sound good to you?",
  ui_story_5040_50400802_39_dialog_content = "Yes...",
  ui_story_5040_50400802_40_dialog_content = "So has the Illumina Federation reminded you of anything else, Sable?",
  ui_story_5040_50400802_41_dialog_content = "No...",
  ui_story_5040_50400802_42_dialog_content = "That's okay! At least you remembered the desert, right? I bet we'll have better luck once we get there.",
  ui_story_5040_50400802_43_dialog_content = "Don't worry.",
  ui_story_5040_50400802_44_dialog_content = "Thank you...",
  ui_story_5040_50400802_45_dialog_content = "Hmm, I think I saw a merchant selling home-baked orange bread by the station. Wait here for me.",
  ui_story_5040_50400802_46_dialog_content = "I'll be back soon, don't go anywhere!",
  ui_story_5040_50400802_47_dialog_content = "...!",
  ui_story_5040_50400802_48_dialog_content = "That sounded... familiar...",
  ui_story_5040_50400802_49_dialog_content = "I'll be back soon, just wait for me here!",
  ui_story_5040_50400802_50_dialog_content = "Don't go anywhere, I'll be back as soon as I buy it.",
  ui_story_5040_50400802_51_dialog_content = "Edward, what's talking you so long? Why are you not back yet?",
  ui_story_5040_50400802_52_dialog_content = "Why aren't you coming back?",
  ui_story_5040_50400802_53_dialog_content = "Is it because I'm not good enough? Why... Why?!",
  ui_story_5040_50400802_54_dialog_content = "<size=45>Come back!!!</size>",
  ui_story_5040_50400802_55_dialog_content = "Feeling hopeless? As if there's nothing to depend on in the world? Accept this seed, and you'll never be afraid of anything ever again.",
  ui_story_5040_50400802_56_dialog_content = "Free yourself from the suffering of the weak, for you shall become stronger than you could ever imagine!",
  ui_story_5040_50400802_57_dialog_content = "Aaaaaahhh!!!",
  ui_story_5040_50400802_58_dialog_content = "Look, Sable! It's Mooncrown Day, so I managed to get cinnamon rolls. I bet you'll love it.",
  ui_story_5040_50400802_59_dialog_content = "Sable...?",
  ui_story_5040_50400802_60_dialog_content = "Aaaah! Look sis, an Eclipsite!",
  ui_story_5040_50400802_61_dialog_content = "There's an Eclipsite in the city!",
  ui_story_5040_50400802_62_dialog_content = "Wait... are you sure? Maybe it's something else...",
  ui_story_5040_50400802_63_dialog_content = "Should we call the Legion?",
  ui_story_5040_50400802_64_dialog_content = "!!!",
  ui_story_5040_50400802_65_dialog_content = "Out of the way!",
  ui_story_5040_50400802_66_dialog_content = "Sable? Sable! Are you okay?!",
  ui_story_5040_50400802_67_dialog_content = "Ah...",
  ui_story_5040_50400802_68_dialog_content = "Come on, Sable! We have to get out of here!",
  ui_story_5040_50400802_69_dialog_content = "Wait, you two! Name yourselves!",
  ui_story_5040_50400802_70_dialog_content = "Gasp... Gasp...",
  ui_story_5040_50400802_71_dialog_content = "Quiet!",
  ui_story_5040_50400802_72_dialog_content = "*Whimpers*",
  ui_story_5040_50400802_73_dialog_content = "We'll be in huge trouble if they find us!",
  ui_story_5040_50400802_74_dialog_content = "Did you happen to see a strange-looking Eclipsite around here? She was with a girl.",
  ui_story_5040_50400802_75_dialog_content = "Oh my, that sounds troublesome. I believe they were trying to escape to the surface... Should I call for more soldiers?",
  ui_story_5040_50400802_76_dialog_content = "What? How did they get there so quickly?! After them!",
  ui_story_5040_50400802_77_dialog_content = "Jeriah... Thank you.",
  ui_story_5040_50400802_78_dialog_content = "Looks like the coast is clear. Are you hurt, Sable? Let me take a look!",
  ui_story_5040_50400802_79_dialog_content = "I'm... fine.",
  ui_story_5040_50400802_80_dialog_content = "Sorry for... making you worry...",
  ui_story_5040_50400802_81_dialog_content = "What are you saying? I could never forgive myself if you got hurt while I was off buying snacks.",
  ui_story_5040_50400802_82_dialog_content = "...Kya.",
  ui_story_5040_50400802_83_dialog_content = "I... I remembered something.",
  ui_story_5040_50400802_84_dialog_content = "Really? What did you remember?",
  ui_story_5040_50400802_85_dialog_content = "A person... Someone who... said the same things... as you.",
  ui_story_5040_50400802_86_dialog_content = "But... he never... came back.",
  ui_story_5040_50400802_87_dialog_content = "I went somewhere... somewhere far away... to look for him.",
  ui_story_5040_50400802_88_dialog_content = "He told me... that he liked me...",
  ui_story_5040_50400802_89_dialog_content = "But... in the end... he left me.",
  ui_story_5040_50400802_90_dialog_content = "I ran... ran from home... I was scared...",
  ui_story_5040_50400802_91_dialog_content = "But then... someone gave me... a seed.",
  ui_story_5040_50400802_92_dialog_content = "Told me... to get stronger.",
  ui_story_5040_50400802_93_dialog_content = "So you are an Aurorian, after all!",
  ui_story_5040_50400802_94_dialog_content = "But how could something like this happen?!",
  ui_story_5040_50400802_95_dialog_content = "That potion... woke me up...",
  ui_story_5040_50400802_96_dialog_content = "But I... forgot everything... don't trust anything...",
  ui_story_5040_50400802_97_dialog_content = "I just... want to... go home.",
  ui_story_5040_50400802_98_dialog_content = "Sable...",
  ui_story_5040_50400802_99_dialog_content = "Don't worry, Sable. I promise I'll take you back to your home.",
  ui_story_5040_50400802_100_dialog_content = "We're leaving for the Rediesel Desert first thing tomorrow morning. That could be where your home is.",
  ui_story_5040_50400802_101_dialog_content = "Thank you... Kya.",
  ui_story_5040_50400802_102_dialog_content = "My mind... lately, I... can feel it... slipping away again.",
  ui_story_5040_50400802_103_dialog_content = "I don't know... how long... I can hold on.",
  ui_story_5040_50400802_104_dialog_content = "If I... lose it... You'll have to...",
  ui_story_5040_50400802_105_dialog_content = "Don't say anything else! I'll make sure you see your home before that happens. We might even find a way to keep your consciousness from fading away!",
  ui_story_5040_50400802_106_dialog_content = "Remember the pink sandworm? I'm sure we'll find a solution.",
  ui_story_5040_50400802_107_dialog_content = "Kya...",
  ui_story_5040_50400802_108_dialog_content = "We're leaving tomorrow, there's no time to waste.",
  ui_story_5040_50400802_109_dialog_content = "You're going home, Sable.",
  ui_story_5040_50400901_1_dialog_content = "Here we are. Make yourself at home.",
  ui_story_5040_50400901_2_dialog_content = "So this is the Rediesel Wrench division of the Courier Union, huh?",
  ui_story_5040_50400901_3_dialog_content = "The outside might be a little dilapidated, but it's gorgeous in here! Totally not what I was expecting.",
  ui_story_5040_50400901_X3_dialog_content = "Right, not to mention the location is so hard to find!",
  ui_story_5040_50400901_X4_dialog_content = "The Rediesel Wrench base's buildings are all built so haphazardly, it's difficult to even find the road...",
  ui_story_5040_50400901_X5_dialog_content = "You have to twist and turn through alleyways for a good ten minutes before even reaching this place!",
  ui_story_5040_50400901_X6_dialog_content = "It took me ages to find it when I first came here.",
  ui_story_5040_50400901_X7_dialog_content = "That means you have a good sense of direction!",
  ui_story_5040_50400901_X8_dialog_content = "When I first came here, it took me so long to find it, I almost gave up.",
  ui_story_5040_50400901_4_dialog_content = "Even though this is my second time seeing these decorations, they're still so surprising.",
  ui_story_5040_50400901_5_dialog_content = "It's not just the decor, either. There are so many fine ornaments inside that it's blinding.",
  ui_story_5040_50400901_6_dialog_content = "It really doesn't seem like Rediesel Wrench's style!",
  ui_story_5040_50400901_7_dialog_content = "What sort of vulgar cretin do you take me for?",
  ui_story_5040_50400901_8_dialog_content = "That's not what I meant...",
  ui_story_5040_50400901_9_dialog_content = "It's fine, I was teasing.",
  ui_story_5040_50400901_10_dialog_content = "Jeriah, I was hoping to have a look around with Sable...",
  ui_story_5040_50400901_11_dialog_content = "No problem. Go poke around wherever you like.",
  ui_story_5040_50400901_12_dialog_content = "Really?",
  ui_story_5040_50400901_13_dialog_content = "Just remember to put everything back where you found it.",
  ui_story_5040_50400901_14_dialog_content = "Of course!",
  ui_story_5040_50400901_15_dialog_content = "Let's go, Sable!",
  ui_story_5040_50400901_16_dialog_content = "I should go get the car and weapons ready too.",
  ui_story_5040_50400901_17_dialog_content = "It'll be evening soon. You guys should just rest here tonight.",
  ui_story_5040_50400901_18_dialog_content = "The car? Wouldn't it be faster to use the Colossus?",
  ui_story_5040_50400901_X18_dialog_content = "And the Colossus is so big. It looks much safer than a car.",
  ui_story_5040_50400901_19_dialog_content = "Sandworms know their way around above and below ground.",
  ui_story_5040_50400901_20_dialog_content = "They're crafty little devils, adept at navigating underground caverns.",
  ui_story_5040_50400901_21_dialog_content = "If you don't grab them the first second you can, they'll vanish.",
  ui_story_5040_50400901_X21_dialog_content = "What?!",
  ui_story_5040_50400901_X22_dialog_content = "Jeriah is right.",
  ui_story_5040_50400901_22_dialog_content = "The Colossus may be fast, but as a passenger, there's no way to engage them at first sighting.",
  ui_story_5040_50400901_X23_dialog_content = "I've experienced it firsthand, trust me.",
  ui_story_5040_50400901_23_dialog_content = "I see...",
  ui_story_5040_50400901_24_dialog_content = "You have a lot more to learn about the desert.",
  ui_story_5040_50400901_25_dialog_content = "I should be going. We'll head out first thing tomorrow morning to go sandworm hunting.",
  ui_story_5040_50400901_26_dialog_content = "<color=#e8d9bb>*Rumble*</color>",
  ui_story_5040_50400901_27_dialog_content = "Sorry!",
  ui_story_5040_50400901_28_dialog_content = "We've been so busy, I totally forgot about eating.",
  ui_story_5040_50400901_29_dialog_content = "<color=#e8d9bb>*Rrrumble*</color>",
  ui_story_5040_50400901_30_dialog_content = "I'm pretty hungry too.",
  ui_story_5040_50400901_31_dialog_content = "Well, since we're in the desert, allow me to prepare some Rediesel Wrench specialties for you!",
  ui_story_5040_50400901_32_dialog_content = "Let me get a fire going outside, and we'll have some barbecue!",
  ui_story_5040_50400901_33_dialog_content = "I'll help!",
  ui_story_5040_50400901_34_dialog_content = "And then there was one.",
  ui_story_5040_50400901_35_dialog_content = "I probably shouldn't third wheel Tara and Adonis, but I don't think Kya and Sable need any help either.",
  ui_story_5040_50400901_36_dialog_content = "Anyways, I'm just wondering if the lot of us could even handle a sandworm as large as it's rumored to be.",
  ui_story_5040_50400901_37_dialog_content = "Jeriah seems pretty strong, and Tara's a good fighter... but I'm still a little worried.",
  ui_story_5040_50400901_38_dialog_content = "I should go find Jeriah, see if she thinks we need some backup.",
  ui_story_5040_50400901_39_dialog_content = "Did you come find me because you were concerned, little Caelestite?",
  ui_story_5040_50400901_40_dialog_content = "P-Please don't call me that.",
  ui_story_5040_50400901_41_dialog_content = "There's no need to worry. I know this desert like the back of my hand.",
  ui_story_5040_50400901_42_dialog_content = "I've already inspected the car and readied the supplies. Just look after yourselves and you'll be fine.",
  ui_story_5040_50400901_43_dialog_content = "But sandworms are formidable beasts. I worry that we won't be able to handle it by ourselves.",
  ui_story_5040_50400901_44_dialog_content = "Should we enlist some others to help? What about Sinsa, Azure and that lot?",
  ui_story_5040_50400901_45_dialog_content = "There's no need.",
  ui_story_5040_50400901_46_dialog_content = "But...",
  ui_story_5040_50400901_47_dialog_content = "I don't need anyone's help.",
  ui_story_5040_50400901_48_dialog_content = "Just me alone will do. It's just a sandworm, a few hits will take it down.",
  ui_story_5040_50400901_49_dialog_content = "Now if there's nothing else you need, you can head back.",
  ui_story_5040_50400901_50_dialog_content = "I have other things to do, and don't need to be bothered by the concerns of children.",
  ui_story_5040_50400901_51_dialog_content = "...",
  ui_story_5040_50400901_52_dialog_content = "Okay.",
  ui_story_5040_50400901_S52_dialog_content = "I'd better get back to Soroz.",
  ui_story_5040_50400901_53_dialog_content = "Wow... I really just got chased off by Jeriah.",
  ui_story_5040_50400901_54_dialog_content = "Forget it. If she wants me to mind my own business, that's just what I'll do!",
  ui_story_5040_50400901_55_dialog_content = "...",
  ui_story_5040_50400901_X55_dialog_content = "(This whole time, Jeriah's always come across as someone who finds amusement in watching things go down.)",
  ui_story_5040_50400901_X56_dialog_content = "(Even if she's a senior member of the Courier Union, I still can't trust her.)",
  ui_story_5040_50400901_X57_dialog_content = "(I'm just gonna send a terminal message to the Rediesel Wrench folks to be safe.)",
  ui_story_5040_50400901_X58_dialog_content = "(Hopefully someone's nearby and will respond...)",
  ui_story_5040_50400901_56_dialog_content = "<color=#e8d9bb>Beep—</color>",
  ui_story_5040_50400901_57_dialog_content = "Hello PlayerName, this is Odi. Do you copy?",
  ui_story_5040_50400901_58_dialog_content = "Odi!",
  ui_story_5040_50400901_59_dialog_content = "Copy! This is great, I didn't actually expect anyone to reply!",
  ui_story_5040_50400901_60_dialog_content = "What can I do for you?",
  ui_story_5040_50400901_61_dialog_content = "Do you happen to know anything about a pink sandworm?",
  ui_story_5040_50400901_62_dialog_content = "A pink... sandworm? Hmm, that rings a bell.",
  ui_story_5040_50400901_63_dialog_content = "I think Sinsa ran into one about a month ago.",
  ui_story_5040_50400901_64_dialog_content = "No one had ever seen a sandworm like that before, so everyone rushed out to try and capture it, but it got away.",
  ui_story_5040_50400901_65_dialog_content = "I don't have the precise details. Let me get the boss over, and you can ask him yourself.",
  ui_story_5040_50400901_66_dialog_content = "Sure. Sorry for the hassle!",
  ui_story_5040_50400901_67_dialog_content = "Yo, PlayerName! What's up?",
  ui_story_5040_50400901_68_dialog_content = "Odi says you were asking about the pink sandworm?",
  ui_story_5040_50400901_69_dialog_content = "Yup. What can you tell me?",
  ui_story_5040_50400901_70_dialog_content = "What do you wanna know? That brute is one of the few sandworms that could get away from me.",
  ui_story_5040_50400901_71_dialog_content = "A month or so ago, I was dead set on hunting it down, but at the end of the day it got away, and I only managed to come home with a scale.",
  ui_story_5040_50400901_72_dialog_content = "Tsk... Such a shame. That one scale alone sold for a pretty penny. Imagine what you could make if you caught a whole one!",
  ui_story_5040_50400901_73_dialog_content = "After all, no one had ever seen a pink sandworm before. Who's to say if it wasn't the only one in the whole world? And you know that the rarer something is, the more it costs!",
  ui_story_5040_50400901_74_dialog_content = "Why're you after a pink sandworm anyway? Let me guess, are you with Jeriah?",
  ui_story_5040_50400901_75_dialog_content = "How did you know?!",
  ui_story_5040_50400901_76_dialog_content = "Because that Speaker of Jeriah's is all over the place, flying hither and yon between all the usual sandworm stomping grounds.",
  ui_story_5040_50400901_77_dialog_content = "And if you're looking for a sandworm right now, I reckon chances are good that you're looking for that big pink fella.",
  ui_story_5040_50400901_78_dialog_content = "It's insane to be using that much Luminatics.",
  ui_story_5040_50400901_79_dialog_content = "Do you know where it is??",
  ui_story_5040_50400901_80_dialog_content = "Course I do. But that info's gonna cost you, kid. What have you got in exchange?",
  ui_story_5040_50400901_81_dialog_content = "Um... I...",
  ui_story_5040_50400901_82_dialog_content = "Hahaha... Look at you, shaking like that! What, you think I'm tryin' to swindle you or something?",
  ui_story_5040_50400901_83_dialog_content = "Just remember to bring some chocolate for Eve the next time you come here, and we're good.",
  ui_story_5040_50400901_84_dialog_content = "She heard that Umbraton's got some special, limited-edition chocolate for this Crown-whatever festival and she's been asking for it.",
  ui_story_5040_50400901_85_dialog_content = "You're always on that Colossus of yours flying all over anyway, so just help her grab some on the way.",
  ui_story_5040_50400901_86_dialog_content = "Of course.",
  ui_story_5040_50400901_87_dialog_content = "Well then, we have ourselves a deal.",
  ui_story_5040_50400901_88_dialog_content = "Last time I fought that dang thing, it was slippery as hell, always finding somewhere to hide.",
  ui_story_5040_50400901_89_dialog_content = "But I got a good whack with my wrench before it got away, which ripped that scale off its left side.",
  ui_story_5040_50400901_90_dialog_content = "I chased it for days, but eventually lost the trail. The last place I saw it was deep in the desert, near the Oasis.",
  ui_story_5040_50400901_91_dialog_content = "I can't tell you its precise location, however.",
  ui_story_5040_50400901_92_dialog_content = "If you're looking to take it on, you might as well start your search from there.",
  ui_story_5040_50400901_93_dialog_content = "Got it! Thanks a lot, Sinsa.",
  ui_story_5040_50400901_94_dialog_content = "If you have Jeriah with you, I doubt that thing'll be much trouble. But be cautious, it's one helluva trickster.",
  ui_story_5040_50400901_95_dialog_content = "What makes you say that? Do you know Jeriah well?",
  ui_story_5040_50400901_96_dialog_content = "I wouldn't say that. She keeps to herself and doesn't speak much to the rest of us.",
  ui_story_5040_50400901_97_dialog_content = "But being able to survive alone in the Rediesel Desert is evidence of her strength.",
  ui_story_5040_50400901_98_dialog_content = "Besides, she's one of only a handful of couriers in the desert, so we really rely on her.",
  ui_story_5040_50400901_99_dialog_content = "Just don't worry, do what she says, and you'll be fine!",
  ui_story_5040_50400901_100_dialog_content = "Okay...",
  ui_story_5040_50400901_101_dialog_content = "Got it!",
  ui_story_5040_50400901_102_dialog_content = "Anyway, I should probably go, or Eve'll be pestering me to go rest.",
  ui_story_5040_50400901_103_dialog_content = "Alright, see you!",
  ui_story_5040_50400901_104_dialog_content = "I should probably not go straight to Jeriah right now. First, I'll go fill in the others.",
  ui_story_5040_50400901_105_dialog_content = "Not to mention that I'm also starving! Let's see what's on the menu today!",
  ui_story_5040_50400901_106_dialog_content = "<color=#e8d9bb>Meanwhile, at the Courier Union Rediesel Wrench division...</color>",
  ui_story_5040_50400901_107_dialog_content = "All the backlogged letters should be here.",
  ui_story_5040_50400901_108_dialog_content = "With the vast desert and all the Rediesel Wrench guys running around all over the place, it's no surprise there are a lot of unclaimed mail.",
  ui_story_5040_50400901_109_dialog_content = "It'll probably take a while to find what we're looking for.",
  ui_story_5040_50400901_110_dialog_content = "Sable... will... help...",
  ui_story_5040_50400901_111_dialog_content = "We'll work together! First we need to see just how many letters there are.",
  ui_story_5040_50400901_112_dialog_content = "So many!",
  ui_story_5040_50400901_113_dialog_content = "Hang on, these have notes on them.",
  ui_story_5040_50400901_114_dialog_content = "\"Missing Addressee,\" \"Addressee Unknown,\" \"Rejected\"...",
  ui_story_5040_50400901_115_dialog_content = "Have they really all been filed under different categories?!",
  ui_story_5040_50400901_116_dialog_content = "Kya... look... there.",
  ui_story_5040_50400901_117_dialog_content = "This one says \"Same Stamp\"?!",
  ui_story_5040_50400901_118_dialog_content = "There are some words scribbled under, which say, \"Suspect the sender is the same person.\"",
  ui_story_5040_50400901_119_dialog_content = "The stamp here is the same as yours, Sable.",
  ui_story_5040_50400901_120_dialog_content = "These... are... mine...",
  ui_story_5040_50400901_121_dialog_content = "I can't believe we found what we were looking for so quickly. Thank goodness!",
  ui_story_5040_50400901_122_dialog_content = "Let's have a look at the letters.",
  ui_story_5040_50400901_123_dialog_content = "Yes...",
  ui_story_5040_50400901_124_dialog_content = "\"Thanks for agreeing to be my pen pal! It's nice to meet you.\"",
  ui_story_5040_50400901_125_dialog_content = "\"The desert is too hot for most people, so everyone seems to live really far away. We have to rely on couriers to communicate.\"",
  ui_story_5040_50400901_126_dialog_content = "\"If we could travel together, I'd be happy to leave the desert.\"",
  ui_story_5040_50400901_127_dialog_content = "These letters seem to have been written when you were first getting to know the recipient.",
  ui_story_5040_50400901_128_dialog_content = "The recipient's address is always different, and there's no sender address.",
  ui_story_5040_50400901_129_dialog_content = "Could your home have been out in the desert?",
  ui_story_5040_50400901_130_dialog_content = "Mm...",
  ui_story_5040_50400901_131_dialog_content = "Ah!!",
  ui_story_5040_50400901_132_dialog_content = "Sable?!",
  ui_story_5040_50400901_133_dialog_content = "I... remember...",
  ui_story_5040_50400901_134_dialog_content = "My home... deep desert...",
  ui_story_5040_50400901_135_dialog_content = "But... where... don't remember...",
  ui_story_5040_50400901_136_dialog_content = "That doesn't matter, this is already a really useful lead. Next, we just have to ask the people who live out in the desert!",
  ui_story_5040_50400901_137_dialog_content = "Don't push yourself to remember too hard. Have a break first.",
  ui_story_5040_50400901_138_dialog_content = "I accepted your request, so the courier in me will do my utmost to help you.",
  ui_story_5040_50400901_139_dialog_content = "Okay...",
  ui_story_5040_50400901_140_dialog_content = "What's wrong, Sable? You seem a bit listless.",
  ui_story_5040_50400901_141_dialog_content = "Tara, Adonis... Good relationship...",
  ui_story_5040_50400901_142_dialog_content = "Cherish... each other... help... each other...",
  ui_story_5040_50400901_143_dialog_content = "I... want...",
  ui_story_5040_50400901_144_dialog_content = "(Sable wasn't treated well by the person she loved, nor was her love reciprocated.)",
  ui_story_5040_50400901_145_dialog_content = "(Seeing those two so happy must make her feel sad...)",
  ui_story_5040_50400901_146_dialog_content = "Don't feel bad. That guy who treated you so badly is all in the past now!",
  ui_story_5040_50400901_147_dialog_content = "My elders always tell me that in their experience, karma always gets those who don't treat others well.",
  ui_story_5040_50400901_148_dialog_content = "As for Tara and Adonis, if being around them upsets you, we can just get out of here and continue on ourselves.",
  ui_story_5040_50400901_149_dialog_content = "It's... okay...",
  ui_story_5040_50400901_150_dialog_content = "They... remind me... happier times...",
  ui_story_5040_50400901_151_dialog_content = "Family... Friends... Love...",
  ui_story_5040_50400901_152_dialog_content = "That warm feeling... Is all I've ever wanted...",
  ui_story_5040_50400901_153_dialog_content = "That warmth... is precious, so I... wish them well...",
  ui_story_5040_50400901_154_dialog_content = "Okay...",
  ui_story_5040_50400901_155_dialog_content = "<color=#e8d9bb>*Rrrumble*</color>",
  ui_story_5040_50400901_156_dialog_content = "Hungry...",
  ui_story_5040_50400901_157_dialog_content = "Me too. Let's go get a bite to eat!",
  ui_story_5040_50400901_158_dialog_content = "(I didn't realize it had gotten so late, and I don't know how Tara and the others are getting on with dinner.)",
  ui_story_5040_50400901_159_dialog_content = "Achoo!",
  ui_story_5040_50400901_160_dialog_content = "(T-This pungent, spicy taste can only be... Rediesel barbecue!)",
  ui_story_5040_50400901_161_dialog_content = "Hm? Kya, Sable, weren't you two just exploring?",
  ui_story_5040_50400901_162_dialog_content = "We're already done, and since we're starving, we decided to come back and see how dinner was getting on!",
  ui_story_5040_50400901_163_dialog_content = "Yes...",
  ui_story_5040_50400901_164_dialog_content = "(I had no idea that the backlog of mail had already been separated and categorized.)",
  ui_story_5040_50400901_165_dialog_content = "(They were even organized together by sender based on tiny similarities!)",
  ui_story_5040_50400901_166_dialog_content = "(It was only thanks to that, that we managed to find Sable's mail so quickly.)",
  ui_story_5040_50400901_167_dialog_content = "(I suppose that was all Jeriah.)",
  ui_story_5040_50400901_168_dialog_content = "It's sure lively around here.",
  ui_story_5040_50400901_169_dialog_content = "That smell... ha. You Rediesel Wrench folks only know how to cook fiery barbecue, huh?",
  ui_story_5040_50400901_170_dialog_content = "When you're in the desert, you eat like a desert dweller.",
  ui_story_5040_50400901_171_dialog_content = "Did you get everything done, Jeriah?",
  ui_story_5040_50400901_172_dialog_content = "Yes. The car and supplies are all ready, and I also identified the sandworm's active range.",
  ui_story_5040_50400901_173_dialog_content = "It's wounded from an earlier attack, so it's currently headed deeper into the desert.",
  ui_story_5040_50400901_174_dialog_content = "(That aligns with what Sinsa told me.)",
  ui_story_5040_50400901_175_dialog_content = "(Better not to say anything, in case Jeriah gets upset again...)",
  ui_story_5040_50400901_176_dialog_content = "Perfect timing! The lizard jerky is ready, come and have some!",
  ui_story_5040_50400901_177_dialog_content = "Is this really a skewer? You can't even see anything under all the chili.",
  ui_story_5040_50400901_178_dialog_content = "This is known as ultra-spicy lizard jerky. Only the bravest culinary adventurers dare taste this pinnacle of Rediesel cuisine.",
  ui_story_5040_50400901_179_dialog_content = "Er, do I have to?",
  ui_story_5040_50400901_180_dialog_content = "There's so much chili on it, just looking at it makes my eyes burn.",
  ui_story_5040_50400901_181_dialog_content = "Are you going to have some or not?",
  ui_story_5040_50400901_182_dialog_content = "Yes! Of course I am.",
  ui_story_5040_50400901_183_dialog_content = "Don't force yourself, Adonis.",
  ui_story_5040_50400901_184_dialog_content = "*Munch*",
  ui_story_5040_50400901_185_dialog_content = "...",
  ui_story_5040_50400901_186_dialog_content = "He- He ate it all at once?",
  ui_story_5040_50400901_187_dialog_content = "...!",
  ui_story_5040_50400901_188_dialog_content = "<color=#e8d9bb>Thump!</color>",
  ui_story_5040_50400901_189_dialog_content = "A-Adonis?!",
  ui_story_5040_50400901_190_dialog_content = "Hahaha, would you look at that! He's gone totally purple!",
  ui_story_5040_50400901_191_dialog_content = "Spicy...",
  ui_story_5040_50400901_192_dialog_content = "<size=45>SO SPICY!!</size>",
  ui_story_5040_50400901_193_dialog_content = "Whoa, he looks like he's about to faint!",
  ui_story_5040_50400901_194_dialog_content = "Quick, someone get him some milk! I heard milk is good for counteracting spicy food!",
  ui_story_5040_50400901_195_dialog_content = "I'll go look!",
  ui_story_5040_50400901_196_dialog_content = "...",
  ui_story_5040_50400901_197_dialog_content = "(Why'd she go? I'm gonna go see what's up.)",
  ui_story_5040_50400901_198_dialog_content = "I found some milk!",
  ui_story_5040_50400901_199_dialog_content = "Adonis, drink this!",
  ui_story_5040_50400901_200_dialog_content = "*Glug glug glug*",
  ui_story_5040_50400901_201_dialog_content = "Ah... Ahhh... Am I still breathing...?",
  ui_story_5040_50400901_202_dialog_content = "You just ate an entire skewer of ultra-spicy lizard jerky, then keeled right over.",
  ui_story_5040_50400901_203_dialog_content = "Really?",
  ui_story_5040_50400901_204_dialog_content = "Urgh... My stomach hurts, like I've swallowed a chunk of burning coal...",
  ui_story_5040_50400901_205_dialog_content = "<size=45><anim type=Shake>Urgh!</anim></size>",
  ui_story_5040_50400901_206_dialog_content = "Adonis?!!",
  ui_story_5040_50400901_207_dialog_content = "<color=#e8d9bb>Meanwhile...</color>",
  ui_story_5040_50400901_208_dialog_content = "Your little boyfriend is vomiting his brains out over there. Aren't you going to go see if he's alright?",
  ui_story_5040_50400901_209_dialog_content = "Or have you got another bright idea?",
  ui_story_5040_50400901_210_dialog_content = "I'm going to take Adonis back to Northland as soon as he recovers.",
  ui_story_5040_50400901_211_dialog_content = "I'm exhausted. I don't want to do this anymore.",
  ui_story_5040_50400901_212_dialog_content = "We're not meant to be together. We're not compatible.",
  ui_story_5040_50400901_213_dialog_content = "Oh?",
  ui_story_5040_50400901_214_dialog_content = "I used to think that as long as we were together, we could overcome anything.",
  ui_story_5040_50400901_215_dialog_content = "I always wanted to give him a taste of the Rediesel Desert life, like the barbecue just now...",
  ui_story_5040_50400901_216_dialog_content = "but I never thought that the things I liked would actually cause him harm.",
  ui_story_5040_50400901_217_dialog_content = "He keeps getting hurt, all because he's forcing himself to pander to me.",
  ui_story_5040_50400901_218_dialog_content = "I don't think that's love.",
  ui_story_5040_50400901_X218_dialog_content = "Sigh... birdies in love certainly jump to all sorts of conclusions over trifling matters.",
  ui_story_5040_50400901_X219_dialog_content = "Why do you think that?",
  ui_story_5040_50400901_219_dialog_content = "There's just such a chasm between us, whether in lifestyle or personality. Maybe his parents were right.",
  ui_story_5040_50400901_220_dialog_content = "Northland birds lack thin feathers and don't know how to dig for water, so of course they can't survive in the desert.",
  ui_story_5040_50400901_221_dialog_content = "...",
  ui_story_5040_50400901_222_dialog_content = "This isn't something that any amount of bravery can overcome. It's a matter of innate differences.",
  ui_story_5040_50400901_223_dialog_content = "What's commonplace for desert birds is dangerous for Northland ones.",
  ui_story_5040_50400901_224_dialog_content = "But...",
  ui_story_5040_50400901_225_dialog_content = "But what?",
  ui_story_5040_50400901_226_dialog_content = "That little bird of yours can't handle anything spicy, yet he gobbled down a skewer anyway and ended up on the floor.",
  ui_story_5040_50400901_227_dialog_content = "Surely he wanted to show you, if just for a moment, his willingness to step up and be brave?",
  ui_story_5040_50400901_228_dialog_content = "You guys can find a lifestyle that works for both of you gradually.",
  ui_story_5040_50400901_229_dialog_content = "Rather than limit yourselves to living only the Rediesel lifestyle.",
  ui_story_5040_50400901_230_dialog_content = "...!",
  ui_story_5040_50400901_231_dialog_content = "That's all I wished to say.",
  ui_story_5040_50400901_232_dialog_content = "Whether or not you two end up together, you're here right now, so you might as well enjoy it.",
  ui_story_5040_50400901_233_dialog_content = "Relax, have fun, and don't bring down the atmosphere.",
  ui_story_5040_50400901_234_dialog_content = "...",
  ui_story_5040_50400901_235_dialog_content = "Hmm.",
  ui_story_5040_50400901_236_dialog_content = "I'm going back.",
  ui_story_5040_50400901_237_dialog_content = "What an interesting little bird.",
  ui_story_5040_50400901_238_dialog_content = "I'm curious what the next chapter of your relationship will bring.",
  ui_story_5040_50400901_239_dialog_content = "... Ha, what's happened to me?",
  ui_story_5040_50400901_240_dialog_content = "I can't believe I even care.",
  ui_story_5040_50401001_1_dialog_content = "Ah, you've come already?",
  ui_story_5040_50401001_2_dialog_content = "We agreed to look for the sandworm today, so I got up especially early.",
  ui_story_5040_50401001_3_dialog_content = "Plus no one was brave enough to eat those skewers, so we eventually had to go find something to eat on Soroz...",
  ui_story_5040_50401001_4_dialog_content = "You people just don't appreciate good food. But don't worry, I ate the rest of the barbecue.",
  ui_story_5040_50401001_5_dialog_content = "Not one bite went to waste!",
  ui_story_5040_50401001_6_dialog_content = "I definitely approve of not wasting food.",
  ui_story_5040_50401001_7_dialog_content = "So, how did everyone sleep last night?",
  ui_story_5040_50401001_8_dialog_content = "I personally slept amazingly.",
  ui_story_5040_50401001_9_dialog_content = "It's cold in the desert at night, but thankfully you prepared thick blankets, so Sable and I were just fine.",
  ui_story_5040_50401001_10_dialog_content = "Thank you... Jeriah.",
  ui_story_5040_50401001_11_dialog_content = "Oh, no problem at all, Sable.",
  ui_story_5040_50401001_12_dialog_content = "I, uh...",
  ui_story_5040_50401001_13_dialog_content = "My stomach hurt the whole night...",
  ui_story_5040_50401001_14_dialog_content = "(It must've been Adonis I heard rushing to the bathroom several times last night, then.)",
  ui_story_5040_50401001_15_dialog_content = "Do you want to rest a bit before heading out?",
  ui_story_5040_50401001_16_dialog_content = "I'm a-alright!",
  ui_story_5040_50401001_17_dialog_content = "I'm totally okay, seriously!",
  ui_story_5040_50401001_18_dialog_content = "...",
  ui_story_5040_50401001_19_dialog_content = "(Tara's had a funny look on her face ever since dinner last night. Is something on her mind?)",
  ui_story_5040_50401001_20_dialog_content = "Alright. In that case, let's get going. Tara can have the passenger seat, and the rest of you take the back.",
  ui_story_5040_50401001_21_dialog_content = "<color=#e8d9bb>Sometime later...</color>",
  ui_story_5040_50401001_22_dialog_content = "This is near the area of the deep desert inhabited by the sandworms.",
  ui_story_5040_50401001_23_dialog_content = "Let's take our final rest here.",
  ui_story_5040_50401001_24_dialog_content = "I moved the tent, cooking utensils, and all the food from the car with Sable.",
  ui_story_5040_50401001_25_dialog_content = "We can start cooking any time!",
  ui_story_5040_50401001_26_dialog_content = "Good job.",
  ui_story_5040_50401001_27_dialog_content = "Now that all the luggage has been unloaded, let's go back to the car.",
  ui_story_5040_50401001_28_dialog_content = "Huh? Why? Aren't we gonna rest?",
  ui_story_5040_50401001_29_dialog_content = "We still have one more thing to do before that.",
  ui_story_5040_50401001_30_dialog_content = "The sand dunes up ahead are steep and sloped. Riding those sandy waves is the perfect way to let go and relax.",
  ui_story_5040_50401001_31_dialog_content = "What do sand dunes have anything to do with relaxing?",
  ui_story_5040_50401001_32_dialog_content = "You'll find out in a moment, Northland birdie.",
  ui_story_5040_50401001_X32_dialog_content = "Alright, get in the car.",
  ui_story_5040_50401001_X33_dialog_content = "But, it's...",
  ui_story_5040_50401001_X34_dialog_content = "Quit stammering and just get in the car!",
  ui_story_5040_50401001_X35_dialog_content = "You can come along too, little Caelestite.",
  ui_story_5040_50401001_X36_dialog_content = "<color=#e8d9bb>In the Car</color>",
  ui_story_5040_50401001_X37_dialog_content = "Is everyone good to go?",
  ui_story_5040_50401001_X38_dialog_content = "Jeriah, w-what are you planning to do?",
  ui_story_5040_50401001_X39_dialog_content = "Why, I'm going to do something to make Tara happy, of course.",
  ui_story_5040_50401001_X40_dialog_content = "I have a bad feeling about this... Can you let me out of here!?",
  ui_story_5040_50401001_X41_dialog_content = "I'll go make you lunch—",
  ui_story_5040_50401001_X42_dialog_content = "Not a chance. You're an indispensable part of this experience.",
  ui_story_5040_50401001_33_option_content = "Indispensable!?",
  ui_story_5040_50401001_34_dialog_content = "Of course. You're our vital navigator.",
  ui_story_5040_50401001_35_option_content = "I think I'll pass!",
  ui_story_5040_50401001_36_dialog_content = "Now don't be getting cold feet.",
  ui_story_5040_50401001_37_dialog_content = "Remember to fasten your seatbelt.",
  ui_story_5040_50401001_38_dialog_content = "<color=#e8d9bb>Rumble!</color>",
  ui_story_5040_50401001_39_dialog_content = "Ahhh!",
  ui_story_5040_50401001_40_dialog_content = "T-This is too fast!",
  ui_story_5040_50401001_41_dialog_content = "WOOHOO! This is awesome!",
  ui_story_5040_50401001_42_dialog_content = "Faster, Jeriah, faster!",
  ui_story_5040_50401001_43_dialog_content = "Help! This car is about to take off!",
  ui_story_5040_50401001_44_dialog_content = "Is this... what flying feels like?",
  ui_story_5040_50401001_X44_dialog_content = "Stop! Don't go so fast... It's dangerous!",
  ui_story_5040_50401001_X45_dialog_content = "My stomach... doesn't feel so good...",
  ui_story_5040_50401001_45_dialog_content = "You gotta keep flying faster until you're looking a storm in the eye to truly understand the ecstasy of flight!",
  ui_story_5040_50401001_46_dialog_content = "Gahhhh!!!",
  ui_story_5040_50401001_47_dialog_content = "Watch out! The noise of the engine attracted Eclipsites!",
  ui_story_5040_50401001_48_dialog_content = "Little Caelestite, it's showtime!",
  ui_story_5040_50401001_49_dialog_content = "Huh?!",
  ui_story_5040_50401001_50_dialog_content = "I don't care if you use your eyes or your psychic abilities—tell me exactly where the Eclipsites will attack from.",
  ui_story_5040_50401001_51_dialog_content = "When we're going this fast? You're making things difficult on purpose!",
  ui_story_5040_50401001_52_dialog_content = "Gahhhh!",
  ui_story_5040_50401001_53_dialog_content = "Oh! From the rear, left-hand side!",
  ui_story_5040_50401001_54_dialog_content = "Good.",
  ui_story_5040_50401001_55_dialog_content = "<color=#e8d9bb>*Screeeee—!*</color>",
  ui_story_5040_50401001_56_dialog_content = "<color=#e8d9bb>Bang!!!</color>",
  ui_story_5040_50401001_57_dialog_content = "We just sent an Eclipsite flying!",
  ui_story_5040_50401001_58_dialog_content = "I need... Oh, no... *Retch*!",
  ui_story_5040_50401001_59_dialog_content = "Don't be vomiting in my car, little Northland bird.",
  ui_story_5040_50401001_60_dialog_content = "Look at how happy Tara looks for once.",
  ui_story_5040_50401001_61_dialog_content = "R-Really? Then I need to... hold on... for Tara...",
  ui_story_5040_50401001_62_dialog_content = "...",
  ui_story_5040_50401001_63_dialog_content = "Grahh!!",
  ui_story_5040_50401001_64_dialog_content = "More Eclipsites, dead ahead!",
  ui_story_5040_50401001_65_dialog_content = "Let's show 'em our passion and give 'em some speed.",
  ui_story_5040_50401001_66_dialog_content = "Full speed ahead!",
  ui_story_5040_50401001_67_dialog_content = "Hahaha, this is great!",
  ui_story_5040_50401001_68_dialog_content = "Oh no, no, I'm gonna... *Retch*!",
  ui_story_5040_50401001_69_dialog_content = "Carsick from such a short trip? I guess a Northland bird needs time to get used to the desert.",
  ui_story_5040_50401001_70_dialog_content = "Whereas birds of the desert only fly freely when borne by desert winds.",
  ui_story_5040_50401001_71_dialog_content = "Yeah...",
  ui_story_5040_50401001_72_dialog_content = "I've decided.",
  ui_story_5040_50401001_73_dialog_content = "Have you now? Finally.",
  ui_story_5040_50401001_74_dialog_content = "Yes. Actually, Adonis, I—",
  ui_story_5040_50401001_75_dialog_content = "Huh?",
  ui_story_5040_50401001_76_dialog_content = "<color=#e8d9bb>Rumbling—</color>",
  ui_story_5040_50401001_77_dialog_content = "Lady Jeriah! Eclipsites!",
  ui_story_5040_50401001_78_dialog_content = "There's a whole lot of them heading right for us!",
  ui_story_5040_50401001_79_dialog_content = "These guys sure know how to ruin the mood.",
  ui_story_5040_50401001_80_dialog_content = "You're the one who gunned the engine earlier, Jeriah! The noise must have attracted them!",
  ui_story_5040_50401001_81_dialog_content = "Let's continue our conversation later, little birds.",
  ui_story_5040_50401001_82_dialog_content = "Right now we need to deal with these guys, then we're going to have a nice lunch.",
  ui_story_5040_50401001_83_dialog_content = "Sigh...",
  ui_story_5040_50401001_84_dialog_content = "I-I'll help!",
  ui_story_5040_50401002_1_dialog_content = "They're cuter when they're on the ground.",
  ui_story_5040_50401002_2_dialog_content = "Graaahh—",
  ui_story_5040_50401002_3_dialog_content = "Scared...",
  ui_story_5040_50401002_4_dialog_content = "Don't be scared, she won't... Er, I mean, we've already dealt with the Eclipsites.",
  ui_story_5040_50401002_5_dialog_content = "Jeriah... not scary...",
  ui_story_5040_50401002_6_dialog_content = "Jeriah... good person... Protect everyone...",
  ui_story_5040_50401002_7_dialog_content = "But the Eclipsites wrecked everything, including all our food supplies!",
  ui_story_5040_50401002_8_dialog_content = "I was planning to make some Umbraton-style snacks, but now everything's been turned upside down. Totally unusable!",
  ui_story_5040_50401002_9_dialog_content = "Oh no, whatever should we do?",
  ui_story_5040_50401002_10_dialog_content = "(Did Jeriah just glance at Adonis?)",
  ui_story_5040_50401002_11_dialog_content = "I've got an idea.",
  ui_story_5040_50401002_12_dialog_content = "Yeah?",
  ui_story_5040_50401002_13_dialog_content = "I think we can still use this stuff if we just clean it up.",
  ui_story_5040_50401002_14_dialog_content = "I'm not sure we can use it for what you were planning, but we could definitely cook up a stew.",
  ui_story_5040_50401002_15_dialog_content = "Leave it to me!",
  ui_story_5040_50401002_16_dialog_content = "(Adonis really got straight down to business!)",
  ui_story_5040_50401002_17_dialog_content = "First, cut off any bruised or damaged bits, saving what can still be used.",
  ui_story_5040_50401002_18_dialog_content = "Then chop them into bite-sized pieces and put them in boiling water.",
  ui_story_5040_50401002_19_dialog_content = "Tara, could you pass me that, please?",
  ui_story_5040_50401002_20_dialog_content = "Here.",
  ui_story_5040_50401002_21_dialog_content = "Thanks. Now we add a little salt...",
  ui_story_5040_50401002_22_dialog_content = "Smells good!",
  ui_story_5040_50401002_23_dialog_content = "Here's a bowl for you, Tara. I know you don't like radish, so I already picked them all out.",
  ui_story_5040_50401002_24_dialog_content = "Thanks...",
  ui_story_5040_50401002_25_dialog_content = "A bowl for me too, please! And one for Sable!",
  ui_story_5040_50401002_26_dialog_content = "Alright, alright, hang on... I'll get yours ready.",
  ui_story_5040_50401002_27_dialog_content = "Here, I've brought the bowls over.",
  ui_story_5040_50401002_28_dialog_content = "Mmm, what a lovely lunch!",
  ui_story_5040_50401002_29_dialog_content = "It's a bit weird eating hot stew in the middle of the desert, but it's so delicious I don't even care!",
  ui_story_5040_50401002_30_dialog_content = "That's the only thing that matters!",
  ui_story_5040_50401002_31_dialog_content = "Let me handle the washing up.",
  ui_story_5040_50401002_32_dialog_content = "Okay. I'll have a quick look around the area, and make sure there aren't any more Eclipsites.",
  ui_story_5040_50401002_33_dialog_content = "Wait, weren't you saying something earlier?",
  ui_story_5040_50401002_34_dialog_content = "I almost forgot, with the whole Eclipsite fiasco.",
  ui_story_5040_50401002_35_dialog_content = "... No, it was nothing. I'm off to patrol.",
  ui_story_5040_50401002_36_dialog_content = "I'm gonna go for a walk with Sable, check out the scenery.",
  ui_story_5040_50401002_37_dialog_content = "(Odd... Tara seems to be keeping something from me.)",
  ui_story_5040_50401002_38_dialog_content = "(And earlier, Tara handed me the salt before I even asked for it.)",
  ui_story_5040_50401002_39_dialog_content = "(Is her memory starting to come back?)",
  ui_story_5040_50401002_40_dialog_content = "(That being said, she's been a little strange the whole trip.)",
  ui_story_5040_50401002_41_dialog_content = "(The way she hesitated just now was a lot like how she used to be, when about to apologize for something.)",
  ui_story_5040_50401002_42_dialog_content = "(It's really strange. Could it be... that she never really had amnesia?)",
  ui_story_5040_50401002_43_dialog_content = "(But why would she do this? I need to think...)",
  ui_story_5040_50401002_44_dialog_content = "(She fakes losing her memory, which forces me to leave Northland... could this all have been a ruse to make me more courageous?)",
  ui_story_5040_50401002_45_dialog_content = "(Tara, I'll prove myself to you. I promise!)",
  ui_story_5040_50401002_46_dialog_content = "Penny for your thoughts, Adonis?",
  ui_story_5040_50401002_47_dialog_content = "Oh, it's nothing. What's up?",
  ui_story_5040_50401002_48_dialog_content = "Can I help with anything?",
  ui_story_5040_50401002_49_dialog_content = "Nah, it's okay. I can tidy up myself.",
  ui_story_5040_50401002_50_dialog_content = "You can go do something else.",
  ui_story_5040_50401002_51_dialog_content = "Alright.",
  ui_story_5040_50401002_52_dialog_content = "(I'm so bored by myself. I wish Vice and Carleen were here right now, I miss chatting with them.)",
  ui_story_5040_50401002_53_dialog_content = "(Jeriah's a bit of a loner. Does she never get bored?)",
  ui_story_5040_50401002_54_dialog_content = "(Hopefully she's not mad anymore. Maybe I should go check on her.)",
  ui_story_5040_50401002_55_dialog_content = "Sigh, it's been tiring, but...",
  ui_story_5040_50401002_56_dialog_content = "Tara, Adonis... Heheh, those are two interesting little birds.",
  ui_story_5040_50401002_57_dialog_content = "Jeriah!",
  ui_story_5040_50401002_58_dialog_content = "Huh? Oh, if it's not the young Caelestite! What brings you over here?",
  ui_story_5040_50401002_59_dialog_content = "Could it be that you're lonely without your other young friends?",
  ui_story_5040_50401002_60_dialog_content = "N-No! Of course not!",
  ui_story_5040_50401002_61_dialog_content = "Or perhaps you found me pitiful, here all by my lone self, and thought company would be appreciated?",
  ui_story_5040_50401002_62_dialog_content = "Not that either...",
  ui_story_5040_50401002_63_dialog_content = "There's something I wanted to ask you.",
  ui_story_5040_50401002_64_dialog_content = "Oh?",
  ui_story_5040_50401002_65_option_content = "Are you being completely honest?",
  ui_story_5040_50401002_66_dialog_content = "What makes you say that?",
  ui_story_5040_50401002_67_dialog_content = "You said this morning that you slept well.",
  ui_story_5040_50401002_68_dialog_content = "But that doesn't gel with what I heard!",
  ui_story_5040_50401002_69_option_content = "Are you putting on a brave face?",
  ui_story_5040_50401002_70_dialog_content = "Brave face? And what led you to that conclusion?",
  ui_story_5040_50401002_71_dialog_content = "I heard that yesterday you sent your Speaker to scour the whole desert, looking for sandworms.",
  ui_story_5040_50401002_72_dialog_content = "...",
  ui_story_5040_50401002_73_dialog_content = "Even if I did, so what?",
  ui_story_5040_50401002_74_dialog_content = "It was reckless!",
  ui_story_5040_50401002_75_dialog_content = "Using such intense Luminatics for so long, then getting up so early this morning—I bet you didn't rest well, did you? And now you're still going.",
  ui_story_5040_50401002_76_dialog_content = "You're overdoing it!",
  ui_story_5040_50401002_77_dialog_content = "Again... supposing you're right, so what?",
  ui_story_5040_50401002_78_dialog_content = "I'm just saying, you don't need to push yourself so hard. It's okay to lean on others now and then.",
  ui_story_5040_50401002_79_dialog_content = "I'm able to get by just fine in the desert on my own.",
  ui_story_5040_50401002_80_dialog_content = "I'm perfectly capable of tracking the sandworm by myself, all while completing Courier Union tasks and delivering mail all across the desert.",
  ui_story_5040_50401002_81_dialog_content = "What right do you have to doubt me anyway?",
  ui_story_5040_50401002_82_dialog_content = "I'm not doubting you!",
  ui_story_5040_50401002_83_dialog_content = "I'm well aware that, as a Caelestite, I don't have particularly strong Luminatics. I also know that I'm pretty useless fighting Eclipsites.",
  ui_story_5040_50401002_84_dialog_content = "That's why I rely on the strength of my companions all the time.",
  ui_story_5040_50401002_85_dialog_content = "It's because I'm weak that I realized that no one can survive in this world completely on their own.",
  ui_story_5040_50401002_86_dialog_content = "Is that what you think?",
  ui_story_5040_50401002_87_dialog_content = "However strong you are, you'll inevitably encounter problems beyond what you can handle.",
  ui_story_5040_50401002_88_dialog_content = "Some people may be able to get by, relying on their own growth or hard work...",
  ui_story_5040_50401002_89_dialog_content = "but some problems don't wait for you to grow, or are too much, even if you work hard.",
  ui_story_5040_50401002_90_dialog_content = "My life is full of these kinds of problems because I'm a frail Caelestite.",
  ui_story_5040_50401002_91_dialog_content = "You mean to say, there's no shame in leaning on others?",
  ui_story_5040_50401002_92_dialog_content = "Hehe, you really are naive.",
  ui_story_5040_50401002_93_dialog_content = "Once or twice is perhaps okay, but too many times and the number of favors owed becomes a burden.",
  ui_story_5040_50401002_94_dialog_content = "Like a cage, this burden traps a bird, preventing it from ever flying freely.",
  ui_story_5040_50401002_95_dialog_content = "I imagine you must know what it feels like, to be so burdened by the things you owe others.",
  ui_story_5040_50401002_96_option_content = "Yes",
  ui_story_5040_50401002_97_dialog_content = "You're right, it is difficult to be in the position of owing people favors.",
  ui_story_5040_50401002_98_dialog_content = "Exactly. I hate the feeling, and I have no desire to engage much with others.",
  ui_story_5040_50401002_99_dialog_content = "Can you really say that living alone, but free, is a bad thing?",
  ui_story_5040_50401002_100_dialog_content = "It's great to have the freedom to do whatever you like without needing to consider too much.",
  ui_story_5040_50401002_101_dialog_content = "But interactions with others aren't transactional.",
  ui_story_5040_50401002_102_option_content = "No",
  ui_story_5040_50401002_103_dialog_content = "It's true that many people have helped me, but I don't feel like it's any sort of burden.",
  ui_story_5040_50401002_104_dialog_content = "...!",
  ui_story_5040_50401002_105_dialog_content = "Everyone has their own strengths and weaknesses, and people complement each other.",
  ui_story_5040_50401002_106_dialog_content = "My companions may be gifted in Luminatics, but I can see Light Trails. We're able to take on Eclipsites together, side by side.",
  ui_story_5040_50401002_107_dialog_content = "I don't know what you've experienced that has made you so averse to connecting with people.",
  ui_story_5040_50401002_108_dialog_content = "But relationships are a two-way street. Yes, I might accept other people's help, but I'll also do my best to help others.",
  ui_story_5040_50401002_109_dialog_content = "...",
  ui_story_5040_50401002_110_dialog_content = "That's how you see it, huh?",
  ui_story_5040_50401002_111_dialog_content = "Seems the relationship you have with your companions is the same as those two little birds over there.",
  ui_story_5040_50401002_112_dialog_content = "What?!",
  ui_story_5040_50401002_113_dialog_content = "We're just friends! We are so not—",
  ui_story_5040_50401002_114_dialog_content = "My, my, look where your mind has gone! I haven't said a thing.",
  ui_story_5040_50401002_115_dialog_content = "You...",
  ui_story_5040_50401002_116_dialog_content = "Look at those two. They complement each other pretty well, don't they?",
  ui_story_5040_50401002_117_dialog_content = "I'm back. There's no traces of Eclipsites in the area so far.",
  ui_story_5040_50401002_118_dialog_content = "Good work! Here, have some water and rest a while.",
  ui_story_5040_50401002_119_dialog_content = "Yeah...",
  ui_story_5040_50401002_120_dialog_content = "Tara is outgoing and cheerful, with plenty of experience living in the wild and dealing with Eclipsites.",
  ui_story_5040_50401002_121_dialog_content = "Adonis is more logistical, and patient enough to deal with all the work that Tara both finds tedious and isn't very good at.",
  ui_story_5040_50401002_122_dialog_content = "That's right. I would never have thought that there'd be a person who could get on with a Rediesel Wrench member like that.",
  ui_story_5040_50401002_123_dialog_content = "Do you dislike the Rediesel Wrenches?",
  ui_story_5040_50401002_124_dialog_content = "Dislike? Ha. Perhaps.",
  ui_story_5040_50401002_125_dialog_content = "As far as I'm concerned, they're nothing more than a bunch of short-sighted, brainless bandits.",
  ui_story_5040_50401002_126_dialog_content = "They live such a hedonistic existence, not caring about anything other than having fun.",
  ui_story_5040_50401002_127_dialog_content = "But you know, it was Sinsa who told me about you using your Speaker to scour the whole desert for sandworms.",
  ui_story_5040_50401002_128_dialog_content = "What?",
  ui_story_5040_50401002_129_dialog_content = "Yesterday, after you made me leave, I got in touch with Sinsa to ask about the pink sandworm.",
  ui_story_5040_50401002_130_dialog_content = "He told me that someone in the Rediesel Wrench saw you using your Speaker to search for sandworms.",
  ui_story_5040_50401002_131_dialog_content = "Everyone was worried about you.",
  ui_story_5040_50401002_132_dialog_content = "That's only because I'm one of the few couriers in the desert who can deliver them the information they need.",
  ui_story_5040_50401002_133_dialog_content = "It's not like that!",
  ui_story_5040_50401002_134_dialog_content = "Alright, I think I've had enough rest.",
  ui_story_5040_50401002_135_dialog_content = "Hey, Jeriah!",
  ui_story_5040_50401002_136_dialog_content = "Get your things together. It's time to head out.",
  ui_story_5040_50401002_137_dialog_content = "Seriously, Jeriah. Just walk off and leave me hanging, why don't you...",
  ui_story_5040_50401002_138_dialog_content = "Does she make a habit of living in denial and pretend everything's fine?",
  ui_story_5040_50401101_1_dialog_content = "How are your preparations going, little birds?",
  ui_story_5040_50401101_2_dialog_content = "I'm all packed and ready to go whenever.",
  ui_story_5040_50401101_3_dialog_content = "I'm ready too.",
  ui_story_5040_50401101_4_dialog_content = "The fire's been put out, and we have all our belongings.",
  ui_story_5040_50401101_5_dialog_content = "You're so prudent, Kya!",
  ui_story_5040_50401101_6_dialog_content = "Thanks! Emerald taught me well.",
  ui_story_5040_50401101_7_dialog_content = "Who's Emerald?",
  ui_story_5040_50401101_8_dialog_content = "She was a senior of mine at the Courier Union, though she's retired now.",
  ui_story_5040_50401101_9_dialog_content = "Before I became a courier, it was Emerald who delivered letters to my hometown of Faar and the other nearby villages.",
  ui_story_5040_50401101_10_dialog_content = "My hometown is really remote, so we barely ever had contact with the outside world.",
  ui_story_5040_50401101_11_dialog_content = "Our only way of knowing what was going on was through the letters that Emerald brought.",
  ui_story_5040_50401101_12_dialog_content = "She must've been a really responsible person.",
  ui_story_5040_50401101_13_dialog_content = "Oh, yes! It was because of her that I was inspired to become a courier!",
  ui_story_5040_50401101_14_dialog_content = "I know firsthand how hard it is for people living in remote places to connect with the outside world, so I wanted to become a bridge for others to the outside.",
  ui_story_5040_50401101_15_dialog_content = "That's amazing!",
  ui_story_5040_50401101_16_dialog_content = "Hehe, I still have room for improvement.",
  ui_story_5040_50401101_17_dialog_content = "Even with all the notes that Emerald gave me, I still mess things up...",
  ui_story_5040_50401101_18_dialog_content = "Even though I follow all the advice in her notes precisely, things somehow always turn out differently from my expectations.",
  ui_story_5040_50401101_19_dialog_content = "You don't need to always follow directions like that to a tee. Sometimes, it's necessary to improvise and adapt to the situation.",
  ui_story_5040_50401101_20_dialog_content = "Eh, I'm not very good at that.",
  ui_story_5040_50401101_21_dialog_content = "Graaoooooohhh!!",
  ui_story_5040_50401101_22_dialog_content = "Did you hear that? Something in the distance?",
  ui_story_5040_50401101_23_dialog_content = "That's...",
  ui_story_5040_50401101_24_dialog_content = "Graah! Roar!",
  ui_story_5040_50401101_25_dialog_content = "Eclipsites! Everyone, watch out!",
  ui_story_5040_50401101_26_dialog_content = "So many of them!",
  ui_story_5040_50401101_27_dialog_content = "Where have they all come from this time?!",
  ui_story_5040_50401101_28_dialog_content = "Another group? How strange...",
  ui_story_5040_50401101_29_dialog_content = "Let's just deal with them first. Good luck and be careful.",
  ui_story_5040_50401102_1_dialog_content = "Graaahh—",
  ui_story_5040_50401102_2_dialog_content = "Strange, they don't usually give up so easily. Yet they just ran off...",
  ui_story_5040_50401102_3_dialog_content = "This isn't an area where Eclipsites are usually known to appear.",
  ui_story_5040_50401102_4_dialog_content = "But this was the second group we've encountered in the past couple of days. That's not normal.",
  ui_story_5040_50401102_5_dialog_content = "They're... running...",
  ui_story_5040_50401102_6_dialog_content = "What did you say?",
  ui_story_5040_50401102_7_dialog_content = "Sable said they seemed to be running away, hiding from something?",
  ui_story_5040_50401102_8_dialog_content = "<color=#e8d9bb>Rumble...</color>",
  ui_story_5040_50401102_9_dialog_content = "Is the ground shaking?",
  ui_story_5040_50401102_10_dialog_content = "Out of the way, everyone. Something's coming!",
  ui_story_5040_50401102_11_dialog_content = "Look out, Tara!",
  ui_story_5040_50401102_12_dialog_content = "<color=#e8d9bb>Boom!</color>",
  ui_story_5040_50401102_13_dialog_content = "<size=50>Rooooaaaar!</size>",
  ui_story_5040_50401102_14_dialog_content = "Wow!! I-Is that actually a pink sandworm?!",
  ui_story_5040_50401102_15_dialog_content = "I thought it was supposed to be headed towards the deeper part of the desert! That's, uh, pretty far away from here!",
  ui_story_5040_50401102_16_dialog_content = "There's one other explanation for its appearance... It might be feeding time.",
  ui_story_5040_50401102_17_dialog_content = "You're saying it was trying to feed on those Eclipsites?",
  ui_story_5040_50401102_18_dialog_content = "Yes... and it looks like now we're on the menu.",
  ui_story_5040_50401102_19_dialog_content = "<size=50>Roooaaar!</size>",
  ui_story_5040_50401102_20_dialog_content = "Why the rush, big guy?",
  ui_story_5040_50401102_21_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5040_50401102_22_dialog_content = "That is some armor!",
  ui_story_5040_50401102_23_dialog_content = "Heheh... I guess those pink scales are a lot stronger than they look.",
  ui_story_5040_50401102_24_dialog_content = "But no matter what, it's still just a sandworm.",
  ui_story_5040_50401102_25_dialog_content = "Go, Speakers!",
  ui_story_5040_50401102_26_dialog_content = "Roaaar—",
  ui_story_5040_50401102_27_dialog_content = "Look, it's working!",
  ui_story_5040_50401102_28_dialog_content = "I'll help out too!",
  ui_story_5040_50401102_29_dialog_content = "Wait, Tara! Don't get too close to it!",
  ui_story_5040_50401102_30_dialog_content = "My bullets won't pierce this sandworm's scales if I'm too far away.",
  ui_story_5040_50401102_31_dialog_content = "Besides, there's nothing to be afraid of. Pink or not, it's just a sandworm!",
  ui_story_5040_50401102_32_dialog_content = "Rrr... Roar...!",
  ui_story_5040_50401102_33_dialog_content = "Next... a headshot!",
  ui_story_5040_50401102_34_dialog_content = "Roar!",
  ui_story_5040_50401102_35_dialog_content = "Huh?!",
  ui_story_5040_50401102_36_dialog_content = "I-It got Tara's gun! Did it do that intentionally?!",
  ui_story_5040_50401102_37_dialog_content = "Let go!",
  ui_story_5040_50401102_38_dialog_content = "How could a sandworm have this kind of awareness? Something's wrong...",
  ui_story_5040_50401102_39_dialog_content = "We won't be able to defeat it quickly. Not with our current strength.",
  ui_story_5040_50401102_40_dialog_content = "It's trying to wear us down by dragging out the fight!",
  ui_story_5040_50401102_41_dialog_content = "We can't let that happen. Grimoire, unleash your power!",
  ui_story_5040_50401102_42_dialog_content = "Roar—!",
  ui_story_5040_50401102_43_dialog_content = "Wh-Where'd it go?!",
  ui_story_5040_50401102_44_dialog_content = "It's burrowing under the sand! Watch your step!",
  ui_story_5040_50401102_45_dialog_content = "<size=50>Roooaaarrr!!!</size>",
  ui_story_5040_50401102_46_dialog_content = "<color=#e8d9bb>Whoosh—Slam!</color>",
  ui_story_5040_50401102_47_dialog_content = "Agh—!",
  ui_story_5040_50401102_48_dialog_content = "It hurled Tara into the dunes over there!",
  ui_story_5040_50401102_49_dialog_content = "Tara!!!",
  ui_story_5040_50401102_50_dialog_content = "I'm okay!",
  ui_story_5040_50401102_51_dialog_content = "The sand here is loose; it's using that to burrow and ambush us.",
  ui_story_5040_50401102_52_dialog_content = "Everyone into the car!",
  ui_story_5040_50401102_53_dialog_content = "There's a part of the desert where the ground is mostly stone. If we can get there, the sandworm won't be able to ambush us!",
  ui_story_5040_50401102_54_dialog_content = "Got it! Come on Sable, let's get to the car!",
  ui_story_5040_50401102_55_dialog_content = "We're retreating, Adonis!",
  ui_story_5040_50401102_56_dialog_content = "Got—Look out, Tara!",
  ui_story_5040_50401102_57_dialog_content = "Roaaar—",
  ui_story_5040_50401102_58_dialog_content = "Urg—!",
  ui_story_5040_50401102_59_dialog_content = "Tara!!",
  ui_story_5040_50401102_60_dialog_content = "Ow...",
  ui_story_5040_50401102_61_dialog_content = "Oh no, Tara's leg is injured!",
  ui_story_5040_50401102_62_dialog_content = "Roar!",
  ui_story_5040_50401102_63_dialog_content = "(Drat, we won't be able to make it. How can I stop it...)",
  ui_story_5040_50401102_64_dialog_content = "Leave Tara alone, you fat, ugly caterpillar!",
  ui_story_5040_50401102_65_dialog_content = "Roaaar—",
  ui_story_5040_50401102_66_dialog_content = "Over here, you overgrown maggot! Come get me!",
  ui_story_5040_50401102_67_dialog_content = "Adonis caught the sandworm's attention!",
  ui_story_5040_50401102_68_dialog_content = "I can't believe that weak attack of his worked!",
  ui_story_5040_50401102_69_dialog_content = "Look closely at the place where Adonis struck the sandworm... I think it's a wound that hasn't fully recovered.",
  ui_story_5040_50401102_70_dialog_content = "That must be from its fight with Sinsa and the others!",
  ui_story_5040_50401102_71_dialog_content = "Roar!",
  ui_story_5040_50401102_72_dialog_content = "Yikes!!!",
  ui_story_5040_50401102_73_dialog_content = "The sandworm is after Adonis now, it's moving away from Tara!",
  ui_story_5040_50401102_74_dialog_content = "Now's your chance, Jeriah!",
  ui_story_5040_50401102_75_dialog_content = "Heheh... I know.",
  ui_story_5040_50401102_76_dialog_content = "Fly, Hawk! Aim for that wound!",
  ui_story_5040_50401102_77_dialog_content = "Roar? Roaaarrrr!",
  ui_story_5040_50401102_78_dialog_content = "Now!",
  ui_story_5040_50401102_79_dialog_content = "Are you okay, Tara?",
  ui_story_5040_50401102_80_dialog_content = "I'm fine! Go help Adonis!",
  ui_story_5040_50401102_81_dialog_content = "Roger!",
  ui_story_5040_50401102_82_dialog_content = "I'll... help... too!",
  ui_story_5040_50401102_83_dialog_content = "<color=#e8d9bb>Whizz—!</color>",
  ui_story_5040_50401102_84_dialog_content = "Roooaaarrr!!!",
  ui_story_5040_50401102_85_dialog_content = "I... I'm saved!",
  ui_story_5040_50401102_86_dialog_content = "Get behind us, and don't lose your footing!",
  ui_story_5040_50401102_87_dialog_content = "Roar!",
  ui_story_5040_50401102_88_dialog_content = "<color=#e8d9bb>Fwooosh!!!</color>",
  ui_story_5040_50401102_89_dialog_content = "Whoa! Where did this sandstorm come from?!",
  ui_story_5040_50401102_90_dialog_content = "It's not a sandstorm. The sandworm is hurling sand in the air.",
  ui_story_5040_50401102_91_dialog_content = "It's trying to protect its weak points by obscuring our vision!",
  ui_story_5040_50401102_92_dialog_content = "Oh no... I lost sight of Kya and the others!",
  ui_story_5040_50401102_93_dialog_content = "Tara! Where are you?!",
  ui_story_5040_50401102_94_dialog_content = "Over here!",
  ui_story_5040_50401102_95_dialog_content = "We're on our way!",
  ui_story_5040_50401102_96_dialog_content = "<color=#e8d9bb>Rumble...</color>",
  ui_story_5040_50401102_97_dialog_content = "Ahhh!!!",
  ui_story_5040_50401102_98_dialog_content = "A-Adonis?!",
  ui_story_5040_50401102_99_dialog_content = "I'll go bring them back!",
  ui_story_5040_50401102_100_dialog_content = "<size=50>Roooaaar!!!</size>",
  ui_story_5040_50401102_101_dialog_content = "Huh?!",
  ui_story_5040_50401102_102_dialog_content = "Jeriah, it's getting away!",
  ui_story_5040_50401102_103_dialog_content = "Not on my watch!",
  ui_story_5040_50401102_104_dialog_content = "<size=50>Roooaaarrr!!!</size>",
  ui_story_5040_50401102_105_dialog_content = "Ugh!!!",
  ui_story_5040_50401102_106_dialog_content = "PlayerName!!!",
  ui_story_5040_50401102_107_dialog_content = "Ouch...",
  ui_story_5040_50401201_1_dialog_content = "Snap out of it, PlayerName!",
  ui_story_5040_50401201_2_dialog_content = "Ugh... My head...",
  ui_story_5040_50401201_3_dialog_content = "*Sputtering* Ugh, my mouth is filled with sand!",
  ui_story_5040_50401201_4_dialog_content = "Phew... Thank goodness you're okay. Are you hurt anywhere?",
  ui_story_5040_50401201_5_dialog_content = "*Coughs* No, I think I'm fine. My head just hurts, that's all...",
  ui_story_5040_50401201_6_dialog_content = "The sandworm sent you flying headfirst into a dune... When I saw your half-buried body sticking out of the sand, I thought you'd been seriously injured.",
  ui_story_5040_50401201_7_dialog_content = "It wasn't easy for Tara and me to pull you out, little Caelestite... you should really thank us.",
  ui_story_5040_50401201_8_dialog_content = "Th-Thank you...",
  ui_story_5040_50401201_9_dialog_content = "Wait, where are the others? Are they okay?",
  ui_story_5040_50401201_10_dialog_content = "We ran over to help you as soon as we saw your legs poking out of the sand.",
  ui_story_5040_50401201_11_dialog_content = "Thanks to that vicious sandstorm, we lost the sandworm and got separated from Adonis and the others.",
  ui_story_5040_50401201_12_dialog_content = "I'll try locating them with my powers!",
  ui_story_5040_50401201_13_option_content = "Mindlink!",
  ui_story_5040_50401201_14_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5040_50401201_15_dialog_content = "I don't sense any trace of them nearby...",
  ui_story_5040_50401201_16_dialog_content = "It's fine. My Speakers are out searching for them as we speak. Unless they ran into trouble, we should be hearing from them soon enough.",
  ui_story_5040_50401201_17_dialog_content = "Even if they were buried underground, Hawk can detect even the slightest movements on the surface of the sand and find them.",
  ui_story_5040_50401201_18_dialog_content = "Adonis... Please be okay...",
  ui_story_5040_50401201_19_dialog_content = "Shreee—!",
  ui_story_5040_50401201_20_dialog_content = "My bird has news for us.",
  ui_story_5040_50401201_21_dialog_content = "Well? Did you find them?",
  ui_story_5040_50401201_22_dialog_content = "Shreee—",
  ui_story_5040_50401201_23_dialog_content = "... No sign of them at all?",
  ui_story_5040_50401201_24_dialog_content = "Try again, and expand your search radius this time. Don't worry about how much Lumina it'll expend.",
  ui_story_5040_50401201_25_dialog_content = "Go!",
  ui_story_5040_50401201_26_dialog_content = "Shreee—!",
  ui_story_5040_50401201_27_dialog_content = "I'll look around as well.",
  ui_story_5040_50401201_28_dialog_content = "But your leg is still hurt!",
  ui_story_5040_50401201_29_dialog_content = "I can't just sit here and do nothing!",
  ui_story_5040_50401201_30_dialog_content = "You would only be wasting your energy. If a hawk's eyes can't see something from the air, what makes you think your eyes can do better?",
  ui_story_5040_50401201_31_dialog_content = "Your best option is to rest here, so you don't exacerbate your injuries.",
  ui_story_5040_50401201_32_dialog_content = "...",
  ui_story_5040_50401201_33_dialog_content = "If it weren't for me faking memory loss, Adonis wouldn't even be in this mess, would he?",
  ui_story_5040_50401201_34_dialog_content = "... To be honest, I figured it out ages ago through my ability that you were faking.",
  ui_story_5040_50401201_35_dialog_content = "It's just that I thought you had your reasons, so I didn't want to intervene.",
  ui_story_5040_50401201_36_dialog_content = "Yes...",
  ui_story_5040_50401201_37_dialog_content = "But in hindsight, letting you do as you please just ended up putting us all in danger!",
  ui_story_5040_50401201_38_dialog_content = "What on earth were you thinking? How could you do this to everyone?!",
  ui_story_5040_50401201_39_dialog_content = "I thought... I thought it would help Adonis get over his fear of the outside world.",
  ui_story_5040_50401201_40_dialog_content = "He's always been reluctant about leaving behind his life in Northland... So I was hoping that these trials would give him the push he needed.",
  ui_story_5040_50401201_41_option_content = "That's completely insane!",
  ui_story_5040_50401201_42_dialog_content = "Never mind the rest of us. Isn't Adonis the person who means the most to you?",
  ui_story_5040_50401201_43_dialog_content = "What's the point of completing all of these trials, if it means putting the man you love in harm's way?!",
  ui_story_5040_50401201_44_dialog_content = "Now he's nowhere to be found, along with Kya and Sable! This isn't a joke, Tara!",
  ui_story_5040_50401201_45_dialog_content = "I'm sorry...",
  ui_story_5040_50401201_46_option_content = "... I know where you're coming from.",
  ui_story_5040_50401201_47_dialog_content = "Sometimes, when I'm not brave enough to do something, I need others to push me forward.",
  ui_story_5040_50401201_48_dialog_content = "Your heart was in the right place, but I can't say I agree with your methods.",
  ui_story_5040_50401201_49_dialog_content = "If the person you care about isn't brave enough to face a challenge, you should stand by them.",
  ui_story_5040_50401201_50_dialog_content = "You're supposed to use your words and actions to help them find their courage and face those challenges together.",
  ui_story_5040_50401201_51_dialog_content = "I was wrong... I'm sorry. I shouldn't have been so reckless...",
  ui_story_5040_50401201_52_dialog_content = "I thought the pink sandworm would be just like any other sandworm, just a different color.",
  ui_story_5040_50401201_53_dialog_content = "I've dealt with plenty of regular sandworms before without a hitch. I thought I could protect Adonis on my own.",
  ui_story_5040_50401201_54_dialog_content = "I had no idea that thing would be so cunning and powerful...",
  ui_story_5040_50401201_55_dialog_content = "I'm partly to blame for this.",
  ui_story_5040_50401201_56_dialog_content = "I should have realized that for such a special sandworm to survive the harsh realities of the desert for so long, it must be much more tenacious than the rest.",
  ui_story_5040_50401201_57_dialog_content = "At the end of the day, I'm the one who presented this trial, putting everyone in danger. I'll take responsibility for it, and do everything I can to rescue them.",
  ui_story_5040_50401201_58_dialog_content = "Sigh, let's just try and find the others first.",
  ui_story_5040_50401201_59_dialog_content = "I hope they're safe...",
  ui_story_5040_50401201_60_dialog_content = "(This is worrying...)",
  ui_story_5040_50401201_61_dialog_content = "(What should we do if even Jeriah's Speaker can't find them...?)",
  ui_story_5040_50401201_62_dialog_content = "My bird is back.",
  ui_story_5040_50401201_63_dialog_content = "Huh? Where?",
  ui_story_5040_50401201_64_dialog_content = "Hawk, over here!",
  ui_story_5040_50401201_65_dialog_content = "Kree—!",
  ui_story_5040_50401201_66_dialog_content = "Graaah...",
  ui_story_5040_50401201_67_dialog_content = "And it seems to have brought along something extra...",
  ui_story_5040_50401201_68_dialog_content = "Let's take care of these Eclipsites first!",
  ui_story_5040_50401201_69_dialog_content = "Let me help. A scratch like this... is nothing for someone who grew up in the Rediesel Desert!",
  ui_story_5040_50401202_1_dialog_content = "*Cough* *cough*",
  ui_story_5040_50401202_2_dialog_content = "My, I didn't expect to feel so fatigued.",
  ui_story_5040_50401202_3_dialog_content = "Do you think those Eclipsites are running away from the sandworm?",
  ui_story_5040_50401202_4_dialog_content = "No, they don't seem to be panicking or looking for cover...",
  ui_story_5040_50401202_5_dialog_content = "Perhaps they noticed how much Lumina Hawk was spending to search for the others, and saw a perfect opportunity to ambush us?",
  ui_story_5040_50401202_6_dialog_content = "Now then, my little bird... Did you find anything?",
  ui_story_5040_50401202_7_dialog_content = "Shree!",
  ui_story_5040_50401202_8_dialog_content = "Still nothing...?",
  ui_story_5040_50401202_9_dialog_content = "There's no sign of the sandworm anywhere nearby. It's most likely moving around using underground tunnels that it created previously.",
  ui_story_5040_50401202_10_dialog_content = "If that's the case, then it's also very likely that it carried Adonis, Kya, and Sable along with it...",
  ui_story_5040_50401202_11_dialog_content = "That means they're in serious danger!",
  ui_story_5040_50401202_12_dialog_content = "There's no way those three can handle that sandworm on their own! Not to mention they could get lost in those tunnels!",
  ui_story_5040_50401202_13_dialog_content = "We need to find them right away!",
  ui_story_5040_50401202_14_dialog_content = "Don't worry. I can empower Hawk to search the entire desert.",
  ui_story_5040_50401202_15_dialog_content = "Haw—*Cough*—Hawk!",
  ui_story_5040_50401202_16_dialog_content = "Stop it, Jeriah!",
  ui_story_5040_50401202_17_dialog_content = "You look so pale, you're clearly at your limit!",
  ui_story_5040_50401202_18_dialog_content = "Heheh... Don't underestimate me, little Caelestite. I'm not nearly that delicate.",
  ui_story_5040_50401202_19_dialog_content = "After all these years, I've managed to overcome every single problem on my own.",
  ui_story_5040_50401202_20_dialog_content = "This time will be no diff—",
  ui_story_5040_50401202_21_dialog_content = "We should ask the Rediesel Wrench for help.",
  ui_story_5040_50401202_22_dialog_content = "What?",
  ui_story_5040_50401202_23_dialog_content = "Let's return to Soroz. I'll use the communicators to contact Sinsa and the rest of the Rediesel Wrench, so they can help us search.",
  ui_story_5040_50401202_24_dialog_content = "If we can't find them with just the three of us, then we'll just have to mobilize everyone in the entire desert!",
  ui_story_5040_50401202_25_dialog_content = "You're a senior member of the Courier Union! I'm sure everyone would be willing to help if someone of your status asked them to!",
  ui_story_5040_50401202_26_dialog_content = "\"Someone of my status\"? How naive of you, hehe...",
  ui_story_5040_50401202_27_dialog_content = "I've always been a professional. I don't help others, and I don't expect help from others.",
  ui_story_5040_50401202_28_dialog_content = "Besides, I'm sure they'd be much happier with another, far more responsible courier.",
  ui_story_5040_50401202_29_dialog_content = "You're not someone who can just be replaced!",
  ui_story_5040_50401202_30_dialog_content = "Everyone in the Rediesel Desert knows that couriers are the bridges that connect us all!",
  ui_story_5040_50401202_31_dialog_content = "The Courier Union was the only reason that Adonis and I were able to keep in touch all this time!",
  ui_story_5040_50401202_32_dialog_content = "That's right. Relationships between people are never that simple, Jeriah.",
  ui_story_5040_50401202_33_dialog_content = "By delivering everyone's letters, I'm sure you've made connections with people that run deeper than you realize.",
  ui_story_5040_50401202_34_dialog_content = "...",
  ui_story_5040_50401202_35_dialog_content = "What am I supposed to do with you two...",
  ui_story_5040_50401202_36_dialog_content = "Fine. We'll do it your way, and ask for help.",
  ui_story_5040_50401202_37_dialog_content = "But don't get your hopes high. The Rediesel Wrench may not want to help someone who only thinks of them when in trouble.",
  ui_story_5040_50401202_38_dialog_content = "We'll never know unless we try, right?",
  ui_story_5040_50401202_39_dialog_content = "Let's head back to Soroz!",
  ui_story_5040_50401202_40_dialog_content = "Don't be so hasty. I can reach them faster than your communicators.",
  ui_story_5040_50401202_41_dialog_content = "Huh?",
  ui_story_5040_50401202_42_dialog_content = "It's a talent of mine, one that will burn through nearly all of my Lumina. Once I use it, I won't be able to do so again for a long time...",
  ui_story_5040_50401202_43_dialog_content = "but I believe now is the perfect time to use it.",
  ui_story_5040_50401202_44_dialog_content = "Hold on, are you telling me you have some sort of ultimate attack up your sleeve?",
  ui_story_5040_50401202_45_dialog_content = "Not an attack, no.",
  ui_story_5040_50401202_46_dialog_content = "All it does is let me quickly establish a connection with my little Courier Union birdies, so it's meant for emergencies only.",
  ui_story_5040_50401202_47_dialog_content = "By activating this skill, I can use Hawk to ask them for help. This way, we can reach every member of the Rediesel Wrench in the area.",
  ui_story_5040_50401202_48_dialog_content = "Have you ever done it before?",
  ui_story_5040_50401202_49_dialog_content = "Nope! This is my very first attempt.",
  ui_story_5040_50401202_50_dialog_content = "Come, my sweet little bird! Carry my message to all who will listen!",
  ui_story_5040_50401202_51_dialog_content = "Shree!",
  ui_story_5040_50401202_52_dialog_content = "Go!",
  ui_story_5040_50401202_53_dialog_content = "Shreee—!",
  ui_story_5040_50401202_54_dialog_content = "Come home with good news, my beautiful, little bird...",
  ui_story_5040_50401202_55_dialog_content = "<color=#e8d9bb>A few minutes later...</color>",
  ui_story_5040_50401202_56_dialog_content = "Still no response...",
  ui_story_5040_50401202_57_dialog_content = "Hawk may be fast, but it still needs time to deliver my message. Just be patient.",
  ui_story_5040_50401202_58_dialog_content = "... Look! There it is!",
  ui_story_5040_50401202_59_dialog_content = "Yes! It's Jeriah's Hawk...",
  ui_story_5040_50401202_60_dialog_content = "Shreee—!",
  ui_story_5040_50401202_61_dialog_content = "It looks like it's carrying something in its talons... L-Look out! It's dropping stuff on us!",
  ui_story_5040_50401202_62_dialog_content = "Are these... letters?",
  ui_story_5040_50401202_63_dialog_content = "They are! Look at all these letters, falling from the sky like snow...",
  ui_story_5040_50401202_64_dialog_content = "There are so many of them. I think there are notes inside them.",
  ui_story_5040_50401202_65_dialog_content = "Whoa, what does this even mean? I can't make heads or tails of this!",
  ui_story_5040_50401202_66_dialog_content = "Let me see.",
  ui_story_5040_50401202_67_dialog_content = "Oh, it's just a coded message from the Rediesel Wrench. It says that no one has seen our friends or that sandworm in the northwestern parts of the desert.",
  ui_story_5040_50401202_68_dialog_content = "Not everyone in the Rediesel Wrench can read or write, so we use messages like these to communicate most of the time.",
  ui_story_5040_50401202_69_dialog_content = "It really worked...",
  ui_story_5040_50401202_70_dialog_content = "Shree!",
  ui_story_5040_50401202_71_dialog_content = "Are you telling me these letters include every location where the Rediesel Wrench has spotted the pink sandworm?!",
  ui_story_5040_50401202_72_dialog_content = "So if we follow their notes, we should be able to find the sandworm and our friends, right?",
  ui_story_5040_50401202_73_dialog_content = "Right...",
  ui_story_5040_50401202_74_dialog_content = "So what are we waiting for? Let's start going through these letters!",
  ui_story_5040_50401202_75_dialog_content = "Nothing near Tail Street or Red-Eye Gorge.",
  ui_story_5040_50401202_76_dialog_content = "Nothing in the direction of the Illumina Federation either... Hmm?",
  ui_story_5040_50401202_77_dialog_content = "Aha! Found you!",
  ui_story_5040_50401202_78_dialog_content = "Where?!",
  ui_story_5040_50401202_79_dialog_content = "Far to the south, near an oasis deep in the desert.",
  ui_story_5040_50401202_80_dialog_content = "The place is teeming with sandworms, and the Rediesel Wrench occasionally goes there to hunt them.",
  ui_story_5040_50401202_81_dialog_content = "Apparently, one of their members saw a pink sandworm emerge from the ground not too long ago!",
  ui_story_5040_50401202_82_dialog_content = "Then let's get going! If we hurry, we might be able to track down Adonis!",
  ui_story_5040_50401202_83_dialog_content = "Hop in!",
  ui_story_5040_50401202_84_dialog_content = "<color=#e8d9bb>Vroom—</color>",
  ui_story_5040_50401202_85_dialog_content = "Bwaaaah!!!",
  ui_story_5040_50401202_86_dialog_content = "J-J-Jeriah! Slow down a little!!",
  ui_story_5040_50401202_87_dialog_content = "<size=45>What was that?</size>",
  ui_story_5040_50401202_88_dialog_content = "<size=45>I can't hear youuuuuu!!</size>",
  ui_story_5040_50401202_89_option_content = "Slow down, Jeriaaaaah!!!",
  ui_story_5040_50401202_90_dialog_content = "Slow down? We don't have time to slow down! Lives are at stake!",
  ui_story_5040_50401202_91_option_content = "Don't go past the speeeeed limiiiiiit!!!!",
  ui_story_5040_50401202_92_dialog_content = "Hahaha! You have quite a sense of humor, you know!",
  ui_story_5040_50401202_93_dialog_content = "Speed limits? In the desert?",
  ui_story_5040_50401202_94_dialog_content = "Graaaah—!",
  ui_story_5040_50401202_95_dialog_content = "We're being chased by Eclipsites!",
  ui_story_5040_50401202_96_dialog_content = "Then we'll just have to lose them!",
  ui_story_5040_50401202_97_dialog_content = "Hang on tight, little Caelestite! We're going to go even faster now!",
  ui_story_5040_50401202_98_dialog_content = "<color=#e8d9bb>Vroooom—!!!</color>",
  ui_story_5040_50401301_1_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5040_50401301_2_dialog_content = "Ahhhhhh—!",
  ui_story_5040_50401301_3_dialog_content = "That was beautiful!",
  ui_story_5040_50401301_4_dialog_content = "You could probably give the Rediesel Wrench's best drivers a run for their money!",
  ui_story_5040_50401301_5_dialog_content = "Oh, really? I'll take that as a compliment.",
  ui_story_5040_50401301_6_dialog_content = "I don't see any sign of those Eclipsites anymore... I think we lost them.",
  ui_story_5040_50401301_7_dialog_content = "I suppose that means I can let off the gas a little now.",
  ui_story_5040_50401301_8_dialog_content = "Phew... it's finally over...",
  ui_story_5040_50401301_9_dialog_content = "Are we almost there?",
  ui_story_5040_50401301_10_dialog_content = "No, we're still some distance away.",
  ui_story_5040_50401301_11_dialog_content = "The shifting dunes of the Rediesel Desert make it difficult for most people to maintain their sense of direction.",
  ui_story_5040_50401301_12_dialog_content = "But with you leading the way, I'm sure we'll be fine.",
  ui_story_5040_50401301_13_dialog_content = "Why do I feel like I've heard something like this before...?",
  ui_story_5040_50401301_14_dialog_content = "Just don't worry, do what she says, and you'll be fine!",
  ui_story_5040_50401301_15_dialog_content = "I had my reservations about you yesterday, but I think I can trust you now.",
  ui_story_5040_50401301_16_dialog_content = "When I talked to Sinsa, he said that I should trust you wholeheartedly.",
  ui_story_5040_50401301_17_dialog_content = "Is that what he said?",
  ui_story_5040_50401301_18_dialog_content = "Of course, everyone else in the Rediesel Wrench trusts you too and is grateful for everything you do.",
  ui_story_5040_50401301_19_dialog_content = "That's why it bothers me so much when you talk so poorly about them sometimes.",
  ui_story_5040_50401301_20_dialog_content = "Is that so? Hehe, thanks.",
  ui_story_5040_50401301_21_dialog_content = "That reminds me, PlayerName... I should apologize for yesterday.",
  ui_story_5040_50401301_22_dialog_content = "Huh? Why now, all of a sudden?",
  ui_story_5040_50401301_23_dialog_content = "When you asked me whether we should ask for help in looking for the others, I sort of shut you out.",
  ui_story_5040_50401301_24_dialog_content = "Oh, that? I wasn't all that upset, to be honest...",
  ui_story_5040_50401301_25_dialog_content = "I don't understand, though. Why do you resent the Rediesel Wrench so much?",
  ui_story_5040_50401301_26_dialog_content = "Yeah, I figured you knew them well, considering you were born here.",
  ui_story_5040_50401301_27_dialog_content = "Did one of those good-for-nothing guys that ignored Sinsa's orders pillage your village?",
  ui_story_5040_50401301_28_dialog_content = "No, nothing of the sort... On the contrary, my parents were once members of the Rediesel Wrench, as was I.",
  ui_story_5040_50401301_29_dialog_content = "But I cut ties with my parents and the Rediesel Wrench a long, long time ago.",
  ui_story_5040_50401301_30_dialog_content = "But why?",
  ui_story_5040_50401301_31_dialog_content = "Are you usually this curious about other people's private lives, or is it just me?",
  ui_story_5040_50401301_32_dialog_content = "I-I'm sorry, I didn't mean to pry! It's okay if you don't want to talk about it...",
  ui_story_5040_50401301_33_dialog_content = "Heheh... You really can't take a joke, can you?",
  ui_story_5040_50401301_34_dialog_content = "It isn't some deep, dark secret or anything. I just couldn't agree with their way of doing things.",
  ui_story_5040_50401301_35_dialog_content = "My parents, just like the rest of the Rediesel Wrench, valued freedom above all.",
  ui_story_5040_50401301_36_dialog_content = "For as long as I can remember, they never cared for me like normal parents. All they did was teach me a few basic desert survival skills.",
  ui_story_5040_50401301_37_dialog_content = "The rest of the time, they just left me to my own devices.",
  ui_story_5040_50401301_38_dialog_content = "All by yourself?!",
  ui_story_5040_50401301_39_dialog_content = "Is it that hard to imagine?",
  ui_story_5040_50401301_40_option_content = "It is!",
  ui_story_5040_50401301_41_dialog_content = "Yeah... I mean, even though I was trapped underground for most of my life, at least I had Soroz to keep me company.",
  ui_story_5040_50401301_42_dialog_content = "The days were long and dull, but I was never alone.",
  ui_story_5040_50401301_43_dialog_content = "That's why it's kind of hard for me to imagine a life like that...",
  ui_story_5040_50401301_44_dialog_content = "I must say, I can't help but feel a tinge of jealousy, little Caelestite.",
  ui_story_5040_50401301_45_dialog_content = "Soroz must have taken good care of you, I imagine?",
  ui_story_5040_50401301_46_dialog_content = "Yeah... Soroz has always been like family to me.",
  ui_story_5040_50401301_47_option_content = "Not really...",
  ui_story_5040_50401301_48_dialog_content = "Well, I did spend seventeen years trapped underground, with only Soroz to keep me company...",
  ui_story_5040_50401301_49_dialog_content = "Soroz was my mentor, and the only family I had.",
  ui_story_5040_50401301_50_dialog_content = "Without Soroz, I don't think I could have become the person I am today.",
  ui_story_5040_50401301_51_dialog_content = "I see... Soroz must have been quite the wonderful teacher.",
  ui_story_5040_50401301_52_dialog_content = "Absolutely!",
  ui_story_5040_50401301_53_dialog_content = "You were fortunate, but not everyone can be as fortunate as you.",
  ui_story_5040_50401301_54_dialog_content = "This desert is so vast and empty, rendering even the distance between those who dwell within it to that of an endless sea of dunes.",
  ui_story_5040_50401301_55_dialog_content = "Maybe because my parents were so used to their desert ways, they expected that I'd be able to grow up independent of their care, alone.",
  ui_story_5040_50401301_56_dialog_content = "Even when I was just a little girl, they were more concerned with living fast and free than taking care of their own daughter.",
  ui_story_5040_50401301_57_dialog_content = "There certainly are more than a few people like that in the Rediesel Wrench...",
  ui_story_5040_50401301_58_dialog_content = "They were far too overzealous when it came to their wants. It was only thanks to the charity of other people that I managed to grow up safe and sound.",
  ui_story_5040_50401301_59_dialog_content = "Everyone in the Rediesel Wrench was always kind, but I was always jealous of other kids whose parents actually took care of them.",
  ui_story_5040_50401301_60_dialog_content = "I envied that they had parents they could rely on, that they could cry and laugh uninhibitedly.",
  ui_story_5040_50401301_61_dialog_content = "And while life in the Rediesel Wrench was always filled with noise and action, I never had any personal space, constantly surrounded by people.",
  ui_story_5040_50401301_62_dialog_content = "The liveliness, the rambunctious environment; it was all too much for me. All I wanted was to be somewhere peaceful and quiet.",
  ui_story_5040_50401301_63_dialog_content = "So one day, I decided it was time to leave it all behind. The Rediesel Wrench, my parents... I didn't want to be one of them anymore.",
  ui_story_5040_50401301_64_dialog_content = "I live free as a bird, owing allegiance to no faction, committing myself to no one.",
  ui_story_5040_50401301_65_dialog_content = "As for the Courier Union, working for them is just a means to an end. It's a job to me, and nothing more.",
  ui_story_5040_50401301_66_dialog_content = "Is that really how you feel...?",
  ui_story_5040_50401301_67_dialog_content = "The first time I set foot in your office, I was so shocked to see all of those decorations.",
  ui_story_5040_50401301_68_dialog_content = "They were strewn all over the place and covered in dust from not being dusted in years.",
  ui_story_5040_50401301_69_dialog_content = "Just so you know, you can't have any of them. Those things are precious to me.",
  ui_story_5040_50401301_70_dialog_content = "I'm not interested in them at all! I'm not the type of person that wants whatever I see!",
  ui_story_5040_50401301_71_dialog_content = "All I was going to say is that even though you say you need them... You don't really care that much about them, do you?",
  ui_story_5040_50401301_72_dialog_content = "...",
  ui_story_5040_50401301_73_dialog_content = "None of those things are from the Rediesel Desert, and you use them to convince yourself you're not part of the Rediesel Wrench.",
  ui_story_5040_50401301_74_dialog_content = "But if you don't belong in the Rediesel Wrench, then where DO you belong? I don't think you know the answer to that either.",
  ui_story_5040_50401301_75_dialog_content = "(That does explain why Jeriah's office is packed with all those dusty decorations...)",
  ui_story_5040_50401301_76_dialog_content = "(Maybe she's just trying to fill a void in her heart?)",
  ui_story_5040_50401301_77_dialog_content = "Tell me, what kind of person do you think I am?",
  ui_story_5040_50401301_78_dialog_content = "You always act like you're so enigmatic and detached, but at the end of the day, you're just someone who was emotionally neglected most of your life.",
  ui_story_5040_50401301_79_dialog_content = "That's why you refuse to love anyone, and reject anyone who might care about you!",
  ui_story_5040_50401301_80_dialog_content = "You expect someone who's never been loved, someone who doesn't even know what love is, to love others?",
  ui_story_5040_50401301_81_dialog_content = "I-I didn't mean that at all...",
  ui_story_5040_50401301_82_dialog_content = "Say, Jeriah... don't you think you're being a little too hard on yourself?",
  ui_story_5040_50401301_83_dialog_content = "How do you mean?",
  ui_story_5040_50401301_84_dialog_content = "I don't believe for a second that you don't know what love is.",
  ui_story_5040_50401301_85_dialog_content = "If you really had no idea, you wouldn't have put in so much effort to help Adonis and Tara.",
  ui_story_5040_50401301_86_dialog_content = "You taught them how to sell stamps when we were in Lumopolis.",
  ui_story_5040_50401301_87_dialog_content = "Thanks to you, they were able to help Tina, and in return... She pointed us to that research lab in Illumina.",
  ui_story_5040_50401301_88_dialog_content = "And even though Tara was lying about her memory loss, you kept her secret and helped her all the same.",
  ui_story_5040_50401301_89_dialog_content = "You didn't want to see their relationship fall apart either, did you?",
  ui_story_5040_50401301_90_dialog_content = "...",
  ui_story_5040_50401301_91_dialog_content = "I just found them to be an interesting couple. It's not every day that two people from opposite ends of Astra end up together.",
  ui_story_5040_50401301_92_dialog_content = "It's as curious as if a bird and rabbit were to fall in love.",
  ui_story_5040_50401301_93_dialog_content = "You don't hear stories like that every day, much less have a chance to witness them unfold, which is why I decided to tag along with them.",
  ui_story_5040_50401301_94_dialog_content = "Then you could've just sat back and observed in silence.",
  ui_story_5040_50401301_95_dialog_content = "But that's not what happened, is it? In fact, you went out of your way to help them plenty of times, whether you choose to admit it or not.",
  ui_story_5040_50401301_96_dialog_content = "You may not have been loved wholeheartedly in the past, but someone as strong and impressive as you is bound to meet people in the future who will love you.",
  ui_story_5040_50401301_97_dialog_content = "Is that so...",
  ui_story_5040_50401301_98_dialog_content = "I'm just a courier that sticks to herself.",
  ui_story_5040_50401301_99_dialog_content = "Don't underestimate your own significance!",
  ui_story_5040_50401301_100_dialog_content = "You are a courier, and someone that the people of the desert can't do without!",
  ui_story_5040_50401301_101_dialog_content = "You matter so much more than you know!",
  ui_story_5040_50401301_102_dialog_content = "...!",
  ui_story_5040_50401301_103_dialog_content = "That's right, Jeriah! You have no idea how important you are to everyone!",
  ui_story_5040_50401301_104_dialog_content = "Life in the desert is brutal. People can only survive out here by relying on one another, and helping each other out!",
  ui_story_5040_50401301_105_dialog_content = "Each Aurorian here is like a tiny boat floating in a sea of sand. On our own, it's easy for us to lose our way, or even capsize...",
  ui_story_5040_50401301_106_dialog_content = "But when we all stick together, we can brave any storm that comes our way!",
  ui_story_5040_50401301_107_dialog_content = "And there's no one out here better at keeping us all connected than the Rediesel Desert Courier Union!",
  ui_story_5040_50401301_108_dialog_content = "...",
  ui_story_5040_50401301_109_dialog_content = "Heheheh... I think I finally understand why Adonis was willing to muster the courage to leave Northland.",
  ui_story_5040_50401301_110_dialog_content = "What?!",
  ui_story_5040_50401301_111_dialog_content = "Really? Why?",
  ui_story_5040_50401301_112_dialog_content = "... I'll just let you figure it out for yourself, little Caelestite.",
  ui_story_5040_50401301_113_dialog_content = "Don't be so vague and mysterious!",
  ui_story_5040_50401301_114_dialog_content = "Now's not the time. We have more important matters at hand...",
  ui_story_5040_50401301_115_dialog_content = "Roar—!!!",
  ui_story_5040_50401301_116_dialog_content = "Eclipsites! But where did they come from!?",
  ui_story_5040_50401301_117_dialog_content = "Eclipsites are known to take shelter in the underground burrows left by sandworms...",
  ui_story_5040_50401301_118_dialog_content = "We're getting closer to our destination.",
  ui_story_5040_50401301_119_dialog_content = "Alright! Let's wipe them all out in one go!",
  ui_story_5040_50401302_1_dialog_content = "<color=#e8d9bb>Screeech—!</color>",
  ui_story_5040_50401302_2_dialog_content = "So this is the oasis those sandworms live in?",
  ui_story_5040_50401302_3_dialog_content = "Yes. This place would be perfect for an Aurorian settlement if it weren't for all the sandworms.",
  ui_story_5040_50401302_4_dialog_content = "Because of them, it remains completely uninhabited.",
  ui_story_5040_50401302_5_dialog_content = "Maybe it's better this way, you know? After all, just look at how beautiful it is here.",
  ui_story_5040_50401302_6_dialog_content = "What if I tell you that the sands surrounding this oasis are littered with the remains of Aurorians and animals who fell victim to the sandworms?",
  ui_story_5040_50401302_7_dialog_content = "Wh-What?!",
  ui_story_5040_50401302_8_dialog_content = "In the desert, the more beautiful something is, the more likely it has a macabre side to it.",
  ui_story_5040_50401302_9_dialog_content = "Don't let your guard down just because it looks pretty. There are all kinds of dangers hiding just beneath the surface.",
  ui_story_5040_50401302_10_dialog_content = "G-Got it...",
  ui_story_5040_50401302_11_dialog_content = "It's weird, though. I don't sense any sandworms nearby... there's not a scale in sight.",
  ui_story_5040_50401302_12_dialog_content = "Could they have migrated somewhere else?",
  ui_story_5040_50401302_13_dialog_content = "There's another possibility.",
  ui_story_5040_50401302_14_dialog_content = "The pink sandworm could've chased them away to claim this oasis as its own.",
  ui_story_5040_50401302_15_dialog_content = "Then we should hurry up and search for signs of that sandworm!",
  ui_story_5040_50401302_16_dialog_content = "Looks like I have to trouble you again, Hawk.",
  ui_story_5040_50401302_17_dialog_content = "Shree!",
  ui_story_5040_50401302_18_dialog_content = "I'll use my psychic abilities to scout around too!",
  ui_story_5040_50401302_19_option_content = "Force Boost!",
  ui_story_5040_50401302_20_dialog_content = "(Please, show me something... A trace of the pink sandworm, a hint of my friends' presence... anything!)",
  ui_story_5040_50401302_21_dialog_content = "Wait, is that...?",
  ui_story_5040_50401302_22_dialog_content = "Jeriah! Tara! I think I just sensed Adonis and Kya!",
  ui_story_5040_50401302_23_dialog_content = "Really? You're even faster than Hawk...",
  ui_story_5040_50401302_24_dialog_content = "Where are they?!",
  ui_story_5040_50401302_25_dialog_content = "This way!",
  ui_story_5040_50401302_26_dialog_content = "Are you sure you sensed them? There's nothing here, except for a few bushes...",
  ui_story_5040_50401302_27_dialog_content = "My powers haven't lied to me yet! They're somewhere around here, but they seem to be unconscious... That's why I can't pinpoint their location.",
  ui_story_5040_50401302_28_dialog_content = "Hello?",
  ui_story_5040_50401302_29_dialog_content = "Kya! Adonis! Sable!",
  ui_story_5040_50401302_30_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5040_50401302_31_dialog_content = "Wait... Look at the bush over there. Those plants usually grow straight upwards, but these are lying on the ground!",
  ui_story_5040_50401302_32_dialog_content = "It looks as though someone or something did this to them...",
  ui_story_5040_50401302_33_dialog_content = "A-Adonis?!",
  ui_story_5040_50401302_34_dialog_content = "And Kya too! But where's Sable?",
  ui_story_5040_50401302_35_dialog_content = "They're still breathing... just unconscious.",
  ui_story_5040_50401302_36_dialog_content = "Adonis! Wake up!",
  ui_story_5040_50401302_37_dialog_content = "Urgh... Wh-Where am I...?",
  ui_story_5040_50401302_38_dialog_content = "Oh, thank goodness you're okay!",
  ui_story_5040_50401302_39_dialog_content = "Ow! E-Easy, Tara! My ribs are gonna break... or maybe they're already broken.",
  ui_story_5040_50401302_40_dialog_content = "Sorry, I'm just so relieved that you're okay.",
  ui_story_5040_50401302_41_dialog_content = "Do you remember how you got here? Why isn't Sable with you two?",
  ui_story_5040_50401302_42_dialog_content = "Give me a second...",
  ui_story_5040_50401302_43_dialog_content = "I remember this crazy sandstorm, and the ground sinking beneath my feet... And then, that pink sandworm charging right at me...",
  ui_story_5040_50401302_44_dialog_content = "I panicked. I didn't want to get swept away by the storm or swallowed up by the sand, so I grabbed onto one of the sandworm's scales and held on for dear life.",
  ui_story_5040_50401302_45_dialog_content = "Afterward, it carried me to a pitch-black place... I think it was a burrow of some kind?",
  ui_story_5040_50401302_46_dialog_content = "I called out to Kya and Sable, but they didn't respond.",
  ui_story_5040_50401302_47_dialog_content = "That's when the sandworm started thrashing around. I didn't dare let go, so I held on until I finally passed out.",
  ui_story_5040_50401302_48_dialog_content = "Don't you ever do that again the next time you see a sandworm, Adonis.",
  ui_story_5040_50401302_49_dialog_content = "It's one of the most dangerous things you could've done. You're incredibly lucky to be alive.",
  ui_story_5040_50401302_50_dialog_content = "I-I mean, it was my first time coming face to face with a sandworm...",
  ui_story_5040_50401302_51_dialog_content = "In any case... You're alive and safe, and that's all I could ever ask for.",
  ui_story_5040_50401302_52_dialog_content = "Yeah, thank goodness.",
  ui_story_5040_50401302_53_dialog_content = "Oh, and I have this!",
  ui_story_5040_50401302_54_dialog_content = "Is that a scale from the pink sandworm?!",
  ui_story_5040_50401302_55_dialog_content = "Yep! I managed to pry it loose from the monster while it was dragging me across the desert.",
  ui_story_5040_50401302_56_dialog_content = "I only got one of them, though... I hope it's enough.",
  ui_story_5040_50401302_57_dialog_content = "(But Tara doesn't even have amnesia... Should we tell him?)",
  ui_story_5040_50401302_58_dialog_content = "Actually, Adonis... I have something to confess.",
  ui_story_5040_50401302_59_dialog_content = "What is it?",
  ui_story_5040_50401302_60_dialog_content = "I never lost my memories in the first place.",
  ui_story_5040_50401302_61_dialog_content = "I've been pretending this whole time... I just wanted to see if you were capable of mustering the courage to leave Northland...",
  ui_story_5040_50401302_62_dialog_content = "... Tara, you really shouldn't have done this.",
  ui_story_5040_50401302_63_dialog_content = "I'm sorry...",
  ui_story_5040_50401302_64_dialog_content = "I never should have lied to you, or forced you to leave Northland, or made you face all those dangers... you have every right to be upset with me.",
  ui_story_5040_50401302_65_dialog_content = "I promise I'll never make you live anywhere you don't want to live again! I'll spend the rest of my life in Northland, if I have to...",
  ui_story_5040_50401302_66_dialog_content = "But how will you go exploring if you live up there? Traveling in Northland is pretty much impossible.",
  ui_story_5040_50401302_67_dialog_content = "I... I'll give up exploring.",
  ui_story_5040_50401302_68_dialog_content = "You're far more important to me than digging around in some ruins.",
  ui_story_5040_50401302_69_dialog_content = "...",
  ui_story_5040_50401302_70_dialog_content = "I can't believe you.",
  ui_story_5040_50401302_71_dialog_content = "What?!",
  ui_story_5040_50401401_1_dialog_content = "I... I can't even describe how angry I am at you!",
  ui_story_5040_50401401_2_dialog_content = "I'm so sorry...",
  ui_story_5040_50401401_3_dialog_content = "Listen to what I have to say before you start apologizing!",
  ui_story_5040_50401401_4_dialog_content = "I used to be such a weakling before... I couldn't even take one step outside of Northland, much less fight against Eclipsites.",
  ui_story_5040_50401401_5_dialog_content = "I don't blame you for doing what you did to help me get over my fears... After all, I'm sure you were at your wit's end.",
  ui_story_5040_50401401_6_dialog_content = "Adonis...",
  ui_story_5040_50401401_7_dialog_content = "So you aren't upset with her because she lied about having amnesia?",
  ui_story_5040_50401401_8_dialog_content = "I already suspected that she didn't lose her memories last night. I wasn't mad about it.",
  ui_story_5040_50401401_9_dialog_content = "On the contrary, I felt an overwhelming sense of relief...",
  ui_story_5040_50401401_10_dialog_content = "because I finally knew for a fact that Tara didn't forget me because she hated me.",
  ui_story_5040_50401401_11_dialog_content = "Then why are you so angry?",
  ui_story_5040_50401401_12_dialog_content = "Probably because she's compromising?",
  ui_story_5040_50401401_13_dialog_content = "Compromising how, exactly?",
  ui_story_5040_50401401_14_dialog_content = "That's precisely why, Ms. Jeriah! I'm glad someone sees where I'm coming from.",
  ui_story_5040_50401401_15_dialog_content = "Could someone please tell me what we're talking about?!",
  ui_story_5040_50401401_16_dialog_content = "I'm angry because Tara just said she was willing to give up exploring the world, just so she could live with me in Northland.",
  ui_story_5040_50401401_17_option_content = "You don't want her to feel confined.",
  ui_story_5040_50401401_18_dialog_content = "That's right!",
  ui_story_5040_50401401_19_option_content = "Because you don't like her anymore?",
  ui_story_5040_50401401_20_dialog_content = "Of course I do! Why would you even think that?!",
  ui_story_5040_50401401_21_dialog_content = "I know Tara better than anyone, so I can say without a doubt that she would never willingly move to Northland and live a quiet, peaceful life.",
  ui_story_5040_50401401_22_dialog_content = "Even though she says she's willing to live there and be with me... It's clear to me that she's giving up on her hopes and dreams!",
  ui_story_5040_50401401_23_dialog_content = "I could never let her do that to herself, especially not for me!",
  ui_story_5040_50401401_24_dialog_content = "Adonis, you...",
  ui_story_5040_50401401_25_dialog_content = "I love you, Tara. The REAL you. The one who wants to travel and explore the ruins in every corner of the world.",
  ui_story_5040_50401401_26_dialog_content = "Without you, a sheltered coward like me would never have learned so much about the world outside of Northland.",
  ui_story_5040_50401401_27_dialog_content = "I still remember hearing you describe seeing the silhouette of Illumina's defense line walls on the horizon from the Rediesel Desert.",
  ui_story_5040_50401401_28_dialog_content = "Or how, from Lumopolis, you could look down and see all the mountains and plains, as well as the passing clouds beneath your feet...",
  ui_story_5040_50401401_29_dialog_content = "Pffft... Aren't you forgetting the part where the Lumopolis soldiers mistook me for a thief?",
  ui_story_5040_50401401_30_dialog_content = "It was so chaotic... I ended up spending the entire day helping them catch the real criminal!",
  ui_story_5040_50401401_31_dialog_content = "Hahaha! That's right, and thank goodness you were fast enough to catch him! Otherwise, you would have been in real trouble!",
  ui_story_5040_50401401_32_dialog_content = "I had to work really hard to prove my innocence!",
  ui_story_5040_50401401_33_dialog_content = "Tara... We could go on for hours, but what I really want to say...",
  ui_story_5040_50401401_34_dialog_content = "is that before I met you, my entire world was as white and empty as the snow that covers Northland.",
  ui_story_5040_50401401_35_dialog_content = "You're the one who brought color into my boring, monotonous life.",
  ui_story_5040_50401401_36_dialog_content = "That's what I love most about you. I don't want to hold you back or keep you from exploring the world...",
  ui_story_5040_50401401_37_dialog_content = "which is why I'm going to do my best to get stronger and be more brave, so that I can go with you!",
  ui_story_5040_50401401_38_dialog_content = "<size=45>Adonis—!</size>",
  ui_story_5040_50401401_39_dialog_content = "Ow—! Y-You're crushing me again!!!",
  ui_story_5040_50401401_40_dialog_content = "So that's how they feel, huh?",
  ui_story_5040_50401401_41_dialog_content = "You may have the ability to read people's minds, but that doesn't mean you're capable of discerning what's in their hearts.",
  ui_story_5040_50401401_42_dialog_content = "Hey! I never said my psychic abilities were all-knowing!!",
  ui_story_5040_50401401_43_dialog_content = "Indeed, because no one is. And that's why misunderstandings exist that create chasms between people until gradually severing their connections.",
  ui_story_5040_50401401_44_dialog_content = "But if people are willing to communicate with each other, they can bridge the chasms and reconnect.",
  ui_story_5040_50401401_45_dialog_content = "And they come back stronger and more resilient than before.",
  ui_story_5040_50401401_46_dialog_content = "Ugh... What's with all the racket...?",
  ui_story_5040_50401401_47_dialog_content = "Kya! You're finally awake!",
  ui_story_5040_50401401_48_dialog_content = "... PlayerName? Jeriah? Tara and Adonis are here too... Have they finally made up?",
  ui_story_5040_50401401_49_dialog_content = "They went through a lot, but yes... they're okay now!",
  ui_story_5040_50401401_50_dialog_content = "Glad to hear it... When that sandworm swept me and Sable away, I was really worried about Adonis.",
  ui_story_5040_50401401_51_dialog_content = "That reminds me... Where is Sable?",
  ui_story_5040_50401401_52_dialog_content = "We haven't seen her... When we got here, we only found you and Adonis passed out. I can't sense her anywhere nearby either...",
  ui_story_5040_50401401_53_dialog_content = "Do you remember what happened before you lost consciousness?",
  ui_story_5040_50401401_54_dialog_content = "I... I only remember getting launched into the sky with Sable by that sandstorm... I think she managed to grab hold of the sandworm's horn.",
  ui_story_5040_50401401_55_dialog_content = "After that, the sandworm dragged us underground, and I hit my head on a rock or something... Everything went black after that.",
  ui_story_5040_50401401_56_dialog_content = "So if you and Adonis were both unconscious this whole time... who was it that hid you two here?",
  ui_story_5040_50401401_57_dialog_content = "Unless it was...",
  ui_story_5040_50401401_58_dialog_content = "Sable?!",
  ui_story_5040_50401401_59_dialog_content = "But if she's the one who hid you here, why isn't she anywhere to be seen?",
  ui_story_5040_50401401_60_dialog_content = "Perhaps she wanted to lure the sandworm away from Kya and Adonis? Or perhaps...",
  ui_story_5040_50401401_61_dialog_content = "She felt she was already at her limit.",
  ui_story_5040_50401401_62_dialog_content = "\"Limit\"? What \"limit\"? What are you two on about this time?",
  ui_story_5040_50401401_63_dialog_content = "The truth is, Sable isn't an Aurorian. Or rather, she used to be one.",
  ui_story_5040_50401401_64_dialog_content = "What?!",
  ui_story_5040_50401401_65_dialog_content = "I knew it...",
  ui_story_5040_50401401_66_dialog_content = "You don't seem surprised at all, Caelestite.",
  ui_story_5040_50401401_67_dialog_content = "I had a hunch that was the case. I just never had any proof...",
  ui_story_5040_50401401_68_dialog_content = "She was abandoned by her lover when she was still an Aurorian. In her desperation, she was drawn to the power of the Eclipsites and became the Sable we know now.",
  ui_story_5040_50401401_69_dialog_content = "But even though her body and mind were heavily affected, her consciousness had been fighting to resist the urge to fight and destroy.",
  ui_story_5040_50401401_70_dialog_content = "Not long ago, however, she told me that she couldn't hold on for much longer...",
  ui_story_5040_50401401_71_dialog_content = "How could this be...?",
  ui_story_5040_50401401_72_dialog_content = "(Why do I feel like I've seen this kind of thing happen before...?)",
  ui_story_5040_50401401_73_dialog_content = "Tell me, PlayerName. What kind of person do you think Sable is?",
  ui_story_5040_50401401_74_option_content = "A good one.",
  ui_story_5040_50401401_75_dialog_content = "She might look and act a little different, but she's been nothing but friendly to everyone. I believe she's a good person.",
  ui_story_5040_50401401_76_dialog_content = "We have to do whatever we can to help her out.",
  ui_story_5040_50401401_77_option_content = "I don't really know her...",
  ui_story_5040_50401401_78_dialog_content = "She seems really shy, so we haven't spoken much... but that doesn't stop me from believing that she's a good person!",
  ui_story_5040_50401401_79_dialog_content = "I'd totally want to be her friend if she's willing.",
  ui_story_5040_50401401_80_dialog_content = "Then let's do everything in our power to find Sable.",
  ui_story_5040_50401401_81_dialog_content = "Agreed!",
  ui_story_5040_50401401_82_dialog_content = "Shreee—!",
  ui_story_5040_50401401_83_dialog_content = "Looks like Hawk has something to tell us. Thanks, birdie.",
  ui_story_5040_50401401_84_dialog_content = "Kree, kree!",
  ui_story_5040_50401401_85_dialog_content = "You say you saw signs of Sable nearby?",
  ui_story_5040_50401401_86_dialog_content = "Where is she?!",
  ui_story_5040_50401401_87_dialog_content = "Shreee—",
  ui_story_5040_50401401_88_dialog_content = "\"Beneath our feet\"?",
  ui_story_5040_50401401_89_dialog_content = "What does that mean...?",
  ui_story_5040_50401401_90_dialog_content = "Wait, I feel something! It's faint, but I can sense a small amount of Darkflow coming closer...",
  ui_story_5040_50401401_91_dialog_content = "<color=#e8d9bb>Booom—!!!</color>",
  ui_story_5040_50401401_92_dialog_content = "Gaah! A tremor! C-Could it be the sandworm?!",
  ui_story_5040_50401401_93_dialog_content = "<size=45>Roooaaar!!!</size>",
  ui_story_5040_50401401_94_dialog_content = "Look out, Tara!",
  ui_story_5040_50401401_95_dialog_content = "Heh, I knew it was still lurking around.",
  ui_story_5040_50401401_96_dialog_content = "<size=45>Graaah!</size>",
  ui_story_5040_50401401_97_dialog_content = "It looks like something is chasing the sandworm out of its tunnel! Is that... Sable?!",
  ui_story_5040_50401401_98_dialog_content = "I... won't... let you!!!",
  ui_story_5040_50401401_99_dialog_content = "Sable?! She looks just like an—",
  ui_story_5040_50401401_100_dialog_content = "Never mind what she looks like! She's still on our side!",
  ui_story_5040_50401401_101_dialog_content = "You have to help her, PlayerName!",
  ui_story_5040_50401401_102_dialog_content = "...",
  ui_story_5040_50401401_103_dialog_content = "I got it. I'll do everything I can.",
  ui_story_5040_50401401_104_dialog_content = "I think it's time we put this pink menace in its place... Ready, little Caelestite?",
  ui_story_5040_50401401_105_dialog_content = "Will you be okay? We've been fighting back-to-back battles for a long time now, and you burned a lot of Lumina earlier...",
  ui_story_5040_50401401_106_dialog_content = "My, how considerate of you.",
  ui_story_5040_50401401_107_dialog_content = "But don't worry. I recovered some of my Lumina on the ride here.",
  ui_story_5040_50401401_108_dialog_content = "Let's go.",
  ui_story_5040_50401401_109_dialog_content = "Roger! Let's give Sable a hand with this thing!",
  ui_story_5040_50401402_1_dialog_content = "My memories... have gotten so hazy...",
  ui_story_5040_50401402_2_dialog_content = "They're like scattered pieces of film, floating through my mind, flashing incomplete images before my eyes...",
  ui_story_5040_50401402_3_dialog_content = "My earliest memory is of a desert... It's where I was born, where I grew up...",
  ui_story_5040_50401402_4_dialog_content = "Before the courier brought me that letter, I thought I was just an ordinary nobody in the world.",
  ui_story_5040_50401402_5_dialog_content = "But that letter opened my eyes to the beauty of the world beyond the desert... And was how I met \"him\"...",
  ui_story_5040_50401402_6_dialog_content = "His name escapes me now, but I do remember my love for him growing deeper with each letter we sent to one another.",
  ui_story_5040_50401402_7_dialog_content = "When I finally confessed my feelings to him, and he returned them...",
  ui_story_5040_50401402_8_dialog_content = "my heart was overflowing with joy and excitement.",
  ui_story_5040_50401402_9_dialog_content = "But that was also when his letters started coming less often.",
  ui_story_5040_50401402_10_dialog_content = "I worried that my letters weren't conveying my feelings enough, so I started sending him gifts.",
  ui_story_5040_50401402_11_dialog_content = "At first, I only sent things that were hard to come by in the desert, like flowers and ancient trinkets.",
  ui_story_5040_50401402_12_dialog_content = "My gifts grew more extravagant as time went on, until I started sending Nightium.",
  ui_story_5040_50401402_13_dialog_content = "But then, his letters became even more scarce, and in place of the tender words he used to say to me, he would only ask me to send more gifts.",
  ui_story_5040_50401402_14_dialog_content = "I couldn't understand it, but I never doubted him. In fact, I wanted to meet him. And so, he sent me an address.",
  ui_story_5040_50401402_15_dialog_content = "I gathered up my courage and set off out of the desert for the very first time.",
  ui_story_5040_50401402_16_dialog_content = "Following his letters, I went to Illumina...",
  ui_story_5040_50401402_17_dialog_content = "And then Lumopolis...",
  ui_story_5040_50401402_18_dialog_content = "And finally... to the banks of Lake Mirror.",
  ui_story_5040_50401402_19_dialog_content = "He told me that he had prepared an enormous wedding feast for us in Northland...",
  ui_story_5040_50401402_20_dialog_content = "...but he was nowhere to be seen.",
  ui_story_5040_50401402_21_dialog_content = "I was devastated, in tears, with no idea where to go or whether I could even return home.",
  ui_story_5040_50401402_22_dialog_content = "That's when a voice spoke to me.",
  ui_story_5040_50401402_23_dialog_content = "\"Take this seed,\" it said. \"It will grant you the power to make all of your dreams come true.\"",
  ui_story_5040_50401402_24_dialog_content = "I put all of my faith in that \"seed,\" but in the end... I lost everything.",
  ui_story_5040_50401402_25_dialog_content = "My memories, my ability to think... I became nothing more than a wild monster roaming the land without a purpose...",
  ui_story_5040_50401402_26_dialog_content = "Until I met Adonis and Tara. Their actions showed me that there is still love in this world.",
  ui_story_5040_50401402_27_dialog_content = "And Kya, who showed me there are people who keep their promises.",
  ui_story_5040_50401402_28_dialog_content = "And even though she acts cold and distant sometimes, Jeriah is such an incredibly dependable person.",
  ui_story_5040_50401402_29_dialog_content = "From her, I saw what it means to be carefree.",
  ui_story_5040_50401402_30_dialog_content = "That's why... with what little time I have left...",
  ui_story_5040_50401402_31_dialog_content = "I... won't let you... anywhere near them!!!",
  ui_story_5040_50401402_32_dialog_content = "<size=45>Roooaaar!!!</size>",
  ui_story_5040_50401402_33_dialog_content = "Urg—!",
  ui_story_5040_50401402_34_dialog_content = "Sable!",
  ui_story_5040_50401402_35_dialog_content = "The sandworm has Sable! Go for its head, Jeriah! We need to distract it!",
  ui_story_5040_50401402_36_dialog_content = "Don't worry... about me!",
  ui_story_5040_50401402_37_dialog_content = "Attack... weak point!",
  ui_story_5040_50401402_38_dialog_content = "...",
  ui_story_5040_50401402_39_dialog_content = "I got this.",
  ui_story_5040_50401402_40_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5040_50401402_41_dialog_content = "Roar...",
  ui_story_5040_50401402_42_dialog_content = "Agh!",
  ui_story_5040_50401402_43_dialog_content = "(The sandworm's finally down...)",
  ui_story_5040_50401402_44_dialog_content = "(Jeriah's attack targeted an old wound and pierced through its shell...)",
  ui_story_5040_50401402_45_dialog_content = "(But not before it took a huge bite out of Sable, and flung her into the air...)",
  ui_story_5040_50401402_46_dialog_content = "Sable! Are you okay?!",
  ui_story_5040_50401402_47_dialog_content = "Pain...",
  ui_story_5040_50401402_48_dialog_content = "Sable! Sable!! Snap out of it!!",
  ui_story_5040_50401402_49_dialog_content = "That wound looks serious...",
  ui_story_5040_50401402_50_dialog_content = "Even if she's as resilient as an Eclipsite, I don't think...",
  ui_story_5040_50401402_51_dialog_content = "Let me try to heal her with my Luminatics!",
  ui_story_5040_50401402_52_dialog_content = "It... It's not working! But why?!",
  ui_story_5040_50401402_53_dialog_content = "It's no use, Adonis. That wound isn't something your Luminatics can treat.",
  ui_story_5040_50401402_54_dialog_content = "Lady Jeriah! Why didn't you help her?!",
  ui_story_5040_50401402_55_dialog_content = "I only did what she asked me to do.",
  ui_story_5040_50401402_56_dialog_content = "You understand too, don't you? Even if I had saved her, she would have turned into a mindless monster before long.",
  ui_story_5040_50401402_57_dialog_content = "...",
  ui_story_5040_50401402_58_dialog_content = "Kya...",
  ui_story_5040_50401402_59_dialog_content = "Sable? I'm here, Sable!",
  ui_story_5040_50401402_60_dialog_content = "Please... don't blame... Jeriah...",
  ui_story_5040_50401402_61_dialog_content = "I didn't... want to hurt you... so I left. But then... I saw... the sandworm...",
  ui_story_5040_50401402_62_dialog_content = "I got... to see you... all of you... one last time...",
  ui_story_5040_50401402_63_dialog_content = "And... I remembered... I used to be... an Aurorian.",
  ui_story_5040_50401402_64_dialog_content = "Happy.",
  ui_story_5040_50401402_65_dialog_content = "B-But I still haven't taken you home, Sable! I still haven't fulfilled your request!",
  ui_story_5040_50401402_66_dialog_content = "Then... I'm changing... my request.",
  ui_story_5040_50401402_67_dialog_content = "Please... take this... back to... my home.",
  ui_story_5040_50401402_68_dialog_content = "Tell my family... I'm sorry...",
  ui_story_5040_50401402_69_dialog_content = "...",
  ui_story_5040_50401402_70_dialog_content = "... Courier Union Kya... at your service.",
  ui_story_5040_50401402_71_dialog_content = "The Courier Union always delivers!",
  ui_story_5040_50401402_72_dialog_content = "I'm counting... on you...",
  ui_story_5040_50401402_73_dialog_content = "Sable... No...",
  ui_story_5040_50401402_74_dialog_content = "It's okay, Kya...",
  ui_story_5040_50401402_75_dialog_content = "I-I'll go get you something to wipe your tears...",
  ui_story_5040_50401402_76_dialog_content = "...",
  ui_story_5040_50401402_77_dialog_content = "Go on and let it all out.",
  ui_story_5040_50401402_78_dialog_content = "Only then will your sorrow become the motivation you need to keep going.",
  ui_story_5040_50401402_79_dialog_content = "Jeriah...?",
  ui_story_5040_50401402_80_dialog_content = "Are you okay? Why did you leave all of a sudden?",
  ui_story_5040_50401402_81_dialog_content = "Even I need some time to compose myself now and then, little Caelestite.",
  ui_story_5040_50401402_82_dialog_content = "Oh! S-Sorry, Jeriah... I guess I just got used to seeing you dealing with everything in such a carefree manner.",
  ui_story_5040_50401402_83_dialog_content = "Heheh... Thank you for the compliment.",
  ui_story_5040_50401402_84_dialog_content = "I knew a long time ago that Sable didn't have much time left.",
  ui_story_5040_50401402_85_dialog_content = "I thought I'd be able to maintain my distance like always... but not this time, it seems.",
  ui_story_5040_50401402_86_dialog_content = "You knew about her? Why didn't you tell anyone?",
  ui_story_5040_50401402_87_dialog_content = "Why would I do that?",
  ui_story_5040_50401402_88_dialog_content = "Uh.. Well, if we had all known sooner, we might've been able to help her even more!",
  ui_story_5040_50401402_89_dialog_content = "Tara and Adonis would've been okay with it too.",
  ui_story_5040_50401402_90_dialog_content = "They might have been able to keep a secret, sure... but what about everyone else?",
  ui_story_5040_50401402_91_dialog_content = "The more people that know about a secret, the easier it is for it to come to light.",
  ui_story_5040_50401402_92_dialog_content = "There are also plenty of Aurorians in the world who wouldn't have thought twice about taking their revenge out on her.",
  ui_story_5040_50401402_93_dialog_content = "That little bird had already flown too close to the sun; there was no coming back for her.",
  ui_story_5040_50401402_94_dialog_content = "If her identity had been discovered, it would've made her precious \"final journey\" much more difficult than it was.",
  ui_story_5040_50401402_95_dialog_content = "You're right...",
  ui_story_5040_50401402_96_dialog_content = "That's why, little Caelestite, you should always remember one very important thing.",
  ui_story_5040_50401402_97_dialog_content = "Relationships with others are important, but having more of them isn't always a good thing.",
  ui_story_5040_50401402_98_dialog_content = "In fact, maintaining an appropriate level of distance and discretion is sometimes the better choice.",
  ui_story_5040_50401402_99_dialog_content = "Let your relationships be the wind beneath your comrades' wings, and not the net that binds them.",
  ui_story_5040_50401402_100_dialog_content = "I understand...",
  ui_story_5040_50401402_101_dialog_content = "I'm back, Lady Jeriah.",
  ui_story_5040_50401402_102_dialog_content = "I'm sorry that I cried for so long...",
  ui_story_5040_50401402_103_dialog_content = "What's there to be sorry about? You can't bottle up emotions like that. It's always best to let 'em out when they need to come out.",
  ui_story_5040_50401402_104_dialog_content = "Tara's right.",
  ui_story_5040_50401402_105_dialog_content = "You seem to have decided what you're going to do next, Kya.",
  ui_story_5040_50401402_106_dialog_content = "Yes. I'm done crying, because I still have something to do. Sable asked me to deliver this stamp to her home.",
  ui_story_5040_50401402_107_dialog_content = "I may not have a way to do that right now, but once everything is over... I'm going to send in a request to transfer to the Rediesel Wrench division of the Courier Union.",
  ui_story_5040_50401402_108_dialog_content = "As I work, I'll familiarize myself with the desert so I can one day find Sable's home.",
  ui_story_5040_50401402_109_dialog_content = "I'll never give up, even if I have to search every inch of Rediesel Desert.",
  ui_story_5040_50401402_110_dialog_content = "So long as it has a destination, a little bird can always finish its journey no matter the distance... Isn't that right, Kya?",
  ui_story_5040_50401402_111_dialog_content = "That's right!",
  ui_story_5040_50401402_112_dialog_content = "What about you guys?",
  ui_story_5040_50401402_113_dialog_content = "I don't have any doubts anymore. I know that I truly love Adonis with all my heart.",
  ui_story_5040_50401402_114_dialog_content = "I don't need anything else to prove it.",
  ui_story_5040_50401402_115_dialog_content = "I've made my decision too. The outside world may be dangerous, but it isn't nearly as scary as I thought it would be.",
  ui_story_5040_50401402_116_dialog_content = "The old me wasn't actually afraid of the outside world... I was afraid of the unknown.",
  ui_story_5040_50401402_117_dialog_content = "But with Tara's help, I've finally overcome my fears.",
  ui_story_5040_50401402_118_dialog_content = "I'm not ever going to ask Adonis to do crazy things beyond him anymore either.",
  ui_story_5040_50401402_119_dialog_content = "We traveled all over the continent, faced countless dangers, and experienced both pain and loss...",
  ui_story_5040_50401402_120_dialog_content = "but at least in the end, you two were finally able to understand one another.",
  ui_story_5040_50401402_121_dialog_content = "I suppose one could call this a silver lining.",
  ui_story_5040_50401402_122_dialog_content = "What would you have done if Adonis had failed to get that pink sandworm scale, Tara?",
  ui_story_5040_50401402_123_dialog_content = "Would you have kept up your little charade?",
  ui_story_5040_50401402_124_dialog_content = "About that...",
  ui_story_5040_50401402_125_dialog_content = "I'll warrant a guess that you had a backup plan.",
  ui_story_5040_50401402_126_dialog_content = "Ehehe... Nothing gets past you, Jeriah!",
  ui_story_5040_50401402_127_dialog_content = "A-Another pink sandworm scale?!",
  ui_story_5040_50401402_128_dialog_content = "This came from Sinsa's first encounter with the pink sandworm. I had to bid a fortune to buy it at an auction.",
  ui_story_5040_50401402_129_dialog_content = "You're the one who bought it?!",
  ui_story_5040_50401402_130_dialog_content = "No wonder you knew that potion was fake right off the bat... The \"rare ingredient\" that the psychic mentioned was in your hands all along!",
  ui_story_5040_50401402_131_dialog_content = "It wasn't just that... I mean, come on! A \"Potion of Unlimited Power\"? That name alone is ridiculous enough!",
  ui_story_5040_50401402_132_dialog_content = "You're the only person naive and impulsive enough that I know who would fall for something like that.",
  ui_story_5040_50401402_133_dialog_content = "I, uh... Well...",
  ui_story_5040_50401402_134_dialog_content = "In actuality, I was prepared for this outcome when I decided to fake amnesia.",
  ui_story_5040_50401402_135_dialog_content = "If Adonis failed his trial...",
  ui_story_5040_50401402_135X1_dialog_content = "I was gonna give this scale to Jeriah and ask her to come up with another way for us to get it.",
  ui_story_5040_50401402_136_dialog_content = "I see... So why did you buy something like this in the first place?",
  ui_story_5040_50401402_137_dialog_content = "...!",
  ui_story_5040_50401402_138_dialog_content = "Er, w-well... It's a super rare sandworm scale, you know! Plus it's pink, so I...",
  ui_story_5040_50401402_139_dialog_content = "I wanted to show it to Adonis... so I kind of bought it on impulse.",
  ui_story_5040_50401402_140_dialog_content = "Originally, I wanted to ask a blacksmith to fashion a wedding ring out of it for him.",
  ui_story_5040_50401402_141_dialog_content = "Oh? That's an interesting idea. It wouldn't let the sandworm scale's beauty be wasted either.",
  ui_story_5040_50401402_142_dialog_content = "But if I'm not mistaken, only the center of the scale is hard enough for the job... which means only one ring can be made out of it, right?",
  ui_story_5040_50401402_143_dialog_content = "What would you have done about your own ring if Adonis hadn't managed to pry another scale from that beast today?",
  ui_story_5040_50401402_144_dialog_content = "I... I never really thought about it.",
  ui_story_5040_50401402_145_dialog_content = "But it's not that important. I could settle for any material, to be honest.",
  ui_story_5040_50401402_146_dialog_content = "You've never been one to care about this sort of thing, but that doesn't make it okay!",
  ui_story_5040_50401402_147_dialog_content = "A marriage without a set of matching rings just isn't right! Besides...",
  ui_story_5040_50401402_148_dialog_content = "We have all the pink sandworm scales we could ever want now!",
  ui_story_5040_50401402_149_dialog_content = "<color=#e8d9bb>Screeeech—</color>",
  ui_story_5040_50401402_150_dialog_content = "Where's the sandworm? I don't see it anywhere!!",
  ui_story_5040_50401402_151_dialog_content = "Settle down, Brock. Look over there.",
  ui_story_5040_50401402_152_dialog_content = "Holy crap, it's real! The pink sandworm is real! ... But why isn't it moving?",
  ui_story_5040_50401402_153_dialog_content = "Wait... is it dead?!?!",
  ui_story_5040_50401402_154_dialog_content = "Fleur? Brock? What are you two doing here?",
  ui_story_5040_50401402_155_dialog_content = "Ah, PlayerName! Thank goodness you're not hurt.",
  ui_story_5040_50401402_156_dialog_content = "I heard from Sinsa that you and your friends were hunting a pink sandworm, so naturally, I was a bit worried.",
  ui_story_5040_50401402_157_dialog_content = "I rushed over as soon as I could, but it seems my help isn't needed anymore.",
  ui_story_5040_50401402_158_dialog_content = "I had no idea someone in the Rediesel Wrench could be so considerate. A pity, then, that you were too late.",
  ui_story_5040_50401402_159_dialog_content = "Better luck next time, I suppose... Call us if you ever need help again. We'll be there faster than you can say \"sandworm.\"",
  ui_story_5040_50401402_160_dialog_content = "Now then, if you have everything taken care of here, we should head back.",
  ui_story_5040_50401402_161_dialog_content = "You guys may have won this time, but I swear I'll hunt down an even bigger, even meaner one next time!",
  ui_story_5040_50401402_162_dialog_content = "Speaking of, you guys need our help with this thing? I hear pink sandworm scales sell for a pretty penny...",
  ui_story_5040_50401402_163_dialog_content = "This pink sandworm cost Kya's friend her life, so we can't just hand it over to you so easily.",
  ui_story_5040_50401402_164_dialog_content = "At the very least, you should ask Kya about it first.",
  ui_story_5040_50401402_165_dialog_content = "... I don't care what anyone does with this sandworm.",
  ui_story_5040_50401402_166_dialog_content = "As long as Tara and Adonis have enough scales to make their wedding rings, you guys can do whatever you want with the rest of it.",
  ui_story_5040_50401402_167_dialog_content = "I'm sure Sable would want that too.",
  ui_story_5040_50401402_168_dialog_content = "I don't know what exactly happened here, but... I sure hope you feel better soon!",
  ui_story_5040_50401402_169_dialog_content = "I promise we'll make good use of this sandworm. We won't let any of it go to waste!",
  ui_story_5040_50401402_170_dialog_content = "We're heading back to ask for help. For a sandworm this big, we're definitely going to need it.",
  ui_story_5040_50401402_171_dialog_content = "Until next time, PlayerName.",
  ui_story_5040_50401402_172_dialog_content = "Sure, see you!",
  ui_story_5040_50401402_173_dialog_content = "It's been quite a busy day, but after all of our bitter struggles, we finally managed to defeat the pink sandworm.",
  ui_story_5040_50401402_174_dialog_content = "Which means Adonis has officially passed his final trial.",
  ui_story_5040_50401402_175_dialog_content = "I just wish things could've ended differently with Sable...",
  ui_story_5040_50401402_176_dialog_content = "But it was thanks to her and everyone else that I finally came to understand Adonis' true feelings.",
  ui_story_5040_50401402_177_dialog_content = "And I got to understand Tara more, in addition to gaining the courage I finally needed to step out into the world.",
  ui_story_5040_50401402_178_dialog_content = "Since everyone seems to have gotten what they wanted, there's only one thing left to do... Allow me to award you your stamp.",
  ui_story_5040_50401402_179_dialog_content = "<color=#e8d9bb>Stamp!</color>",
  ui_story_5040_50401402_180_dialog_content = "Congratulations, you two.",
  ui_story_5040_50401402_181_dialog_content = "Yeah! Congratulations!",
  ui_story_5040_50401402_182_option_content = "Congratulations!",
  ui_story_5040_50401402_183_dialog_content = "Thank you!",
  ui_story_5040_50401402_184_dialog_content = "Thanks, everyone!",
  ui_story_5040_50401402_185_dialog_content = "If it weren't for all of you, I'd still be cowering in a corner back in Northland...",
  ui_story_5040_50401402_186_dialog_content = "But you overcame your fears.",
  ui_story_5040_50401402_187_dialog_content = "Yup. I finally have the courage to accompany you for the rest of our lives.",
  ui_story_5040_50401402_188_dialog_content = "*Ahem* Not that I want to disrupt this private moment between you, but before all that, there's still something that needs to be done.",
  ui_story_5040_50401402_189_dialog_content = "...!",
  ui_story_5040_50401402_190_dialog_content = "Yes! And it's the most important thing too!",
  ui_story_5040_50401402_191_dialog_content = "Good, it looks like all the birds know what the most important, final leg of this journey is.",
  ui_story_5040_50401402_192_dialog_content = "Huh? Anyone wanna fill me in?",
  ui_story_5040_50401402_193_dialog_content = "Isn't it obvious?",
  ui_story_5040_50401402_194_dialog_content = "The wedding!",
  ui_story_5040_50401501_1_dialog_content = "<color=#e8d9bb>A few days later in Northland...</color>",
  ui_story_5040_50401501_2_dialog_content = "Adonis and Tara sure are taking their time...",
  ui_story_5040_50401501_3_dialog_content = "Achoo!",
  ui_story_5040_50401501_4_dialog_content = "It's freezing out here... How much longer do we have to wait?!",
  ui_story_5040_50401501_5_dialog_content = "Patience, little Caelestite. This is one of the most important days of their lives, so let's just give them a little more time to prepare.",
  ui_story_5040_50401501_6_dialog_content = "Fine, fine...",
  ui_story_5040_50401501_7_dialog_content = "Speaking of, this isn't the place where Adonis originally planned to hold the wedding, is it?",
  ui_story_5040_50401501_8_dialog_content = "Of course not.",
  ui_story_5040_50401501_9_dialog_content = "They have no reason to elope anymore, so it makes sense that they would want to host a larger, more conspicuous wedding.",
  ui_story_5040_50401501_10_dialog_content = "Or... do you perhaps prefer doing things the illicit way?",
  ui_story_5040_50401501_11_dialog_content = "N-No, this is perfectly fine! Now they can share their happiness with all of their friends and family without worrying!",
  ui_story_5040_50401501_12_dialog_content = "PlayerName?",
  ui_story_5040_50401501_13_dialog_content = "I didn't expect to see you here today.",
  ui_story_5040_50401501_14_dialog_content = "Hey, Novio! Are you here for the wedding too?",
  ui_story_5040_50401501_15_dialog_content = "Indeed. I received an invitation from Adonis, and it would be remiss of me not to attend.",
  ui_story_5040_50401501_16_dialog_content = "As he was my student, I'm here to extend the Winter Palace's best wishes to him and his new bride.",
  ui_story_5040_50401501_17_dialog_content = "Oh yeah, I remember Adonis' parents and Naroxel mentioning something about that!",
  ui_story_5040_50401501_18_dialog_content = "Adonis was always a cautious, introverted boy... As far as I knew, he had never set foot outside of Northland's borders.",
  ui_story_5040_50401501_19_dialog_content = "When I heard that he was marrying Tara, a young lady from the Rediesel Wrench... Well, I was surprised, to say the least.",
  ui_story_5040_50401501_20_dialog_content = "Still, Her Majesty is always pleased to see her subjects interacting with the outside world and expanding their horizons... As am I.",
  ui_story_5040_50401501_21_dialog_content = "Yup!",
  ui_story_5040_50401501_22_dialog_content = "Please give our regards to Queen Bethlehem when you return to the palace.",
  ui_story_5040_50401501_23_dialog_content = "Of course.",
  ui_story_5040_50401501_24_dialog_content = "Now if you'll excuse me, I still need to offer my wedding gift to Adonis.",
  ui_story_5040_50401501_25_dialog_content = "Sure thing. See you soon, Novio!",
  ui_story_5040_50401501_26_dialog_content = "Until next time, PlayerName.",
  ui_story_5040_50401501_27_dialog_content = "By the way, why isn't Kya here yet?",
  ui_story_5040_50401501_28_dialog_content = "She practically ordered me to stop the Colossus as we flew over Umbraton a few days ago, saying she needed to do something...",
  ui_story_5040_50401501_29_dialog_content = "She didn't hear me when I asked about it, and jumped off before I even had the chance to land Soroz properly!",
  ui_story_5040_50401501_30_dialog_content = "Does she not plan on coming to Tara and Adonis' wedding?",
  ui_story_5040_50401501_31_dialog_content = "Kya isn't one to break her promises.",
  ui_story_5040_50401501_32_dialog_content = "I... I finally made it!!!",
  ui_story_5040_50401501_33_dialog_content = "Whew... Thank goodness... I'm not too late!",
  ui_story_5040_50401501_34_dialog_content = "K-Kya?! Why are you so out of breath?",
  ui_story_5040_50401501_35_dialog_content = "Here, have some water and catch your breath. The wedding's about to start.",
  ui_story_5040_50401501_36_dialog_content = "Th... Thank you, Lady Jeriah...",
  ui_story_5040_50401501_37_dialog_content = "<color=#e8d9bb>Glug, glug, glug—</color>",
  ui_story_5040_50401501_38_dialog_content = "Ahh... I'm so glad I made it in time. I would never forgive myself if I was late for this!",
  ui_story_5040_50401501_39_dialog_content = "Where have you been these last few days, Kya?",
  ui_story_5040_50401501_40_dialog_content = "Oh yeah, I still haven't told you.",
  ui_story_5040_50401501_41_dialog_content = "Tara and Adonis asked me to take their sandworm scales to a blacksmith and have them forged into their wedding rings.",
  ui_story_5040_50401501_42_dialog_content = "Take a look!",
  ui_story_5040_50401501_43_dialog_content = "They're beautiful... You can't even tell they're made out of sandworm scales!",
  ui_story_5040_50401501_44_dialog_content = "It took the blacksmith a lot longer than he expected to forge these rings.",
  ui_story_5040_50401501_45_dialog_content = "If it weren't for this shortcut I found in the notes that Emerald lent me, I would've been late for sure!",
  ui_story_5040_50401501_46_dialog_content = "Oh? Which shortcut would that be, and why haven't I heard of it?",
  ui_story_5040_50401501_47_dialog_content = "The sky, of course! I had to fly nonstop for hours just to catch a carriage to Northland!",
  ui_story_5040_50401501_48_dialog_content = "My wings are still in so much pain...",
  ui_story_5040_50401501_49_dialog_content = "You do know that Umbraton's Courier Union would've provided you with transportation had you sent in an urgent request?",
  ui_story_5040_50401501_50_dialog_content = "What?!",
  ui_story_5040_50401501_51_dialog_content = "Why didn't anyone tell me that! There's no mention of it in Emerald's notes, either...",
  ui_story_5040_50401501_52_dialog_content = "It's a fairly new service offered by the Umbraton division. Naturally, you wouldn't find anything about it in your senior's notebook.",
  ui_story_5040_50401501_53_dialog_content = "Sigh... I suppose I still have a lot to learn about the different divisions.",
  ui_story_5040_50401501_54_dialog_content = "Still, it's great that you managed to make it here on time! We're still waiting for the ceremony to begin, so get some rest, Kya!",
  ui_story_5040_50401501_55_dialog_content = "I will!",
  ui_story_5040_50401501_56_dialog_content = "How did preparations go while I was away?",
  ui_story_5040_50401501_57_dialog_content = "Please tell me you found that so-called \"psychic\" and taught him a lesson so he doesn't swindle any more people.",
  ui_story_5040_50401501_58_dialog_content = "Heheh... Of course.",
  ui_story_5040_50401501_59_dialog_content = "We went looking for him as soon as we arrived.",
  ui_story_5040_50401501_60_dialog_content = "That's him! That's the psychic!",
  ui_story_5040_50401501_61_dialog_content = "Ah?! ... M-May I help you, kind sir?",
  ui_story_5040_50401501_62_dialog_content = "You sold me some shoddy \"magical potion\" a few days ago, but it was a total fake!",
  ui_story_5040_50401501_63_dialog_content = "Ah, yes! I remember you now...",
  ui_story_5040_50401501_64_dialog_content = "I must ask that you stop sullying my good name with your ludicrous claims, sir. I can assure you, my potions are 100 percent genuine and effective.",
  ui_story_5040_50401501_65_dialog_content = "It's made of the scale of the rare pink sandworm!",
  ui_story_5040_50401501_66_dialog_content = "And if I recall correctly, weren't you the one who came to me when my potion caused your fiancée to lose her memories?",
  ui_story_5040_50401501_67_dialog_content = "That's me, and I was making it up the entire time. Your potion had no effect on me at all.",
  ui_story_5040_50401501_68_dialog_content = "Not only that, you never even used a pink sandworm scale to brew it!",
  ui_story_5040_50401501_69_dialog_content = "O-Oh yeah? Where's your proof then?!",
  ui_story_5040_50401501_70_dialog_content = "You first! Where did you even get a pink sandworm scale in the first place?",
  ui_story_5040_50401501_71_dialog_content = "I'll have you know that I bought it at an auction not long ago! There was only one of its kind in all of Astra!",
  ui_story_5040_50401501_72_dialog_content = "Wow, what a coincidence... because I, too, happened to buy a pink sandworm scale at an auction a while back.",
  ui_story_5040_50401501_73_dialog_content = "What?!",
  ui_story_5040_50401501_74_dialog_content = "In fact, I still have the official certificate of sale from when I bought it... Care to take a look?",
  ui_story_5040_50401501_75_dialog_content = "You were the mystery buyer who ran off with the sandworm scale at that auction?!",
  ui_story_5040_50401501_76_dialog_content = "My, my... Getting you to implicate yourself hardly took any effort at all.",
  ui_story_5040_50401501_77_dialog_content = "I'm not entirely familiar with how Northland punishes swindlers, but...",
  ui_story_5040_50401501_78_dialog_content = "I bet you guys don't wanna know how we punish them in the Rediesel Desert.",
  ui_story_5040_50401501_79_dialog_content = "Uh... we really don't have to hear it, thanks...",
  ui_story_5040_50401501_80_dialog_content = "I-I'm sorry!",
  ui_story_5040_50401501_81_dialog_content = "Here, you can have your money back! I'll turn myself in!",
  ui_story_5040_50401501_82_dialog_content = "That's good to hear. I'm glad everything worked out.",
  ui_story_5040_50401501_83_dialog_content = "So, what about Adonis' parents? Did they agree to the marriage?",
  ui_story_5040_50401501_84_dialog_content = "After seeing how much Adonis had changed, they didn't really have anything else to say about it.",
  ui_story_5040_50401501_85_dialog_content = "They were more than happy to approve of Tara and Adonis' marriage!",
  ui_story_5040_50401501_86_dialog_content = "Really? That's almost too good to be true!",
  ui_story_5040_50401501_87_dialog_content = "After all, they were completely against the idea of Adonis eloping with Tara before.",
  ui_story_5040_50401501_88_dialog_content = "You only think that because you failed to see how they really felt.",
  ui_story_5040_50401501_89_dialog_content = "I guess if there's one person who can see through people, it's you...",
  ui_story_5040_50401501_90_dialog_content = "If the Caelestite's powers could read people's hearts, I imagine he'd be able to as well.",
  ui_story_5040_50401501_91_dialog_content = "I-I don't use my abilities to pry into people's minds! That's completely inappropriate!",
  ui_story_5040_50401501_92_dialog_content = "The best way to understand others is to communicate with them.",
  ui_story_5040_50401501_93_dialog_content = "So what were Adonis' parents thinking back then?",
  ui_story_5040_50401501_94_dialog_content = "The same thing any ordinary mother and father would think in their position.",
  ui_story_5040_50401501_95_dialog_content = "They were simply worried that their child, who had never left Northland, would be incapable of adapting to the unfamiliar outside world.",
  ui_story_5040_50401501_96_dialog_content = "That, in turn, made them all the more unwilling to let him even set foot outside of his homeland.",
  ui_story_5040_50401501_97_dialog_content = "That sounds like a vicious cycle.",
  ui_story_5040_50401501_98_dialog_content = "That's true, which is why I had to give them a small nudge to give their son a chance.",
  ui_story_5040_50401501_99_dialog_content = "D-Don't tell me you threatened them like you did with the psychic?!",
  ui_story_5040_50401501_100_dialog_content = "Do I really seem like that kind of person to you?",
  ui_story_5040_50401501_101_dialog_content = "N-No...",
  ui_story_5040_50401501_102_dialog_content = "You have to employ different methods with different people.",
  ui_story_5040_50401501_103_dialog_content = "Adonis' parents are perfectly reasonable people. They were just reluctant to let their precious son out of their sight.",
  ui_story_5040_50401501_104_dialog_content = "All I did was point out the problem with treating him like this, and they quickly realized that letting him go was for the best.",
  ui_story_5040_50401501_105_dialog_content = "I envy him for having such parents.",
  ui_story_5040_50401501_106_dialog_content = "I didn't know you did so much behind the scenes!",
  ui_story_5040_50401501_107_dialog_content = "I just lent a hand here and there... I wanted to see how their story would end, these two lovers from opposite ends.",
  ui_story_5040_50401501_108_dialog_content = "It has quite a satisfying ending, if I do say so myself.",
  ui_story_5040_50401501_109_dialog_content = "Look, they're here!",
  ui_story_5040_50401501_110_dialog_content = "It's Adonis and Tara!",
  ui_story_5040_50401501_111_dialog_content = "Their outfits look amazing!",
  ui_story_5040_50401501_112_dialog_content = "Tara looks absolutely stunning! And Adonis... I had no idea he cleaned up so well!",
  ui_story_5040_50401501_113_dialog_content = "Congratulations, you two.",
  ui_story_5040_50401501_114_dialog_content = "Congratulations!",
  ui_story_5040_50401501_115_dialog_content = "Congratulations!",
  ui_story_5040_50401501_116_dialog_content = "Thank you!",
  ui_story_5040_50401501_117_dialog_content = "Thank you so much, everyone! Sorry to keep you all waiting!",
  ui_story_5040_50401501_118_dialog_content = "We're the luckiest newlyweds in all of Astra to have two of its greatest couriers serve as witnesses to our marriage!",
  ui_story_5040_50401501_119_dialog_content = "The feeling is mutual. Now then, let's get started, shall we?",
  ui_story_5040_50401501_120_dialog_content = "Tara, do you take Adonis to be your lawfully-wedded husband?",
  ui_story_5040_50401501_121_dialog_content = "To have and to hold from this day forward, in sickness and in health, for richer or poorer, through all tribulations—",
  ui_story_5040_50401501_122_dialog_content = "To love, honor, and accept him, now and forever, till death do you part?",
  ui_story_5040_50401501_123_dialog_content = "I do!",
  ui_story_5040_50401501_124_dialog_content = "Adonis, do you take Tara to be your lawfully-wedded wife?",
  ui_story_5040_50401501_125_dialog_content = "To have and to hold from this day forward, in sickness and in health, for richer or poorer, through all tribulations—",
  ui_story_5040_50401501_126_dialog_content = "To love, honor, and accept her, now and forever, till death do you part?",
  ui_story_5040_50401501_127_dialog_content = "I do!",
  ui_story_5040_50401501_128_dialog_content = "Your love has crossed rivers and withstood mountains of differences; it has faced all manner of obstacles and peril and lasted. Now then, my little birds...",
  ui_story_5040_50401501_129_dialog_content = "I ask that you please exchange your rings.",
  ui_story_5040_50401501_130_dialog_content = "Whew... Thank goodness the ceremony is over with!",
  ui_story_5040_50401501_131_dialog_content = "We finally got to ditch those clothes for something more comfortable!",
  ui_story_5040_50401501_132_dialog_content = "You didn't like your wedding dress?!",
  ui_story_5040_50401501_133_dialog_content = "Of course I did! We picked it out together, didn't we?",
  ui_story_5040_50401501_134_dialog_content = "It was just a little stuffy wearing it, is all... I could barely move in it!",
  ui_story_5040_50401501_135_dialog_content = "I almost fell over a few times when you were walking me up to the altar!",
  ui_story_5040_50401501_136_dialog_content = "Hahahaha! To be honest, it was a bit strange seeing you in such a flamboyant dress.",
  ui_story_5040_50401501_137_dialog_content = "Wearing your favorite clothes and doing whatever you like is always the best, isn't it?",
  ui_story_5040_50401501_138_dialog_content = "Yeah, but I gotta say, that suit really looked great on you.",
  ui_story_5040_50401501_139_dialog_content = "I'm also curious, considering formalwear is a far cry from your usual attire.",
  ui_story_5040_50401501_140_dialog_content = "How did you make yourself look so good in it?",
  ui_story_5040_50401501_141_dialog_content = "Er, actually...",
  ui_story_5040_50401501_142_dialog_content = "Adonis has been preparing for this wedding in secret for a long, long time.",
  ui_story_5040_50401501_143_dialog_content = "Father? Mother?!",
  ui_story_5040_50401501_144_dialog_content = "He'd often wait until we were asleep late at night and try it on in front of the mirror, working on his stature.",
  ui_story_5040_50401501_145_dialog_content = "This wedding meant the world to him... More than anything, he wanted to give you an unforgettable experience.",
  ui_story_5040_50401501_146_dialog_content = "Still, he would get so excited practicing that he would wake us up in the middle of the night...",
  ui_story_5040_50401501_147_dialog_content = "Wait, so you two knew all along?!",
  ui_story_5040_50401501_148_dialog_content = "Of course we did.",
  ui_story_5040_50401501_149_dialog_content = "We were never truly opposed to you getting married, son. You were always free to choose whether or not you did so, and to whom.",
  ui_story_5040_50401501_150_dialog_content = "We were only worried that you would jump headfirst into marriage without properly preparing yourself mentally and emotionally.",
  ui_story_5040_50401501_151_dialog_content = "After all, you knew practically nothing of the outside world. Even a potion-peddling con artist got the better of you!",
  ui_story_5040_50401501_152_dialog_content = "It would have been irresponsible of us to let you get married in that state!",
  ui_story_5040_50401501_153_dialog_content = "Exactly! What if, one day, you realized that the outside world wasn't for you? If you came to regret your decision to leave Northland,",
  ui_story_5040_50401501_154_dialog_content = "you would've held Tara responsible for being the reason you left.",
  ui_story_5040_50401501_155_dialog_content = "And that, my son, wouldn't have been fair to you or Tara. Do you understand now?",
  ui_story_5040_50401501_156_dialog_content = "Father... Mother... I'm sorry for being so selfish...",
  ui_story_5040_50401501_157_dialog_content = "But now I can tell you, with full certainty, that I know what the outside world is like, and even so... I still want to marry Tara.",
  ui_story_5040_50401501_158_dialog_content = "Yes, we've witnessed how you've changed, so we no longer oppose your marriage.",
  ui_story_5040_50401501_159_dialog_content = "We wish you both all of the love and happiness in the world.",
  ui_story_5040_50401501_160_dialog_content = "This isn't just our home anymore. It's Tara's home as well.",
  ui_story_5040_50401501_161_dialog_content = "While your adventures will undoubtedly take you to every corner of Astra... Never forget that Northland will always be here to welcome you back.",
  ui_story_5040_50401501_162_dialog_content = "Mother, Father... Thank you so much!",
  ui_story_5040_50401501_163_dialog_content = "From now on, we're family!",
  ui_story_5040_50401501_164_dialog_content = "<color=#e8d9bb>Two days later, aboard Soroz...</color>",
  ui_story_5040_50401501_165_dialog_content = "That adventure sure took up a lot of time...",
  ui_story_5040_50401501_166_dialog_content = "At first, I was just taking some people from the Rediesel Desert to Northland... I never expected to travel all over Astra because of it!",
  ui_story_5040_50401501_167_dialog_content = "Good thing I was able to wrap everything up before Vice and Carleen came back from vacation... I was even able to buy the fancy record player with the payment I got from Naroxel!",
  ui_story_5040_50401501_168_dialog_content = "They always help me so much, but this time I got them a surprise all by myself!",
  ui_story_5040_50401501_169_dialog_content = "We're back, PlayerName!",
  ui_story_5040_50401501_170_dialog_content = "Mooncrown Day was just as hectic as any other year, but thank goodness everything remained relatively peaceful this year.",
  ui_story_5040_50401501_171_dialog_content = "How were things while we were away?",
  ui_story_5040_50401501_172_dialog_content = "Oh, same as usual.",
  ui_story_5040_50401501_173_dialog_content = "I just flew Soroz around for a few days, and experienced Mooncrown Day in a few different places.",
  ui_story_5040_50401501_174_dialog_content = "I even took on a job from the Courier Union and made some money!",
  ui_story_5040_50401501_175_dialog_content = "I heard that! Jola asked me why I wasn't with you.",
  ui_story_5040_50401501_176_dialog_content = "A number of Lumopolis soldiers also saw you helping the local Courier Union a few days ago. You've been hard at work.",
  ui_story_5040_50401501_177_dialog_content = "Oh, it was nothing, really.",
  ui_story_5040_50401501_178_dialog_content = "I was really busy!",
  ui_story_5040_50401501_179_dialog_content = "I took on a job from the Courier Union and made some money!",
  ui_story_5040_50401501_180_dialog_content = "It was supposed to be a quick trip, but the job ended up taking a few days.",
  ui_story_5040_50401501_181_dialog_content = "I heard about that, yes. You were in Lumopolis at one point, then I think you went to Illumina?",
  ui_story_5040_50401501_182_dialog_content = "I heard you even went as far as the Rediesel Desert and Northland! That must've been quite the journey!",
  ui_story_5040_50401501_183_dialog_content = "Wait a second... Why do you two know where I've been this whole time?!",
  ui_story_5040_50401501_184_dialog_content = "Well, Soroz isn't exactly hard to miss... You draw a lot of attention wherever you fly!",
  ui_story_5040_50401501_185_dialog_content = "I guess that makes sense...",
  ui_story_5040_50401501_186_dialog_content = "Anyways, I used the payment to get you guys a little surprise!",
  ui_story_5040_50401501_187_dialog_content = "Ta-da—!",
  ui_story_5040_50401501_188_dialog_content = "Is that the record player from before?!",
  ui_story_5040_50401501_189_dialog_content = "It was fairly expensive, if I remember correctly.",
  ui_story_5040_50401501_190_dialog_content = "When we went shopping in Umbraton, I remember you two staring at it through the window for a long time.",
  ui_story_5040_50401501_191_dialog_content = "I figured you guys must have liked it a lot, so I snuck a look at the price and it genuinely shocked me.",
  ui_story_5040_50401501_192_dialog_content = "But when I thought about all the times you've helped me out, I realized I hadn't done much to show my appreciation...",
  ui_story_5040_50401501_193_dialog_content = "That's when I decided I would buy that record player for you both!",
  ui_story_5040_50401501_194_dialog_content = "I've been taking on odd jobs here and there, and this time I could finally afford it!",
  ui_story_5040_50401501_195_dialog_content = "PlayerName...",
  ui_story_5040_50401501_196_dialog_content = "There's a reason we were staring at that record player for so long...",
  ui_story_5040_50401501_197_dialog_content = "Carleen and I had been talking it over for days... We wanted to get you something special.",
  ui_story_5040_50401501_198_dialog_content = "So when we both saw that record player in Umbraton, we immediately knew it was the right choice!",
  ui_story_5040_50401501_199_dialog_content = "After all, Caelestites have always loved music, right? And what better way to enjoy it than with a high-quality record player!",
  ui_story_5040_50401501_200_dialog_content = "That's when we decided to put our money together to buy it for you.",
  ui_story_5040_50401501_201_dialog_content = "It's also the reason we went back to work for Mooncrown Day...",
  ui_story_5040_50401501_202_dialog_content = "Work...? Wait, so neither of you went on vacation?!",
  ui_story_5040_50401501_203_dialog_content = "Yep... We didn't want you to find out, so we kept it our little secret...",
  ui_story_5040_50401501_204_dialog_content = "But it was only after we arrived in Umbraton that we realized... someone had already purchased the record player.",
  ui_story_5040_50401501_205_dialog_content = "All we could do was buy a few Umbraton sweets and some new books to give you as a present.",
  ui_story_5040_50401501_206_dialog_content = "So you two didn't want that record player in the first place?!",
  ui_story_5040_50401501_207_dialog_content = "This is...",
  ui_story_5040_50401501_208_dialog_content = "It's fine! Sure, it didn't happen how we expected, but we got the record player in the end, didn't we?",
  ui_story_5040_50401501_209_dialog_content = "Not to mention a few new books and some snacks.",
  ui_story_5040_50401501_210_dialog_content = "Yeah... You're right!",
  ui_story_5040_50401501_211_dialog_content = "Come on, let's catch up over music and snacks!"
}
